update content_bodies set title = '蒜山高原ジャージー牛の乳しぼり＆アイスクリーム作り体験（真庭市）【岡山観光WEB】', description = '岡山県で人気の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや、予約・申込みに関する情報も掲載されています。' where id = 'G6XbxVHij072UYg6mNRLG';
update content_bodies set title = 'Milking Jersey Cows and Ice Cream Making Experience in Jirisan Highland (Maniwa City)【Okayama Tourism WEB】', description = 'Discover the trending experiences and tours in Okayama Prefecture! This includes immersive experience reports and information on reservations and applications.' where id = 'NxjsMYnnjajpuk_0FB2ze';
update content_bodies set title = '瀬戸内に浮かぶ貸切無人島 くじら島 KUJIRA-JIMAでグランピング（玉野市発）', description = '岡山県で話題の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや予約、申込みの情報が掲載されています。' where id = 'dKlNkeW3jIs1BBgS3wopz';
update content_bodies set title = 'Private Uninhabited Island Kujira-Jima for Glamping (from Tamano City) - Okayama Tourism WEB', description = 'Discover the trending experiences and tours in Okayama Prefecture! This site offers immersive experience reports along with reservation and application details.' where id = 't0lY3vIFDI9EQMm2J2U03';
update content_bodies set title = 'ニッポンの原風景に出会う！上山棚田コムスガイドツアー（美作市）【岡山観光WEB】', description = 'このツアーは現在休止中です（2021年3月時点）。岡山観光動画「おかやま ハレ旅」をチェックしたり、岡山県の観光・旅行情報を提供する岡山観光WEBの公式サイトを訪れることができます。' where id = 'C7MSx4PYDe0A4P9G8E8sz';
update content_bodies set title = 'Encounter the Original Scenery of Japan! Kamiyama Terraced Rice Field Coms Guide Tour (Mimasaka City) [Okayama Tourism WEB]', description = 'This tour is currently suspended (as of March 2021). For more information, you can check the Okayama tourism video ''Okayama Hare Tabi'' and visit the official Okayama Tourism WEB for travel information in Okayama Prefecture.' where id = 'sslHmJX3ooxNNbnhEGuKh';
update content_bodies set title = '地元ガイドと走る蒜山高原サイクリングツアー（真庭市）【岡山観光WEB】', description = '岡山県で人気の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや、予約・申込みに関する情報も掲載されています。観光情報を探している方に最適なサイトです。' where id = 'HeZiH7vueBI2P5x-cNGJL';
update content_bodies set title = 'Cycling Tour in Hiruzen Highlands with Local Guides (Maniwa City)【Okayama Tourism WEB】', description = 'Discover the trending experiences and tours in Okayama Prefecture! This includes immersive experience reports and information on reservations and applications.' where id = '6YobB2lf1K65vosvj2pJ6';
update content_bodies set title = '京都市観光PR映像_ショート動画⑧「宿泊施設と食事」', description = 'この動画では、京都市における宿泊施設と食事の選択肢について紹介しています。京都の魅力を伝えるために、観光客が利用できる宿泊施設の種類や、地元の料理を楽しむための食事スポットが取り上げられています。' where id = 'RNfIaczjXWupal-rJQKi_';
update content_bodies set title = 'Kyoto City Tourism PR Video - Short Video ⑧ ''Accommodation and Dining''', description = 'This video introduces the accommodation options and dining experiences available in Kyoto City.' where id = 'wQZt00ADIdZMgyRCRaa_U';
update content_bodies set title = '井倉洞アドベンチャー！断崖絶壁に現れる巨大洞窟に潜入', description = '全長1,200mの巨大鍾乳洞、井倉洞に潜入します。洞窟内は狭くなったり低くなったりしながら続き、高低差90mのアップダウンを体験できます。長い年月をかけて形成された奇岩や、洞内を流れ落ちる滝も見ることができ、自然の神秘を感じることができます。' where id = 'C0m_sAkXe0_QYuWnKZMsX';
update content_bodies set title = 'Explore the Giant Cave at Ikura Cave Adventure!', description = 'Dive into the massive 1,200-meter-long limestone cave, Ikura Cave. Experience the varying widths and heights of the cave as you navigate through its twists and turns, including a vertical drop of 90 meters. Marvel at the unique rock formations that have developed over many years and the waterfalls cascading within the cave.' where id = 'QaHvr3nGznI3QdiIuDveG';
update content_bodies set title = '満奇洞：幻想的空間をリアルに体感！', description = 'ライトアップされた幻想的な空間が広がる満奇洞の奥へ進むと、変化するLEDの灯りや滴る水音、迫る岩肌がリアルな感覚をもたらします。まるでその場にいるかのような体験ができる場所です。' where id = '7ADJtddtCv7PhUOGM0IZZ';
update content_bodies set title = 'Maki Cave: Experience a Fantastical Space in Reality!', description = 'Venture deep into the Maki Cave, where a fantastical space illuminated by changing LED lights awaits. The sound of dripping water and the looming rock formations create an immersive experience, making you feel as if you are truly there.' where id = 's-ctRZoKZE2gOAGepUask';
update content_bodies set title = '岡山の旅なら叶う！ 贅沢＆美味な果物時間', description = '晴れの国岡山はおいしい国でもあり、特に白桃やぶどうは全国屈指の生産量を誇ります。夏から秋にかけては“くだもの王国”としての魅力が発揮され、果樹農園での収穫体験や街のお店での絶品フルーツメニューが楽しめます。贅沢で美味しい時間が待っている岡山への旅を計画してみてはいかがでしょうか。' where id = 'VaO83HcSfi4y5oWVMXqgk';
update content_bodies set title = 'Experience Luxury and Delicious Fruit Time in Okayama!', description = 'Okayama, known as the ''Sunny Country,'' is also a land of delicious fruits, particularly renowned for its white peaches and grapes, which boast some of the highest production rates in Japan. From summer to autumn, the region truly shines as a ''fruit kingdom.'' Visitors can enjoy fruit-picking experiences at orchards and discover exquisite fruit dishes at local shops, promising a luxurious and delightful time. Plan your next trip to Okayama!' where id = 'wupnDVEAsjRFAFxVGUSk_';
update content_bodies set title = '【大原美術館モーニングツアー】', description = '大原美術館では、開館前に特別解説員の案内で名画を巡るモーニングツアーを開催します。このツアーは参加者専用に美術館を貸し切り、特別な体験を提供します。ツアー参加後、近隣の協力飲食店で食事をされた方には、大原美術館のノベルティがプレゼントされます。大原美術館は1930年に設立された日本初の私立西洋美術館で、エル・グレコやクロード・モネ、ルノワールなどの名画が展示されています。約3,000点の美術品を収蔵し、倉敷美観地区を訪れた際には必見の観光スポットです。' where id = 'LoxiVLRumYQ7DLNqDFhg-';
update content_bodies set title = 'Ohara Museum Morning Tour', description = 'The Ohara Museum offers a special morning tour where participants can enjoy an exclusive visit before the museum opens. Guided by a special lecturer, guests will explore renowned artworks in a private setting. After the tour, those who dine at nearby partner restaurants will receive a novelty gift from the museum. Established in 1930, the Ohara Museum is Japan''s first private Western art museum, showcasing masterpieces by artists such as El Greco, Claude Monet, and Pierre-Auguste Renoir. With a collection of around 3,000 artworks, including ancient Egyptian art and modern Japanese art, it is a must-visit spot in Kurashiki''s Bikan Historical Area.' where id = 'wknzaMWNBYOPukfDA6op7';
update content_bodies set title = '【最終】温泉 FHD', description = '説明' where id = 'mFEDluMqtAfau_mOaY7ZN';
update content_bodies set title = 'Final Onsen FHD', description = 'Description' where id = 'b1aoCkS6QoZs3IkFdVARz';
update content_bodies set title = '岡山県内初「渚の交番 ひなせうみラボ」と頭島（かしらじま）の絶景を空から見てみよう！', description = '備前市日生町・頭島に誕生した「渚の交番」は、日本の海洋文化と伝統を守ることをコンセプトに、漁協などが中心となりアマモの生育に努めてきた場所です。2024年2月1日には、ひなせうみラボの2階にレストランがオープンし、地元の旬の食材を使った料理を提供します。大きな窓からは瀬戸内海の美しい景色を楽しみながら、日生の牡蠣やチヌのフライ、魚介のアラ汁などが味わえます。春からは岡山特産の巨大魚・ヒラを使ったメニューも登場予定です。お茶だけの利用も可能で、観光客にとってもアクセスが便利な立地です。' where id = 'ZWrjxxBe1rYANdy1_eF2t';
update content_bodies set title = 'First ''Nagisa Police Box Hinase Umi Lab'' in Okayama Prefecture and a Scenic View of Kashirajima from the Sky!', description = 'The ''Nagisa Police Box'' in Hinase, Bizen City, was established with the concept of preserving Japan''s marine culture and traditions, focusing on marine education, experiences, and research. On February 1, 2024, a restaurant will open on the second floor of Hinase Umi Lab, offering dishes made from local seasonal ingredients while enjoying beautiful views of the Seto Inland Sea and its islands. The menu includes local delicacies such as oysters, fried black sea bream, and fish soup. Starting in spring, a special dish featuring the giant fish Hira, unique to Okayama, will be introduced. The restaurant also serves cakes, parfaits, and drinks, making it a great spot for tea. Located about 10 minutes from the popular ''Gomi no Ichi'' market, the lab is easily accessible via a bridge connecting it to the mainland.' where id = '6PaEaerEaR-r62QDzpHrW';
update content_bodies set title = '笠岡諸島「白石島」トレッキング体験', description = '笠岡（住吉）港から定期船で約35分（高速船で約20分）の場所にある「白石島」は、瀬戸内海国立公園の名勝地として知られています。夏のマリンレジャーやハイキングコース、弘法大師ゆかりの寺、幻想的な白石踊りなどを目的に多くの人々が訪れています。島内のハイキングコースには巨石が点在し、絶景フォトスポットが多数あるため、実際に歩いて撮影することができます。' where id = 'EtfswnhdP7-yoXaMlCtvo';
update content_bodies set title = 'Trekking Experience on Shiraishi Island, Kasaoka Islands', description = 'Shiraishi Island is located about 35 minutes by regular ferry (or 20 minutes by high-speed ferry) from Sumiyoshi Port in Kasaoka. Known as a scenic spot in Setonaikai National Park, it attracts many visitors for summer marine leisure activities, hiking trails, a temple associated with Kobo Daishi, and the enchanting Shiraishi Dance. The hiking trails on the island feature numerous large rocks and breathtaking photo spots, making it a great opportunity to walk and capture stunning images.' where id = 'dMJnyiv4aoFvpB85-uDdZ';
update content_bodies set title = '岡山、日本の桃太郎の故郷', description = '岡山は西日本の中心に位置し、京都、大阪、広島などの主要観光地へのアクセスが便利です。「晴れの国」として知られる岡山は、年間を通じて降水量が少なく、温暖な気候に恵まれています。地元の果物は、白桃やマスカット、ピオーネなど、豊かな土壌で育ち、比類のない風味と甘さを誇ります。歴史的な建物や美しい観光スポットが点在し、抹茶や着物体験を通じて日本文化を体験できます。北部では四季折々の自然景観や温泉を楽しめ、南部では瀬戸内海の美しい島々や夕日が見られます。大原美術館の世界的に有名な絵画やアートツアー、サイクリング、工場見学など、岡山ならではの魅力が満載です。独自の料理やお土産も豊富で、訪れる人々に特別な体験を提供します。' where id = 'sHmrnZZO1bEunV8bwiE6k';
update content_bodies set title = 'Okayama Japan, the home of Momotaro', description = 'Okayama, located in Western Japan, serves as a convenient hub for accessing major tourist destinations like Kyoto, Osaka, and Hiroshima. Known as the ''Land of Sunshine,'' it enjoys a mild climate and minimal rainfall year-round. The region is famous for its delicious fruits, including white peaches and Muscat grapes, which thrive in its fertile soil. Visitors can immerse themselves in Japanese history and culture through traditional experiences such as matcha tea and kimono dressing. Northern Okayama offers stunning natural landscapes and hot springs, while the southern region features beautiful islands in the Setonaikai. Unique attractions include the Ohara Museum of Art and various art tours, cycling, and factory visits. Okayama promises a memorable experience with its distinctive cuisine and local souvenirs.' where id = 'DRYqvIVvxoilpfjicXK8G';
update content_bodies set title = '岡山を探る、太陽の国', description = '岡山県は日本で温暖な晴れの日が多いことで知られています。訪れる人々は、瀬戸内海沿いの美しい風景や、地域にあるリラックスできる温泉など、自然の恵みを楽しむことができます。' where id = '-1m52q8H5XB7lvj1SX_od';
update content_bodies set title = 'Explore Okayama, the Land of Sunshine', description = 'Okayama Prefecture in Japan is renowned for its warm and sunny climate. Visitors can enjoy a variety of natural attractions, including the beautiful scenery along the Seto Inland Sea and the relaxing hot springs available in the region.' where id = 'NFnn3Bw1esW2FcY32DaeY';
update content_bodies set title = '岡山を探訪しよう、太陽の国 - デスティネーションキャンペーン版 -', description = '日本の岡山県は、温暖で晴れた日々で知られています。訪れる人々は、瀬戸内海沿いの美しい風景や、リラックスできる温泉など、自然の恵みを楽しむことができます。' where id = 'zDXsbOHHLyeQ0n9rGSPMO';
update content_bodies set title = 'Explore Okayama, the Land of Sunshine - Destination Campaign version -', description = 'Okayama Prefecture in Japan is celebrated for its warm and sunny climate. Visitors can enjoy a variety of natural attractions, including the beautiful scenery along the Seto Inland Sea and relaxing hot springs.' where id = 'DXgrbf0ySGaxGnuSh797o';
update content_bodies set title = '岡山へようこそ、太陽の国', description = 'この動画では、太陽の国として知られる岡山を紹介しています。岡山の特徴や魅力を強調しています。' where id = 'XUzM5ZkpBwi_vCPGoQurs';
update content_bodies set title = 'Welcome to Okayama, the Land of Sunshine', description = 'This video provides an introduction to Okayama, known as the Land of Sunshine. It highlights the region''s unique features and attractions.' where id = 'TCvNp26W8npNbodxdfAM2';
update content_bodies set title = '岡山観光：雲の城下町・高梁市', description = '岡山県高梁市には多くの観光スポットがあります。動画では、備中松山城のドローン撮影が行われており、この地域の美しさが紹介されています。この動画は、第4回備中たかはしPR観光動画コンテストの優秀賞作品で、堀切凡夫と坂本恒夫によって制作されました。さらなるコンテンツを楽しむために、チャンネル登録を促しています。' where id = '-aQQdwfBLQSDIgKNvM3pG';
update content_bodies set title = 'Okayama Tourism: The Castle Town in the Clouds - Takahashi City', description = 'Takahashi City in Okayama Prefecture is home to numerous tourist attractions. The video features drone footage of Bitchu Matsuyama Castle, showcasing the beauty of the area. This video is an award-winning entry from the 4th Bitchu Takahashi PR Tourism Video Contest, created by Horigiri Bonfu and Sakamoto Tsuneo. For more content, viewers are encouraged to subscribe to the channel.' where id = 'vDQzx9tl4svIihYUd0_3D';
update content_bodies set title = 'TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（60秒）', description = '「旅人が暮らしたくなる街」、玉野は瀬戸内国際芸術祭が開催される中、世界中の旅なれた旅人が訪れる港町です。ここは島々への玄関口であり、旅人が「通りすがる」場所です。その通りすがりの中で、この街に魅了され、住むことを決めた人々がいます。この動画では、旅人の心を捉える玉野の魅力を探ります。' where id = 'rm7lOf1_GK8xEnGoiWKBx';
update content_bodies set title = 'TAMANO Calling - Tamano is Calling You - Okayama Prefecture Tamano City PR Video (60 seconds)', description = 'Tamano is a port town that serves as a gateway to the islands of Setouchi, attracting seasoned travelers from around the world, especially during the Setouchi Triennale. While passing through, some travelers become captivated by the city and choose to make it their home. This video explores the charm of Tamano that enchants visitors and encourages them to consider living there.' where id = 'YfCyiKSfQ89uF5jCb-dXL';
update content_bodies set title = 'ＣＯＬＯＲＦＵＬ ＢＩＣＨＵ', description = '岡山県備中エリアは、南に瀬戸内海、北に中国山地を有し、自然が豊かです。この地域は、歴史文化や豊かな自然から生まれるグルメなど、色とりどりの魅力を持っています。観光情報が豊富な「カラフル備中」ウェブサイトをぜひご覧ください。' where id = 'XzgEMyJj6sT1Sg23Fah7C';
update content_bodies set title = 'COLORFUL BICHIU', description = 'The Bichu area in Okayama Prefecture is rich in nature, bordered by the Seto Inland Sea to the south and the Chugoku Mountains to the north. This region showcases a variety of attractions, including its historical culture and gourmet offerings nurtured by its abundant natural environment. For more tourist information, check out the ''Colorful Bichu'' website.' where id = 'BDIR9Jyox6Pl1_aMPzgI0';
update content_bodies set title = '美宙～＃夜空にも色がある～（ロングver.）', description = '「天文王国おかやま」の備中エリアでは、降りそそぐ星空を楽しむことができます。満点の星を眺めながらのキャンプや、天文台の望遠鏡で宇宙を覗く体験、花畑や夜景越しに見る星空など、備中ならではの魅力が満載です。カラフルな夜空を見つけるために、備中エリアを巡ってみませんか。動画には、道の駅笠岡ベイファーム、美星天文台、鷲羽山スカイライン、遙照山総合公園、うかん常山公園、藤波池キャンプ場、倉敷美観地区、備中松山城雲海展望台、笠岡諸島などのスポットが登場します。詳細は公式Instagramや「COLORFUL BICHU」ウェブサイトをチェックしてください。' where id = 'oWeBse_iXKxIjth5YXfF-';
update content_bodies set title = 'Bichu - #The Night Sky Has Colors (Long Version)', description = 'In the Bichu area of the ''Astronomical Kingdom Okayama'', you can enjoy a breathtaking starry sky. Whether it''s camping under a sky full of stars, observing the universe through telescopes at an observatory, or viewing the stars over flower fields and nightscapes, Bichu offers unique experiences. Why not explore the Bichu area to discover a colorful night sky? The video features various spots including: Kasakawa Bay Farm Station, Bisei Observatory, Washuzan Skyline, Yachiyo Mountain Park, Ukang Jozan Park, Fujinami Pond Campground, Kurashiki Bikan Historical Area, Bichu Matsuyama Castle Cloud Sea Observatory, and the Kasaoka Islands. For more information, check out the official Instagram and the ''COLORFUL BICHU'' website.' where id = 'UCXrjsrYTw4RjkHwJBt_I';
update content_bodies set title = '岡山、日本の桃太郎の故郷', description = '岡山は西日本の中心に位置し、京都、大阪、広島などの主要観光地へのアクセスが便利です。「晴れの国」として知られる岡山は、年間を通じて降水量が少なく、温暖な気候に恵まれています。地元の果物は、白桃やマスカット、ピオーネなど、豊かな土壌で育ち、比類のない風味と甘さを誇ります。歴史的な建物や美しい観光スポットが点在し、抹茶や着物体験を通じて日本文化を体験できます。北部では四季折々の自然景観や温泉を楽しめ、南部では瀬戸内海の美しい島々や夕日が見られます。岡山ならではの美術館やアートツアー、サイクリング、工場見学など、様々なアクティビティが楽しめます。独自の料理やお土産も豊富で、思い出に残る体験が待っています。' where id = '8SLFhioXi3kDQqPyTbsaK';
update content_bodies set title = 'Okayama Japan, the home of Momotaro', description = 'Okayama, located in Western Japan, serves as a convenient hub for accessing major tourist destinations like Kyoto, Osaka, and Hiroshima. Known as the ''Land of Sunshine,'' it enjoys a mild climate with minimal rainfall. The region is famous for its delicious fruits, including white peaches and Muscat grapes, which thrive in its fertile soil. Visitors can immerse themselves in Japanese history and culture through traditional experiences such as matcha tea and kimono dressing. Northern Okayama offers stunning natural landscapes and hot springs, while the southern area features beautiful islands in the Setonaikai. Unique attractions include the Ohara Museum of Art and various art tours, cycling, and factory visits. Okayama promises a memorable experience with its distinctive cuisine and souvenirs.' where id = 'pC7R7eE4kBuwPa2qdEX8r';
update content_bodies set title = '井原市プロモーション映像「旅立ちの地」', description = '井原市は戦国大名の先駆けである北条早雲ゆかりの地であり、ラブストーリーの舞台として注目されています。天文台や中世夢が原などの観光名所があり、観光だけでなくロケ地としてもおすすめです。井原鉄道を利用してぜひ訪れてみてください。' where id = 'gvtNNG-QsbeUZImd_GSvW';
update content_bodies set title = 'Ibara City Promotional Video ''The Land of Departure''', description = 'Ibara City, known as the birthplace of the Sengoku daimyō Hojo Sōun, serves as a backdrop for a romantic story. The city offers not only tourist attractions like the observatory and the medieval dream park but is also recommended as a filming location. Visitors are encouraged to come via the Ibara Railway.' where id = 'VpF3XyAzJHnu4yCGQOkV_';
update content_bodies set title = '岡山日本 パート1', description = 'この文章では、日本の岡山県の魅力的な観光スポットを紹介しています。特に、重要伝統的建造物群保存地区に指定されている倉敷美観地区や、日本三名園の一つである後楽園が挙げられます。また、岡山県の観光、料理、イベントに関する情報を提供する新しいウェブサイトが開設されました。訪問者はこのサイトを通じて岡山の魅力を発見することが奨励されています。' where id = 'ci2eY58aw_kdqC7oAcXe7';
update content_bodies set title = 'OKAYAMA JAPAN Part1', description = 'This text introduces the attractive tourist spots in Okayama Prefecture, Japan. Notable locations include the Kurashiki Bikan Historical Area, recognized as an Important Preservation District for Groups of Traditional Buildings, and Korakuen Garden, which is one of Japan''s Three Great Gardens. Additionally, a new website has been launched to provide information on local tourism, cuisine, and events in Okayama Prefecture. Visitors are encouraged to explore the site and discover the charm of Okayama.' where id = 'WiOw8_GkevSQIY-uFCLjs';
update content_bodies set title = 'OKAYAMA JAPAN Part2', description = 'この文章では、日本の岡山県の魅力的な観光スポットを紹介しています。特に、重要伝統的建造物群保存地区に指定されている倉敷美観地区や、日本三名園の一つである後楽園が挙げられます。また、岡山県の観光、料理、イベントに関する情報を提供する新しいウェブサイトが開設されました。訪問者はこのサイトを通じて岡山の魅力を発見することが奨励されています。' where id = 'KZE3wB2zaCf67eQ3no1jF';
update content_bodies set title = 'OKAYAMA JAPAN Part2', description = 'This text introduces the attractive tourist spots in Okayama Prefecture, Japan. Notable locations include the Kurashiki Bikan Historical Area, recognized as an Important Preservation District for Groups of Traditional Buildings, and Korakuen Garden, which is one of Japan''s Three Great Gardens. Additionally, a new website has been launched to provide information on local tourism, cuisine, and events in Okayama Prefecture. Visitors are encouraged to explore the site and discover the charm of Okayama.' where id = '0n_Bi4AVV3VTT0dkYrl7n';
