update content_bodies set title = 'OKAYAMA JAPAN Part3', description = 'This text introduces the attractive tourist spots in Okayama Prefecture, Japan. Notable locations include the Kurashiki Bikan Historical Area, recognized as an Important Preservation District for Groups of Traditional Buildings, and Korakuen Garden, which is one of Japan''s Three Great Gardens. Additionally, a new website has been launched to provide information on local tourism, cuisine, and events in Okayama Prefecture. Visitors are encouraged to explore the site and discover the charm of Okayama.' where id = 'Vnush881YX7KuT8ju-ML6';
update content_bodies set title = '岡山・日本　上集', description = 'この文章では、日本の岡山県にある魅力的な観光スポットを紹介しています。岡山県には、日本政府により国家伝統建物保存地区に指定された美しい地域や、日本三大名園の一つである岡山後楽園など、多くの観光名所があります。また、岡山県政府は、岡山の観光、美食、祭りの情報を発信する外語サイトを開設しました。ぜひサイトを訪れて、岡山を訪れることを検討してください。' where id = 'NqsXnIBCAKEGzvAS5c46u';
update content_bodies set title = 'Okayama, Japan Overview', description = 'This text introduces the charming tourist attractions in Okayama Prefecture, Japan. It highlights the beautiful areas designated by the Japanese government as national traditional building preservation districts, as well as Okayama Korakuen, one of Japan''s three great gardens. Additionally, the Okayama government has launched a foreign language website to promote tourism, food, and festival activities in Okayama. Visitors are encouraged to explore the site and consider visiting Okayama.' where id = 'ydb5rnQJCHLj2EZiAOuDT';
update content_bodies set title = '岡山・日本　中集', description = 'この文章では、日本の岡山県にある魅力的な観光スポットを紹介しています。岡山県には、日本政府により国家伝統建物保存地区に指定された美しい地域や、日本三大名園の一つである岡山後楽園など、多くの観光名所があります。また、岡山県政府は、岡山の観光、美食、祭りの情報を発信するための外国語ウェブサイトを開設しました。ぜひご覧いただき、岡山にお越しください！' where id = 'lPfryt6li7JmF4ROaTUpx';
update content_bodies set title = 'Okayama, Japan - Chushikoku', description = 'This text introduces the charming tourist attractions in Okayama Prefecture, Japan. It highlights the beautiful areas designated as national traditional building preservation districts by the Japanese government, as well as Okayama Korakuen, one of Japan''s three great gardens, among many other sightseeing spots. Additionally, the Okayama Prefectural Government has launched a foreign language website to promote Okayama''s tourism, cuisine, and festival activities. Visitors are encouraged to check it out and come to Okayama!' where id = '_AM7ASihI0YxDI4-u6AHw';
update content_bodies set title = '岡山・日本　下集', description = 'この文章では、日本の岡山県にある魅力的な観光スポットを紹介しています。岡山県には、日本政府により国家伝統建物保存地区に指定された美しい地域や、日本三大名園の一つである岡山後楽園など、多くの観光名所があります。また、岡山県政府は、岡山の「クール」な魅力を発信するための外国語サイトを開設し、観光、美食、祭りの情報を提供しています。ぜひサイトを訪れ、岡山を訪れることを検討してください。' where id = 'G1q7VCDDSQGdczyuVw4ZJ';
update content_bodies set title = 'Okayama, Japan - Lower Collection', description = 'This text introduces the charming tourist attractions in Okayama Prefecture, Japan. It highlights the beautiful areas designated by the Japanese government as traditional building preservation districts, as well as Okayama Korakuen, one of Japan''s three great gardens. The Okayama government has launched a foreign language website to promote the ''cool'' aspects of Okayama, providing information on tourism, food, and festival activities. Visitors are encouraged to explore the site and consider visiting Okayama.' where id = 'QEeY7qNM5Y37ERFxxkTvn';
