update content_bodies set title = 'Okayama, Japan: A Collection', description = 'This text introduces the charming tourist attractions in Okayama Prefecture, Japan. It highlights areas designated by the Japanese government as preservation sites for traditional architecture, as well as Okayama Korakuen, one of Japan''s three great gardens, among many other sightseeing spots.' where id = 'sXUt_9v2cNRcWiYBJMSG9';
