update content_bodies set title = '岡山ってどんなところ', description = '日本の西部に位置する「晴れの国おかやま」。今回は、晴れの国おかやまの魅力をご紹介します。' where id = 'FqzBCXM1VwV4WEkg8a_Pv';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA', description = 'Okayama, located in the western part of Japan, is known as the ''Land of Sunshine.'' This summary introduces the attractions of Okayama.' where id = 'fQfjDKfseCNntfCy30nCZ';
update content_bodies set title = '太陽の国おかやま', description = '西日本に位置する太陽の国おかやまは、観光、料理、イベントに関する情報を提供するウェブサイトを開設しました。このサイトは、岡山の魅力を紹介し、訪問者に地域を探索することを促しています。外国語話者向けに「クール岡山」を発見するためのサイトです。' where id = 'cGGB86W0LUXkHwvk_MJz_';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA', description = 'The Land of Sunshine Okayama is located in Western Japan. This website serves as an introduction to Okayama, highlighting its local tourism, cuisine, and events. It aims to promote the unique aspects of Okayama and invites visitors to explore the region. The site is designed for foreign language speakers to discover the charm of ''Cool Okayama!''' where id = 'QtIUED86hKJagFv-jfRbP';
update content_bodies set title = '晴れの国おかやま - 歴史の魅力', description = '日本の西部に位置する「晴れの国おかやま」。この文章では、晴れの国おかやまの歴史的な魅力について紹介します。おかやまの豊かな過去や文化的な重要性に焦点を当てています。' where id = 'g_nDEtgnHOPSqnvNdw_gc';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA - The Charm of History', description = 'Located in western Japan, Okayama is known as the ''Land of Sunshine.'' This piece introduces the historical charm of Okayama, highlighting its rich past and cultural significance.' where id = 'NdlRRdzWZzmRzHOSj06_M';
update content_bodies set title = '晴れの国おかやま', description = '日本の西部に位置する「晴れの国おかやま」では、情緒豊かな昔ながらの風情を残す町並み保存地区が紹介されています。ここでは、伝統的な町並みの魅力を感じることができ、訪れる人々に懐かしさを与えています。' where id = 'VOwqw7wMaW4fdiipMTwfq';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA', description = 'Located in western Japan, Okayama is known as the ''Land of Sunshine.'' This article introduces a preservation district that retains the nostalgic charm of traditional townscapes.' where id = 'o8aV491GecUqQ8xufmS3T';
update content_bodies set title = '太陽の国おかやま - 歴史的な町並みの懐かしい風景', description = '西日本に位置する太陽の国おかやまは、懐かしい歴史的な町並みを紹介しています。おかやま県に特化した新しいウェブサイトが開設され、地元の観光、料理、イベントに関する情報が提供されています。訪問者はこのサイトを通じておかやまの魅力を発見することを期待しています。' where id = 'WLAaDRutk0oEI665A1gUz';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA - The Nostalgic Scenery of Historic Townscapes', description = 'The Land of Sunshine Okayama, located in Western Japan, offers a glimpse into its nostalgic historic townscapes. A new website dedicated to Okayama Prefecture has been launched, providing information on local tourism, cuisine, and events. Visitors are encouraged to explore the site and discover the charm of Okayama.' where id = 'DsyI5VSyHO22m3g1S5G0r';
update content_bodies set title = '岡山の伝統とトレンディなエリアを探るツアー！', description = '「BASE 101%」ツアーに参加し、西粟倉村の新しいスポットを訪れましょう。ここではレストランやカフェ、いちご狩りが楽しめます。また、岡山の名物グルメである「津山ホルモンうどん」を味わい、SNSやアイドルのスライドショーで話題の「なぎ美術館（Nagi MOCA）」を訪れます。このツアーは、岡山の隠れた魅力を発見する絶好の機会です。行程には、BASE 101%までの40分のドライブ、なぎ美術館までの25分のドライブ、そして津山ホルモンうどんのランチが含まれています。' where id = 'H_tjqKskihgnHceodbfAE';
update content_bodies set title = 'OKAYAMA Explore Tour to traditional and trendy area!', description = 'Join the ''BASE 101%'' tour in Nishi Awakura-son Village, a new destination featuring a restaurant, café, and strawberry picking. Experience the local delicacy, ''Tsuyama Horumon Udon,'' known for its unique flavor, and visit the ''Nagi Museum of Contemporary Art (Nagi MOCA),'' a popular spot highlighted in social media and idol videos. This tour offers a chance to discover the hidden charms of Okayama, combining traditional and modern attractions. The itinerary includes a 40-minute drive to BASE 101%, followed by a 25-minute drive to Nagi MOCA, and a delicious lunch featuring Tsuyama Horumon Udon.' where id = '5DLekoHX97e8__D1XNqJk';
update content_bodies set title = '学生アテンダントと一緒に巡る!! ～岡山探訪ツアー２～', description = '学生が企画したユニークな観光ツアーに参加しませんか？このツアーでは、世界中からファンが訪れる伝統的な日本刀を展示する備前長船刀剣博物館を訪れます。また、岡山の「フルーツ王国」として知られる岡山フルーツパークでのいちご狩りも楽しめます。さらに、サブカゼ陶芸館での体験もあり、自分だけの陶器の土産を作ることができます。岡山駅西口から出発し、合計約145分の移動時間で、岡山の文化と自然の魅力を存分に楽しむことができます。' where id = 'aYAFqfSEFKTBEDvJ_Xwls';
update content_bodies set title = 'Let’s go around with Student Attendants!! ～OKAYAMA Explore Tour２～', description = 'Join a unique sightseeing tour designed by students in Okayama. This tour includes visits to the renowned Bizen Osafune Japanese Sword Museum, famous for its traditional Japanese swords that attract fans globally. Participants will also enjoy strawberry picking at Okayama Fruits Park, known as the ''Fruit Kingdom'' for its high-quality strawberries. Additionally, the tour features a hands-on experience at the Sabukaze Pottery Museum, where visitors can create their own pottery souvenirs. The itinerary includes travel from Okayama Station West Exit, with a total travel time of approximately 145 minutes, allowing for a rich exploration of Okayama''s cultural and natural attractions.' where id = 'x9HtgIc2pgktm_tAmW_7M';
update content_bodies set title = '岡山で雨の日に楽しむべきこと', description = '岡山は「太陽の国」として知られていますが、6月から雨季が始まります。しかし、この時期に訪れることには楽しみもあり、雨季ならではの魅力的な観光スポットがあります。特に注目すべきは、季節の花々やレストラン、ファームマーケット、カフェが楽しめる「笠岡ベイファーム」です。ここでは、春には菜の花やポピー、夏にはひまわり、秋にはコスモスが見られます。また、アート好きには「招き猫美術館」が人気で、写真スポットとしても知られています。雨の日でも、岡山の美しさと魅力を楽しむことができます。' where id = 'IEzGcyz3Dv28VEKa1hogM';
update content_bodies set title = 'Things To Do When It’s Raining in OKAYAMA, JAPAN', description = 'Okayama, known as the land of sunshine, experiences a rainy season starting in June. However, visiting during this time can be enjoyable, as there are unique attractions to explore. One notable destination is Kasaoka Bay Farm, which features seasonal flowers, a restaurant, a farm market, and a café, making it a great spot for photos. The farm showcases different flowers throughout the year, including rape blossoms and sunflowers. Another highlight is the Manekineko Museum of Art, a popular location for art enthusiasts and photo opportunities. Despite the rain, these attractions offer a chance to enjoy Okayama''s beauty and charm.' where id = 'Xp0OQOnJbHfcfVcTzh4Xn';
update content_bodies set title = '直島周辺 60秒', description = 'このコンテンツは、直島周辺の岡山、倉敷、玉野を紹介しています。サイクリングや電動自転車などのアクティビティに焦点を当て、瀬戸内エリアを探索するためのツアーガイドとしての役割を果たしています。' where id = 'J_tD7GkJahAReaU96iShZ';
update content_bodies set title = 'Around NAOSHIMA 60sec', description = 'This content highlights the regions surrounding Naoshima, including Okayama, Kurashiki, and Tamano. It emphasizes activities such as cycling and e-biking, and serves as a tour guide for exploring the Setouchi area.' where id = 'wSuieX0HsDhNJ1_A2T_pk';
update content_bodies set title = '岡山・犬島探訪ツアー！-アートとレジャーの楽園-', description = '犬島は岡山県の宝伝港から約10分の距離にある小さな島で、周囲は3.6km、面積は0.54km²です。美しいビーチがあり、キャンプやピクニックを楽しむ人々を惹きつけています。また、資格を持つガイドと共にシーカヤックを楽しむこともできます。犬島は、瀬戸内海の島々に活気をもたらす「瀬戸内トリエンナーレ」の会場の一つです。2008年にオープンした犬島精錬所美術館は、かつての精錬所の遺構を保存しています。2010年から始まった「アートハウスプロジェクト」では、現代アートが展示されています。訪問者は島の近隣を散策し、地元の人々と出会い、アートや穏やかな生活を楽しむことができます。小道が迷路のように広がっていますが、島の大きさからすぐに道を見つけることができるでしょう。犬島へのアクセスは、岡山や直島からのフェリーで可能です。' where id = 'QeqjaOYX5omHAVTA8JMLP';
update content_bodies set title = 'OKAYAMA Explore Tour to Inujima！-a paradise of art and leisure-', description = 'Inujima is a small island located about 10 minutes by boat from Hoden Port in Okayama Prefecture, with a circumference of 3.6 km and an area of 0.54 km². The island features beautiful beaches that attract campers and picnickers, as well as opportunities for sea kayaking with a qualified guide. Inujima is part of the Setouchi Triennale, which revitalizes the islands in the Seto Inland Sea. The Inujima Seirensho Art Museum, opened in 2008, preserves the remains of a former smelter, while the Art House Project, initiated in 2010, showcases various contemporary artworks. Visitors can explore the island''s neighborhoods, meet locals, and enjoy the art and tranquil lifestyle. The island''s small pathways create a maze-like experience, but its size ensures that getting lost is a brief adventure. Access to Inujima is available via ferry from Okayama and Naoshima.' where id = '696OinfhY3GEa8DuaD_oA';
update content_bodies set title = 'ナオシマ周辺 90秒', description = 'このコンテンツは、ナオシマ周辺の岡山、倉敷、玉野、小島、下津井などの地域を紹介しています。サイクリングや電動自転車ツアーなどのアクティビティに焦点を当て、瀬戸内エリアを探索するためのガイドを提供しています。' where id = 'vGOVMEXTemczfx_T4D3eK';
update content_bodies set title = 'Around NAOSHIMA 90sec', description = 'This content highlights the regions surrounding Naoshima, including Okayama, Kurashiki, Tamano, Kojima, and Shimotsui. It emphasizes activities such as cycling and e-bike tours, providing a guide for exploring the Setouchi area.' where id = '2bpcVn4fb4PrRVnpOLz_P';
update content_bodies set title = '玉野市VP　瀬戸内国際芸術祭2016夏会期・秋会期', description = 'これは岡山県玉野市の自主制作番組です。制作は平成28年12月に行われました。' where id = 'ejte-tjZ6PrIz5A2AuS5m';
update content_bodies set title = 'Tamano City VP Setouchi International Art Festival 2016 Summer and Autumn Sessions', description = 'This is a self-produced program from Tamano City, Okayama Prefecture. It was produced in December 2016.' where id = 'scCMLes39ALSdq2i-fIo3';
update content_bodies set title = 'マネキンチャレンジin玉野市立図書館・中央公民館（文化センター）', description = '岡山県玉野市のPR動画で、平成29年4月にリニューアルオープンした市立図書館・中央公民館を市民と協力してマネキンチャレンジで紹介しています。図書館を利用する感覚で楽しんでいただける内容となっています。' where id = '17avDErhO8BKR698PA3Qf';
update content_bodies set title = 'Mannequin Challenge at Tamano City Library and Central Community Center', description = 'This promotional video for Tamano City, Okayama Prefecture, showcases the Mannequin Challenge conducted in collaboration with local citizens to promote the city’s library and central community center, which reopened in April 2017. The video encourages viewers to experience the library in a unique way.' where id = '1Yw5BDFvVYT0dmLqHAbaK';
update content_bodies set title = '自転車の街たまのＰＲ動画　30秒／ダイジェスト版', description = '玉野市観光大使の渚さんと吉本芸人、玉野高校の生徒たちが共同で制作したサイクリングＰＲ動画です。高校生たちは日常生活の中で好きな場所や店舗を渚さんに紹介し、市内を巡るサイクリングコースを作成しました。動画では、渚さんが実際にサイクリングをしながら、海岸沿いや田園風景、素敵なお店など、玉野市の魅力的なスポットを紹介しています。この動画を通じて、玉野市を自転車で巡りたくなること間違いなしです。ぜひご覧ください。' where id = '7_m51s4LQXmrKTCEqCanM';
update content_bodies set title = 'Cycling PR Video of Tamano City - 30 Seconds / Digest Version', description = 'A cycling PR video has been created in collaboration with Tamano City tourism ambassador Nagisa, Yoshimoto comedians, and Tamano High School students. The students introduced their favorite places and shops in Tamano to Nagisa, and together they designed a cycling course around the city. The video features Nagisa cycling through various attractive spots, including the coastline, rural landscapes, and charming shops. It aims to inspire viewers to explore Tamano City by bike. Be sure to check it out!' where id = 'vQtbvLpghieGx4r4H4AX9';
update content_bodies set title = 'TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（15秒）', description = '「旅人が暮らしたくなる街」として知られる玉野市は、瀬戸内国際芸術祭の開催により、世界中の旅なれた旅人が訪れる場所となっています。この港町は、島々への玄関口として旅人が「通りすがる」場所ですが、その途中でこの街に魅了され、住むことを決めた人々もいます。この動画では、旅人の心を捉える玉野の魅力を、実際に住んでいる人々の声を通じて紹介しています。' where id = 'IbTOFBlynadBnewYNHnXW';
update content_bodies set title = 'TAMANO Calling - Tamano is Calling You - Okayama Prefecture Tamano City PR Video (15 seconds)', description = 'Tamano is a port town that serves as a gateway to the islands of Setouchi, attracting seasoned travelers from around the world, especially during the Setouchi Triennale. While passing through, some travelers become captivated by the city and choose to make it their home. The video invites viewers to explore the charm of Tamano through the voices of those who have fallen in love with the city.' where id = 'QA3drUxd_dC_OlgzW5gMX';
update content_bodies set title = 'TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（240秒）', description = 'この動画は、岡山県玉野市を旅人が暮らしたくなる街として紹介しています。瀬戸内国際芸術祭が開催され、世界中の旅なれた旅人が訪れる「Setouchi」地域に位置する玉野は、島々への玄関口として知られています。旅人たちは「通りすがり」にこの街に魅了され、移り住むことを決める人々がいます。動画では、玉野に移住した人々の声を紹介し、彼らが玉野を選んだ理由や好きなところを語ります。登場するのは、ガラス作家でIJUコンシェルジュの森美樹さんや、ゲストハウス「Machicado」と古本屋「ココカ古書店」の店主、カフェ「belk」のオーナーなどです。' where id = 'Ax5NrF-rWdSMwZpCVY_-w';
update content_bodies set title = 'TAMANO Calling - Tamano is Calling You - Okayama Prefecture Tamano City PR Video (240 seconds)', description = 'The video presents Tamano, a port town in Okayama Prefecture, as a desirable place for travelers to live. It highlights the Setouchi Triennale, which attracts seasoned travelers from around the world to the Setouchi region. Tamano serves as a gateway to the islands, where many travelers, while passing through, become captivated by the city and choose to settle there. The video features voices from residents who share their reasons for moving to Tamano and what they love about the city, including Miki Mori, a glass artist and IJU concierge, and the owners of local businesses like Machicado guesthouse and belk café.' where id = 'PP8jxLdN2CsXkw_FidCkt';
update content_bodies set title = 'TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（120秒）', description = '「旅人が暮らしたくなる街」として知られる玉野市は、瀬戸内国際芸術祭の開催により、世界中の旅人が訪れる場所となっています。この港町は、島々への玄関口として旅人が「通りすがる」場所ですが、その中でこの街に魅了され、住むことを決めた人々もいます。この動画では、玉野の魅力を語る彼らの声を通じて、旅人の心を捉えるこの街の魅力を探ります。' where id = 'YRxZm3dGNmR5PPgI9X6By';
update content_bodies set title = 'TAMANO Calling - Tamano is Calling You - Okayama Prefecture Tamano City PR Video (120 seconds)', description = 'Tamano is a port town that serves as a gateway to the islands of Setouchi, attracting seasoned travelers from around the world, especially during the Setouchi Triennale. While many travelers may just pass through, some have been captivated by the city''s charm and decided to make it their home. This video explores the allure of Tamano through the voices of those who have chosen to live in this enchanting city.' where id = 'MVnT5bG5b36Dk6kRyY8wU';
update content_bodies set title = 'フルサトたまの ～懐かしいこの景色～', description = 'フルサトたまのの懐かしい景色に会いに来ませんか？このスポット紹介では、天王池奥の竹林、八浜町並み保存地区、カフェが並ぶ海岸沿い、吉浦海岸などの場所を紹介しています。また、「若者版広報たまの」では、これらのスポットに加え、インスタ映えスポットやおしゃれなカフェも紹介しています。動画と共にぜひご覧ください。' where id = 'dzqlygrkEojEzHFB_0ZKw';
update content_bodies set title = 'Furusato Tamano - Nostalgic Scenery', description = 'Would you like to come and see the nostalgic scenery of Tamano? This spot introduction features several locations, including the bamboo grove at Tenno Pond, the preserved area of Yahama Town, a coastal area lined with cafes in Gokan, and Yoshihira Beach. Additionally, the ''Youth Edition of Tamano Public Relations'' booklet showcases these spots along with Instagram-worthy locations and stylish cafes. Be sure to check it out along with the accompanying video.' where id = '3cn8AC7oek1xHRkVa7qmd';
update content_bodies set title = '京都市観光PR映像_ショート動画⑨「トレイラー」', description = 'この動画は、京都市の観光を促進するためのPR映像について紹介しています。京都の魅力や観光スポットを短い時間で伝える内容となっており、視聴者に京都を訪れたくなるような印象を与えることを目的としています。' where id = 'mMsEwE3K7XBM10PEeXggK';
update content_bodies set title = 'Kyoto City Tourism PR Video - Short Video ⑨ ''Trailer''', description = 'This video introduces the Kyoto City tourism PR video.' where id = 'wpUQ-lZibBtBz9gyCkvkQ';
update content_bodies set title = '北海道サイロ展望台（雪遊び広場）', description = '実は、冬の方が楽しみがいっぱいです！スノーラフティングやバギー、その他にも様々なソリで遊ぶことができます。ぜひ、ご家族やお友達と一緒にお越しください。' where id = '1Q__Wfn5RPRG9mMJXSxo9';
update content_bodies set title = 'Hokkaido Silo Observatory (Snow Play Area)', description = 'Winter offers a lot of fun activities! You can enjoy snow rafting, buggies, and various types of sledding. We invite you to come with your family and friends.' where id = 'NOxPER16nSvyXDUqbNoa2';
update content_bodies set title = '大雲海', description = '洞爺湖は、円形の青い湖の中央に浮かぶ小さな島が特徴的です。年に数回、その湖全体が隠れるほどの大きな雲海が現れます。この地域は、過去100年間に4度の噴火を繰り返している活火山「有珠山」に囲まれています。また、「洞爺湖有珠山ジオパーク」としてユネスコの世界登録もされています。' where id = '5Pn5HwzDHHDKcEl9Ut8RO';
update content_bodies set title = 'Great Sea of Clouds', description = 'Lake Toya is characterized by a small island floating in the middle of a circular blue lake. Several times a year, a large sea of clouds appears, obscuring the entire lake. This area is surrounded by Mount Usu, an active volcano that has erupted four times over the past century. It is recognized as the ''Toya Caldera and Usu Volcano Global Geopark'' and is registered as a UNESCO World Heritage site.' where id = 'z81YyHFOjA3GX4RzYazT9';
update content_bodies set title = 'ようきたね、おかえりなさい。', description = 'この動画は「ようきたね、おかえりなさい。」について紹介しています。視聴者を温かく迎え入れるメッセージが込められており、田舎の家での心地よい雰囲気を伝えています。' where id = 'd_rtWUcxCxOPreipHTfo9';
update content_bodies set title = 'Welcome home, we have been waiting for you in Tanada House.', description = 'This video introduces ''Welcome home, we have been waiting for you in Tanada House.''' where id = 'tSZdJgeczpIGbGyygUH4D';
update content_bodies set title = '火山の精霊の守護者', description = 'この動画は「火山の精霊の守護者」を紹介しています。' where id = 'Z4ACBA5jB2sr20eOgTDxs';
update content_bodies set title = 'Guardians of the Volcanic Spirit', description = 'This video introduces Guardians of the Volcanic Spirit.' where id = '0PT2jYVZH43YEpQpg95iK';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『肉汁うどん編』', description = '埼玉県熊谷市のグルメ新CMシリーズ『肉汁うどん編』です。普段からうどんを食べることが当たり前だと思っていましたが、実は特別な体験であることに気付きました。熊谷市は本州一の小麦処として知られ、多くのうどん店が存在し、そのほとんどで『肉汁うどん』が定番メニューとなっています。この料理は、コシの強い無骨な麺が冷水でしめられ、豚肉とネギがたっぷり入った濃い醤油ベースの温かいつけ汁につけて食べられます。CMには埼玉うどん子TVの倫さんやその日のお客さまが出演しています。' where id = 'tUU4hD9IqhafgQKh9vAfW';
update content_bodies set title = 'Kumagaya City, Saitama Prefecture Gourmet CM Series ''Niku-Jiru Udon Edition''', description = 'This is the new CM series ''Niku-Jiru Udon Edition'' featuring gourmet food from Kumagaya City, Saitama Prefecture. It highlights the commonality of eating udon, which is often taken for granted, but is actually a special experience. Kumagaya City, known as the top wheat-producing area in Honshu, boasts numerous udon shops, most of which offer ''Niku-Jiru Udon'' as a staple menu item. This dish features firm, chewy noodles served with a rich soy-based dipping sauce filled with plenty of pork and green onions. The CM features appearances by Rin from Saitama Udonko TV and various customers.' where id = 'PG75ZPHULB-SFD71BnXV1';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『妻沼のいなり寿司編』', description = '埼玉県熊谷市のグルメCMシリーズ『妻沼のいなり寿司編』です。かつて利根川の舟運によって江戸文化と深く結びついていた妻沼地域には、その名残が見られます。『妻沼のいなり寿司』は200年以上変わらず愛され続けており、国宝建築を有する『妻沼聖天山』の参拝土産としても人気があります。令和4年度には文化庁により、江戸時代から続く「伝統部門」として“100年フード”に認定されました。' where id = 's7_2iCuTHXKQZhf03dt5d';
update content_bodies set title = 'Kumagaya City Gourmet CM Series: ''Tsum numa Inari Sushi Edition''', description = 'This is the ''Tsum numa Inari Sushi Edition'' of the Kumagaya City gourmet CM series. The Tsum numa area, which was once deeply connected to Edo culture through the transportation on the Tone River, still retains traces of its former prosperity. ''Tsum numa Inari Sushi'' has been loved for over 200 years without changing its form. It is also popular as a souvenir for visitors to ''Tsum numa Seitenzan,'' which is known for its national treasure architecture, often referred to as ''Saitama Nikko.'' In the 4th year of Reiwa, Tsum numa Inari Sushi was recognized as a ''100-Year Food'' in the traditional category by the Agency for Cultural Affairs, reflecting its long-standing cultural significance.' where id = 'xKOsUol8Xjew_PMSsBnTH';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『五家宝（ごかぼう）編』', description = '『五家宝』は、きな粉、米粉から作られたパフ状のたね、水あめだけで作られるシンプルなお菓子です。埼玉県の三大銘菓の一つに数えられていますが、機械による大量生産には向かず、今でも職人の手によって丁寧に作られています。『五家宝』は、令和3年度に文化庁選定の“100年フード”の伝統部門として認定され、さらに有識者特別賞も受賞しました。' where id = 'VyTRHuLtYzIypH6QyT7c1';
update content_bodies set title = 'Kumagaya City, Saitama Prefecture Gourmet CM Series ''Gokabou Edition''', description = 'The ''Gokabou'' is a simple confection made from soybean flour, puffed rice flour, and syrup. It is considered one of the three major confections of Saitama Prefecture. Unlike mass-produced snacks, Gokabou is crafted by artisans, preserving its traditional methods. In 2021, it was recognized as a ''100-Year Food'' in the traditional category by the Agency for Cultural Affairs and received a special award from experts.' where id = 'SPtNDT9nDMjg6YMvJUFRf';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『ホルモン編』', description = '埼玉県熊谷市のグルメCMシリーズ『ホルモン編』です。熊谷は食肉工場があり、新鮮な材料が手に入るため、ホルモン焼の文化が古くから盛んです。店内はモクモクの煙に包まれ、子どもからお年寄りまでが楽しんでいます。多くの店では換気を優先し、エアコンを設置せず、七輪を使った炭火焼スタイルを採用しています。年間を通じて熱気にあふれる店内は、熊谷のもう一つの熱さを表現しています。' where id = 'ZnQ_PaYQ68SBfyb5oLNMw';
update content_bodies set title = 'Kumagaya City, Saitama Prefecture Gourmet CM Series ''Hormone Edition''', description = 'This is the ''Hormone Edition'' of the gourmet CM series from Kumagaya City, Saitama Prefecture. Kumagaya, with its meat processing plants, has a long-standing culture of hormone grilling. Inside the restaurants, filled with thick smoke, people of all ages enjoy their meals. Many establishments prioritize ventilation and do not install air conditioning, opting for a charcoal grilling style using shichirin. The heat and atmosphere of these restaurants throughout the year reflect another aspect of Kumagaya''s warmth.' where id = '9gR7ea0Ww_tHROQ9Kttim';
update content_bodies set title = '【熊本県和水町】このまちの”なごみ”たち～あなたに、なごみを。～（魅力訴求編）', description = '熊本県北部に位置する和水町は、美しい四季に根付く豊かな食べ物や温かい人々、イベント、歴史など多様な魅力を持つ町です。この動画では、和水町の魅力を季節ごとに紹介しています。夏には江田船山古墳やスイカ、ぶどう、なす、火の本豚、古墳祭が登場。秋には肥後民家村や金栗四三、マラソン大会、山太郎ガネ、米、山太郎祭が紹介されます。冬には菊池川、戦国肥後国衆まつり、田中城跡、みかん、三加和温泉郷、星空が魅力です。春には手漉き和紙、和水江田川のカヌー・キャンプ場、たけのこ、花の香酒造、八つの神様が紹介されます。和水町は面積約98平方キロメートル、人口約9,000人です。' where id = '9De4qCD1yBHo2_Ujw0z0C';
update content_bodies set title = 'Nagomi Town, Kumamoto Prefecture: The ''Nagomi'' of This Town - Bringing You Peace', description = 'Nagomi Town, located in the northern part of Kumamoto Prefecture, showcases its diverse attractions rooted in the beautiful seasons, rich food, warm people, events, and history. The video highlights the town''s charm across different seasons: In summer, it features historical sites like the Eda Funayama Kofun, local foods such as watermelon, grapes, eggplants, and Hinomoto pork, along with the Kofun Festival. In autumn, it presents the Higo Minka Village, the marathon named after Kanekuri Shiso, and local delicacies like Yamataro-gane and rice. Winter attractions include the Kikuchi River, the Sengoku Higo Country Festival, and the Minami-Kawa Onsen area. Spring highlights include handmade washi paper, canoeing and camping at the Eda River, bamboo shoots, and the historical Hanano Ka Shuzou. Nagomi Town spans approximately 98 square kilometers with a population of around 9,000.' where id = 'pr6MmjbNbE0FDqeRC7JCs';
update content_bodies set title = 'NIIGATA ASMR_05 温泉篇', description = '新潟県には宿泊施設のある温泉地が144あり、全国で第3位の温泉天国です。日本海に面し、海や山、川、雪や紅葉などの雄大な自然に囲まれた温泉スポットが豊富で、さまざまな効能や泉質を楽しむことができます。湯口から溢れる湯の音や野鳥のさえずり、虫の声など、温もりの中で自然と一体となる体験をお楽しみください。' where id = 'wtpAK_3xxPj5TvLqzkD3l';
update content_bodies set title = 'NIIGATA ASMR_05 Onsen Edition', description = 'Niigata Prefecture boasts 144 hot spring areas with accommodations, ranking third in Japan for its abundance of onsen. Surrounded by the Sea of Japan, mountains, rivers, and stunning natural scenery including snow and autumn leaves, visitors can enjoy various therapeutic effects and water qualities. Experience the soothing sounds of water flowing from the hot spring outlets, the chirping of wild birds, and the sounds of insects, all while feeling a sense of unity with nature in a warm environment.' where id = 'c_d4xMYfXLeewNQgOkCtg';
update content_bodies set title = '江田船山古墳公園', description = '江田船山古墳公園は、古代の埋葬塚である古墳を特徴とする歴史的な場所です。これらの古墳は、古代日本の埋葬習慣や文化を理解する上で重要です。この公園では、訪問者がこれらの考古学的な遺跡を探索し、それに関連する歴史を学ぶ機会が提供されています。' where id = 'jeTgHSjeCazUX9kAZJYdY';
update content_bodies set title = 'Eta Funayama Kofun Park', description = 'Eta Funayama Kofun Park is a historical site that features ancient burial mounds known as kofun. These mounds are significant in understanding the burial practices and culture of ancient Japan. The park provides visitors with an opportunity to explore these archaeological sites and learn about the history associated with them.' where id = 'Y-cdMNJ0r-UbuxSoVurpV';
update content_bodies set title = '【熊本県和水町】まちとぼくとの物語～あなたに、なごみを。～（春編）', description = '熊本県和水町に住む高校三年生が主人公のドキュメンタリー映画で、来春の進学を控えた彼の1年間の軌跡を描いています。和水町の美しい四季を追いかけながら、豊かな食べ物や飲み物、温かい人々から生まれる文化やイベントをリアルに表現しています。高校生の成長と、彼を支える和水町の魅力が響き合う映像に仕上がっています。春編では、手漉き和紙やたけのこ、花の香酒造など、和水町の歴史や食文化が紹介されています。' where id = 'YrCUN381907W-lw9Ui9j6';
update content_bodies set title = 'Kumamoto Prefecture Nagomi Town: A Story Between the Town and Me - Spring Edition', description = 'This documentary-style movie features a high school senior living in Nagomi Town, Kumamoto Prefecture, as he prepares to leave for further studies outside the town next spring. The film captures his journey over the year leading up to his departure, showcasing the beautiful seasons of Nagomi Town. It highlights the rich food and drink, warm people, and cultural events that define the town. The film portrays the growth of the student and the charm of Nagomi Town, which has always supported him. The spring edition features attractions such as handmade washi paper, bamboo shoots, and Hanano Koshuzou, emphasizing the town''s history and culinary delights.' where id = 'crQGLICYxiS6sDWPuLFEb';
update content_bodies set title = '【熊本県和水町】まちとぼくとの物語～あなたに、なごみを。～（夏編）', description = '熊本県和水町に住む高校三年生が主人公のドキュメンタリーで、来春の進学を控えた彼の1年間の軌跡を追います。夏編では、和水町の美しい季節を背景に、豊かな食べ物や飲み物、温かい人々から生まれる文化やイベントをリアルに描写しています。高校生の成長と、彼を支えてきた和水町の魅力が響き合う映像に仕上げられています。夏の魅力としては、すいか、火の本豚、古墳祭が紹介されています。' where id = 'OsZ2fRNAoknE0WtPoxq3t';
update content_bodies set title = 'Kumamoto Prefecture Nagomi Town: A Story Between the Town and Me - Summer Edition', description = 'This documentary features a high school senior living in Nagomi Town, Kumamoto Prefecture, as he prepares to leave for further studies outside the town next spring. The summer edition captures his journey over the year leading up to his departure, showcasing the beautiful seasons of Nagomi Town. It highlights the rich food and drinks, warm people, and cultural events that define the town. The film portrays the growth of the student and the charm of Nagomi Town that has always supported him. The summer attractions include watermelon, Hinohontan pork, and the Kofun Festival.' where id = 'fuH1CEju8EzPFW9S1ysDW';
update content_bodies set title = '【熊本県和水町】まちとぼくとの物語～あなたに、なごみを。～（冬編）', description = '熊本県和水町に住む高校三年生が主人公のドキュメンタリー映画の冬編です。彼は来春、町外への進学を控えており、和水町を旅立つまでの1年間を追います。和水町の美しい四季を背景に、豊かな食べ物や飲み物、温かい人々が生み出す文化やイベントをリアルに描写しています。冬編では、戦国肥後国衆まつり、三加和温泉郷、星空など、和水町の魅力が紹介されます。高校生の成長と、彼を支えてきた和水町の魅力が響き合う映像に仕上がっています。' where id = '3GLi2F21rbHacUfsn_bbU';
update content_bodies set title = 'Kumamoto Prefecture Nagomi Town: A Story Between the Town and Me - Winter Edition', description = 'This documentary-style movie features a high school senior living in Nagomi Town, Kumamoto Prefecture, as he prepares to leave for further studies outside the town next spring. The film captures his journey over the year leading up to his departure, showcasing the beautiful seasons of Nagomi Town. It highlights the rich food and drink, warm culture, and events created by the local people. The winter edition focuses on the charm of Nagomi Town, featuring the Sengoku Higo Country Festival, the Mikawa Onsen area, and the starry skies. The film portrays the growth of the high school student and the unique appeal of Nagomi Town that has always supported him.' where id = 'odYE9HgfWrwI5pOzD9XlH';
update content_bodies set title = '雪育リゾートにいがたプロモーションムービー', description = '「雪育」とは、雪と触れ合う体験を通じて子どもの健やかな心身の成長を促進する考え方です。この取り組みでは、新潟のスノーリゾートの魅力を「雪育リゾートにいがた」として発信していきます。' where id = 'Ml4FRKmVSoMU1TE7ZuevO';
update content_bodies set title = 'Snow Education Resort Niigata Promotion Movie', description = 'The concept of ''snow education'' promotes the healthy growth of children''s minds and bodies through experiences that involve interacting with snow. This initiative aims to showcase the attractions of Niigata''s snow resorts under the banner of ''Snow Education Resort Niigata.''' where id = 'HqY7ZqoA8Tq4znvRRlj_t';
update content_bodies set title = 'NIIGATA ASMR_06 手しごと篇', description = '新潟には多くの名産品があり、そこには職人の丁寧な仕事や技が見え隠れしています。この動画では、笹の葉で包む笹団子の音、てぶりで盛り付けるへぎそばの心地よい音、米どころ新潟のせんべいを何度も焼き上げる音、そして高温でじっくり揚げる栃尾の油揚げの音を楽しむことができます。音を通じて新潟の味わいを体験してみませんか。' where id = '93K_03wHayvyBYgoMwwA-';
update content_bodies set title = 'NIIGATA ASMR_06 Handmade Edition', description = 'Niigata is known for its various local specialties, showcasing the craftsmanship and meticulous work of artisans. The video features the sound of wrapping ''sasa dango'' in bamboo leaves, the pleasant sound of serving ''hegi soba'' in a traditional manner, the repetitive process of baking ''senbei'' from the rice-producing region, and the careful frying of ''Tochio''s aburaage'' at high temperatures. Experience the flavors of Niigata through sound.' where id = 'e2vSAl4ivFgEJNnjdhc1F';
update content_bodies set title = '京都市観光PR映像_ショート動画⑩「モデルなし総集編」', description = 'この動画は、京都市の観光をPRする映像を紹介しています。特に、モデルを使用せずに京都の魅力を伝える内容となっており、観光地や文化、風景などが映し出されています。京都の美しさや独自の文化を感じることができる映像で、観光客にとって魅力的な情報が詰まっています。' where id = 'Jm1BIOnRIJTyhD64gG8G5';
update content_bodies set title = 'Kyoto City Tourism PR Video - Short Video Compilation Without Models', description = 'This video introduces the Kyoto City tourism PR video.' where id = 'oqFJir4c-oQCoOhWRCtnO';
update content_bodies set title = 'NIIGATA ASMR_04 雪旅篇', description = '新潟には、雪国特有の文化や習慣が多く残っています。長い冬の季節において、雪と共存し、雪を利用し、楽しむ方法を見出すことが求められます。そこには寒さに負けないたくましさや知恵、工夫が感じられます。この動画では、雪に覆われた風景の中での旅を擬似体験でき、音を吸収する雪が清々しい空気を生み出します。スノーピクニックや美人林、スキー場での体験など、さまざまなアクティビティが紹介されています。' where id = 'y5ghJkZAvXBK1UtUJ6oCA';
update content_bodies set title = 'NIIGATA ASMR_04 Snow Travel Edition', description = 'Niigata is rich in unique cultural traditions and practices that have been preserved in the snowy regions. During the long winter season, the locals coexist with snow, utilizing it and discovering ways to enjoy it. This reflects their resilience against the cold, as well as their wisdom and ingenuity. The video offers a simulated experience of traveling in this snowy land, where the landscape is blanketed in white snow that absorbs sound, creating a refreshing atmosphere in the crisp air. The video features various activities such as snow picnics, visits to beautiful forests, and experiences at ski resorts.' where id = 'w9Hrayux8Fv7ZCovou6qR';
update content_bodies set title = 'NIIGATA ASMR ダイジェスト版', description = 'NIIGATA ASMR シリーズのダイジェスト版で、トレッキング、島旅、ものづくり、雪旅、温泉の5つのテーマが収録されています。それぞれのセグメントは、新潟の独自の魅力をASMRを通じて体験できる内容となっています。各テーマの詳細は、提供されたリンクから本編を視聴することで確認できます。また、新潟のASMRスポットに関する情報は観光ウェブサイトでさらに探すことができます。' where id = 'Y_eoefITCrHn2Y7H4dWBe';
update content_bodies set title = 'NIIGATA ASMR Digest Edition', description = 'This is a digest edition of the NIIGATA ASMR series. It includes various themes such as trekking, island travel, craftsmanship, snow travel, and hot springs. Each segment showcases unique aspects of Niigata, providing a sensory experience through ASMR. The main episodes are available through the provided links, allowing viewers to explore each theme in detail. For more information on ASMR spots in Niigata, additional resources are available on the tourism website.' where id = 'mwxqjVfx2MEDSk44iC3g6';
update content_bodies set title = '【新潟旅行】新緑のドラゴンドラ/湯沢町/新潟観光', description = '日本最長のドラゴンドラで空中散歩を楽しむことができます。苗場と田代を約25分で結び、アップダウンを繰り返しながら、エメラルドグリーンに輝く神秘的な二居湖や眼下に流れる清津川などの絶景を堪能できます。また、テイクアウトコーヒー付きの苗場ドラゴンドラ往復乗車券を購入すれば、絶景を眺めながらカフェタイムを楽しむことができます。' where id = 'vauBBY3iMgdgi02zwp-QT';
update content_bodies set title = 'Niigata Travel: Fresh Green Dragon Dola / Yuzawa Town / Niigata Tourism', description = 'Experience a sky walk on Japan''s longest Dragon Dola, which connects Naeba and Tashiro in about 25 minutes while enjoying the ups and downs. Marvel at the breathtaking views of the mystical Nii Lake, shining in emerald green, and the clear Kiyotsu River flowing below. Additionally, by purchasing a round-trip ticket for the Naeba Dragon Dola with a takeout coffee, you can enjoy a café time while admiring the stunning scenery.' where id = 'SG2jmgeu-aqI9Xmt1ldU9';
update content_bodies set title = '越後平野　恵の地の夕景　新潟市', description = '新潟市を中心に広がる越後平野は、日本有数のコシヒカリの産地として知られています。信濃川と阿賀野川によって形成されたこの肥沃な土地では、夕陽が水田を照らす光景が広がり、絶景と呼ぶにふさわしい景観を持っています。春には雪解け水が引き込まれ、夏には稲が育ち緑に染まります。そして、収穫を前に頭を垂れた黄金色の田園は、遠くの弥彦山や角田山を背景に越後平野を象徴する風景となっています。' where id = '4gv_H8vzoItecFQ0gseu9';
update content_bodies set title = 'Echigo Plain: Evening Scenery of the Blessed Land in Niigata City', description = 'The Echigo Plain, centered around Niigata City, is renowned as one of Japan''s top rice-producing areas, particularly for its Koshihikari rice. This fertile land, shaped by the Shinano and Agano rivers, offers breathtaking views as the evening sun illuminates the rice fields. The scenery changes with the seasons, from the spring thaw that fills the fields with water, to the lush green of summer as the rice grows, and finally to the golden hues of the fields ready for harvest. The landscape is further characterized by the distant landmarks of Mount Yahiko and Mount Kakuda, symbolizing the beauty of the Echigo Plain.' where id = '3LxMlYyZNq0qY2ILZKyxZ';
update content_bodies set title = '関岬　潮風と人が育む佐渡牛　佐渡市', description = '佐渡はあまり知られていないが、上質な牛肉の生産地である。佐渡牛は、畜産農家の深い愛情と海洋気候により、ミネラルを豊富に含んだ牧草、そして日本海から吹く潮風に育まれ、上質なブランド牛として出荷される。関岬の放牧場は有数の佐渡牛の育成地であり、ストレスを感じることのない大自然の中で育ったブランド牛は、その土地でぜひ味わいたい一品である。' where id = '6qy4u5AulSm80qUQ-Fmzd';
update content_bodies set title = 'Sado Beef Nurtured by Sea Breeze and People at Sekimisaki, Sado City', description = 'Sado Island, though not widely known, is a producer of high-quality beef. Sado beef is nurtured by the deep affection of livestock farmers, mineral-rich pastures, and the sea breeze from the Japan Sea, making it a premium brand of beef. The grazing fields at Sekimisaki on Sado Island are among the top locations for raising Sado beef. Cattle raised in this natural environment, free from stress, offer a unique culinary experience that one should try in the region.' where id = 'WbTpg1lmEPg3IejGcE76x';
update content_bodies set title = '新潟市・福島潟の菜の花', description = '福島潟は多くの植物や野鳥が生息する水の公園です。広さ5ヘクタールの敷地には、4月上旬から5月上旬まで菜の花が一面に咲き誇ります。訪れる人々は、美しい風景を楽しむことができるでしょう。' where id = '1YJiHi5Mn_SnzBcKfg-ZZ';
update content_bodies set title = 'Niigata City - Nanohana at Fukushima-gata', description = 'Fukushima-gata is a water park that is home to many plants and wild birds. The entire 5-hectare area is covered with blooming nanohana (rapeseed flowers) from early April to early May.' where id = 'xlxCj6-DC-hbesAdFWP_A';
update content_bodies set title = '空から見た新潟県の桜名所', description = '2014年に空撮した新潟県の桜の名所をまとめた内容です。撮影スポットには、村上市の水辺の楽校や笹川流れ、新発田市の加治川治水記念公園、新潟市の上堰潟公園、鳥屋野潟公園、長岡市の悠久山公園が含まれています。' where id = 'Kkr6siOk34GuMhrWJKact';
update content_bodies set title = 'Cherry Blossom Spots in Niigata Prefecture from the Sky', description = 'This summary features cherry blossom spots in Niigata Prefecture captured in aerial photography in 2014. The filming locations include Murakami City at Mizube no Gakkou, Sakagawa Nagare, Shibata City at Kaji River Flood Control Memorial Park, Niigata City at Kamiseki Park and Toriyanogata Park, and Nagaoka City at Yuukyuu Mountain Park.' where id = 'Ex0_baiVCuv71C7dluO-f';
update content_bodies set title = '柏崎市・夢の森公園　カキツバタ', description = '里山に位置する自然公園「夢の森公園」では、5月下旬から6月にかけて1万株以上のカキツバタが咲き誇ります。湿地一面が美しい紫色に覆われ、訪れる人々に感動を与えます。自然の中での美しい風景を楽しむことができる場所です。' where id = 'TQjJGmiaJBh0jmvC5Q-WA';
update content_bodies set title = 'Kakitsubata at Yume no Mori Park, Kashiwazaki City', description = 'Yume no Mori Park is a natural park located in the Satoyama area. From late May to June, over 10,000 Kakitsubata (Iris) flowers bloom, covering the wetlands in a beautiful shade of purple.' where id = 'R0PwJt7XknJC3hEIwd159';
update content_bodies set title = '【NIIGATA-SORADORI】国営越後丘陵公園　ウインターイルミネーション　長岡市', description = '国営越後丘陵公園では、シンボルツリーである大ケヤキや、7000個のシャンパングラスを使用した高さ6メートルのシャンパングラスツリーなど、合計40万球のLEDが点灯し、幻想的な世界を演出しています。' where id = 'bRYBGIy37yGSMoqk-iy76';
update content_bodies set title = 'NIIGATA-SORADORI: National Echigo Hillside Park Winter Illumination, Nagaoka City', description = 'The park features a symbolic giant keyaki tree and a 6-meter tall champagne glass tree made from 7,000 champagne glasses, all illuminated by 400,000 LED lights, creating a fantastical world.' where id = 'pQ4NR54TeqrZUaOORRAOQ';
update content_bodies set title = '【うまさぎっしり新潟】～妙高市・上越市篇～', description = 'この篇では、新潟県の妙高市と上越市の美味しい料理に焦点を当てています。地域特有の風味や地元の名物を紹介し、豊かな食文化と新鮮な食材の豊富さを強調しています。' where id = 'tcJ6D9RsOwn3ENQ5-Pm8p';
update content_bodies set title = 'Deliciously Packed Niigata - Myoko City and Joetsu City Edition', description = 'This edition focuses on the culinary delights of Myoko City and Joetsu City in Niigata Prefecture. It highlights the unique flavors and local specialties that these areas have to offer, showcasing the rich food culture and the abundance of fresh ingredients available in the region.' where id = 'eUPaBfOSWNjT_46IF1Yg5';
update content_bodies set title = '日本の滝百選の一つ　鈴ヶ滝　村上市', description = '鈴ヶ滝は、源義経公が奥州に向かう際に立ち寄り、鑑賞したと伝えられる滝です。落差55メートル、幅10メートルの滝は、豪快な音を響かせながら壮観な景色を提供します。訪れる人々は、ブナ林の中を450メートル歩く遊歩道を通って滝にアクセスできます。' where id = 'Sy8GxAwfUmDAYKPW3rK9e';
update content_bodies set title = 'Suzugataki Falls in Murakami City - One of Japan''s Top 100 Waterfalls', description = 'Suzugataki Falls, located in Murakami City, is said to have been admired by Minamoto no Yoshitsune during his journey to Oshu. The falls have a height of 55 meters and a width of 10 meters, creating a spectacular sound and view. Visitors can enjoy a 450-meter walking path through a beech forest leading to the falls.' where id = 'vKJMw2pv9JKSTT9DWOHwj';
update content_bodies set title = '【NIIGATA-SORADORI】縮の雪さらし　一面の雪景色を彩る麻布の彩　小千谷市', description = '小千谷縮みは、小千谷市周辺で生産される麻織物です。強い糸で織られた布を雪に晒すことで、染められた麻糸はさらに鮮やかになり、色柄が引き立ちます。この過程で糸が膨らみ、織物全体がふっくらとした印象を与えます。小千谷の雪深い地での雪晒しの光景は、春を呼ぶ風物詩となっています。雪の白と色鮮やかな反物のストライプは、一見の価値があります。' where id = '5aDzo7SqHTv5mKLP41P1X';
update content_bodies set title = 'Snow Bleaching of Ojiya Chirimen: A Colorful Snowy Landscape in Ojiya City', description = 'Ojiya Chirimen is a type of hemp fabric produced in the Ojiya City area. The fabric is woven with strong threads and then exposed to snow, which enhances the dyeing of the hemp threads, making the colors more vibrant and the patterns more pronounced. This process also causes the threads to swell, giving the fabric a fluffy appearance. The sight of Ojiya Chirimen being bleached in the snow is a seasonal tradition that heralds spring in the snow-laden region of Ojiya. The contrast between the white snow and the colorful fabric creates a striking visual that is worth seeing.' where id = 'ELeK9ePXxTBiG6jDq32pr';
update content_bodies set title = '日本の原風景　秘境秋山郷の紅葉　津南町', description = '鈴木牧之が桃源郷と称した秋山郷は、信濃川の支流である中津川の上流域に点在する集落の総称で、長野県と新潟県にまたがる狭谷地帯です。紅葉シーズンには、素晴らしい景観を楽しむことができます。' where id = 'Nj9GWaHOcnGvjQ75EUYcH';
update content_bodies set title = 'Autumn Foliage in Akiyamago, a Hidden Gem of Japan', description = 'Akiyamago, referred to as a paradise by Suzuki Bakin, is a collection of villages located in the upper reaches of the Nakatsu River, a tributary of the Shinano River, spanning the narrow valley between Nagano and Niigata Prefectures. The autumn foliage season offers breathtaking scenery.' where id = '-1jr1n5-r-uL62KJFRgAz';
update content_bodies set title = '星峠の棚田　雲海煙る原風景　十日町市', description = '星峠の棚田は、今なお日本の原風景を残しており、四季を通じてその美しさを楽しむことができます。朝陽を映す棚田や、独特の雲海に包まれた幻想的な景観は、多くのカメラマンを惹きつけています。松之山や十日町を訪れた際には、ぜひ立ち寄りたいスポットです。' where id = 'e1bESc-TM6UePWMBcA_Qc';
update content_bodies set title = 'Hoshitoge Rice Terraces: A Scenic Landscape with Sea of Clouds in Tokamachi City', description = 'The Hoshitoge Rice Terraces in Tokamachi preserve Japan''s original landscapes. Visitors can enjoy their beauty throughout the year. The terraces, reflecting the morning sun and surrounded by unique sea of clouds, create a mesmerizing view that attracts many photographers from across the country. This spot is a must-visit when traveling to Matsunoyama or Tokamachi.' where id = '7eAUhQFkG2MCyybUTPVvp';
update content_bodies set title = '龍ヶ窪　清水出でる神秘の地　津南町', description = '津南町に位置する龍ヶ窪は、国内有数の豪雪地帯にあり、日本名水百選にも選ばれた清らかな湧き水を湛えています。水量は毎分30トン、日量43,000トンで、池の水は1日に1回入れ替わります。この神聖な場所には伝説にまつわる二つの神社があり、村の人々によって大切に守られてきました。その神秘的で厳粛な雰囲気は、訪れる人々を魅了し続けています。' where id = 'QS7fOz1yQZMJujiOaa4Sx';
update content_bodies set title = 'Ryugakubo: A Mysterious Place of Pure Water in Tsunan Town', description = 'Located in Tsunan Town, one of Japan''s major heavy snowfall areas, Ryugakubo is renowned for its pristine spring water, selected as one of Japan''s top 100 famous waters. The spring has a flow rate of 30 tons per minute, with a daily total of 43,000 tons of water that is completely replaced once a day. This sacred site, associated with local legends, is home to two shrines and has been cherished by the villagers for generations. Its mystical and solemn atmosphere continues to captivate visitors.' where id = 'la34HZ0EuqpwyPlyvtQdl';
update content_bodies set title = '十日町観光-新潟ふしぎさんがYukiMo!（快速便バス）で清津峡へ！', description = 'YukiMo!は、人気の観光地である清津峡と十日町市街、湯沢駅を結ぶ快速便バスです。今回はインスタグラマーの「新潟ふしぎさん」がYukiMo!を利用して大地の芸術祭を鑑賞しました。清津峡を楽しみながら、十日町の伝統文化や温泉地にも簡単にアクセスできるYukiMo!を利用して、地域の魅力を存分に味わう旅を体験してください。' where id = 'taODgPoFzMfEuKKi7J_om';
update content_bodies set title = 'Tourism in Tokamachi - YukiMo! Express Bus to Kiyotsu Gorge!', description = 'YukiMo! is an express bus that connects the popular Kiyotsu Gorge with the city of Tokamachi and Yuzawa Station. In this instance, the Instagrammer ''Niigata Fushigi-san'' enjoyed the Echigo-Tsumari Art Triennale while traveling on YukiMo! Experience the charm of the region by easily accessing Tokamachi''s traditional culture and hot springs while enjoying Kiyotsu Gorge!' where id = 'Ld-j1S9aDfS4xO_j5A8IY';
update content_bodies set title = '雪育リゾートにいがたプロモーションムービー（ロングver）20241108', description = '「雪育」とは、雪と触れ合う体験を通じて子どもの心身の健やかな成長を促進する考え方です。このプロモーションムービーでは、新潟のスノーリゾートの魅力を「雪育リゾートにいがた」として発信し、雪を通じた教育的な体験の重要性を伝えています。' where id = 'vd0ArcLcFVw6vEPyqc6dc';
update content_bodies set title = 'Snow Education Resort Niigata Promotion Movie (Long Version) 20241108', description = 'The concept of ''snow education'' promotes the healthy growth of children''s minds and bodies through experiences that involve interacting with snow. The appeal of Niigata''s snow resorts will be communicated under the initiative ''Snow Education Resort Niigata.''' where id = '2o15Z15EeWqbr6QS-pMRH';
update content_bodies set title = '清津峡　七色に染まる秘境　十日町市', description = '新潟県十日町市に位置する清津峡は、日本三大渓谷の一つであり、その美しい閃緑ひん岩と柱状節理は特に紅葉シーズンに際立ち、多くの観光客を惹きつけています。昭和63年の落石事故により一時閉鎖されていましたが、清津峡渓谷トンネルの開通により、現在は安全に訪れることができるようになりました。絶景を楽しむだけでなく、近くの温泉も堪能できる観光スポットです。' where id = 'gVd6ddwXj9tHFRgrK3Xxm';
update content_bodies set title = 'Kiyotsu Gorge: A Hidden Gem Drenched in Seven Colors in Tokamachi City', description = 'Kiyotsu Gorge, located in Tokamachi City, Niigata Prefecture, is one of Japan''s three major gorges. The stunning beauty of its greenish-gray rock formations and columnar joints is particularly highlighted during the autumn foliage season, attracting many tourists. After being closed due to a rockfall accident in 1988, the opening of the Kiyotsu Gorge Tunnel has made it safe for visitors to enjoy the breathtaking scenery. This tourist spot also offers the opportunity to relax in nearby hot springs.' where id = 'xj3HtaB30MK0twG1kVCmo';
update content_bodies set title = '【NIIGATA-SORADORI】つなん雪まつり　夜空を彩るスカイランタン　津南町', description = '新潟県最南端、信越県境に位置する津南町で行われる「つなん雪まつり」は、厳しい冬の終わりを告げ、春を迎えることを祝う祭りです。夜空を埋め尽くすスカイランタンは、ディズニー映画「ラプンツェル」を彷彿とさせる美しさで、見る者に感動を与えます。一般参加者もスカイランタンを上げることができ、参加者と観客の両方にとって忘れられない体験となります。' where id = 'PqFrgAi-W8zCIgDdwIKI6';
update content_bodies set title = 'Tsunami Snow Festival: Sky Lanterns Illuminate the Night Sky', description = 'The Tsunami Snow Festival takes place in Tsunan Town, located at the southernmost tip of Niigata Prefecture, near the Shin''etsu border. This festival marks the end of the harsh winter in the heavy snowfall area of Tsunan and the anticipation of spring. The sky lanterns, reminiscent of Disney''s ''Tangled,'' fill the night sky and are a must-see. Participants can also release their own sky lanterns, creating unforgettable moments for both spectators and those launching the lanterns.' where id = 'aJmmFjQwcPzEQDJCGEoCE';
update content_bodies set title = '【最終】弁天島 FHD', description = '説明' where id = 'lnPevKdG-6ta93T1hPVqZ';
update content_bodies set title = 'Final Benten Island FHD', description = 'Description' where id = 'aWB35yMhNrLXoLk4FJ4RS';
update content_bodies set title = '津南町・津南雪まつり 2015 - スカイランタン', description = '津南雪まつりにおける赤チームによるスカイランタンの打上げの様子を紹介しています。' where id = 'nsfI05O181jsan0pOturr';
update content_bodies set title = 'Tsunan Town Snow Festival 2015 - Sky Lanterns', description = 'This is a depiction of the launch of sky lanterns by the red team during the Tsunan Snow Festival.' where id = 'sqXmeQcM_lGb2EBANbWja';
update content_bodies set title = '柏崎の海あそび　シーカヤック・SUP', description = '柏崎の海は全長42kmに及び、年間を通じて多くの観光客が訪れます。海岸線は多様で、透明度の高い海と相まって絶景を生み出しています。近年では、シーカヤックやスタンドアップパドルボードなどのマリンアクティビティが楽しめるようになり、海からの絶景を気軽に楽しむことができます。穏やかな日本海に沈む夕陽は、一見の価値があります。' where id = '0jZ42IVcb9fKwUUnw6z9z';
update content_bodies set title = 'Sea Activities in Kashiwazaki: Sea Kayaking and SUP', description = 'Kashiwazaki''s coastline, stretching 42 km, attracts numerous tourists year-round with its stunning views and clear waters. The area offers a variety of marine activities, including sea kayaking and stand-up paddleboarding (SUP), allowing visitors to enjoy the breathtaking scenery from the sea. The tranquil sunsets over the Sea of Japan are particularly noteworthy and worth experiencing.' where id = 'dV-2J7Mn5PRvBdL1rnKF0';
update content_bodies set title = '【新潟旅行】遊覧船/奥只見/魚沼市/新潟観光', description = '新潟の人気観光地である奥只見は、国内最大級の人造湖を有し、総貯水量は6億トン以上です。春には「北欧のような」美しい景色が広がり、秋には「紅葉の奥只見」として知られる壮大な風景が楽しめます。2,000メートル級の山々に囲まれたこの大自然の中で、湖上遊覧を満喫することができます。' where id = '91StSFOVVGJnRFYPvdEGw';
update content_bodies set title = 'Niigata Travel: Sightseeing Boat / Okutadami / Uonuma City / Niigata Tourism', description = 'Okutadami, one of Niigata''s most popular tourist destinations, features Japan''s largest artificial lake with a total water storage capacity of over 600 million tons. In spring, the scenery resembles that of Northern Europe, while in autumn, visitors can enjoy the stunning fall foliage. Surrounded by mountains over 2,000 meters high, the area offers a chance to experience a scenic boat ride on the lake amidst breathtaking natural beauty.' where id = 'u4vXwUuGHqsPszh1P9mBB';
update content_bodies set title = '2014/07/29　津南町・竜ヶ窪の林道', description = '津南町の竜ヶ窪へ行くまでの林道についての情報です。' where id = 'OI5yg6dXadLMwivtOrqQb';
update content_bodies set title = 'Ryugakubo Forest Road in Tsunan Town (July 29, 2014)', description = 'This is a forest road leading to Ryugakubo in Tsunan Town.' where id = '5nc_M9bLBv4y8xu35rpEi';
update content_bodies set title = '津山市、岡山観光プロモーションビデオ', description = '津山市は岡山県の北部に位置し、北側は鳥取県と接しています。アクセスは良好で、岡山駅からJRで約1時間、岡山桃太郎空港からレンタカーや相乗りタクシーで約1時間、大阪市から車で約2時間です。津山市の観光情報については、公式ウェブサイトをご覧ください。' where id = 'eBBp-cyCmnCGFg8BO5uFh';
update content_bodies set title = 'Tsuyama City, Okayama Tourism Promotion Video', description = 'Tsuyama City is located in the northern part of Okayama Prefecture, adjacent to Tottori Prefecture. It is easily accessible, taking about one hour by JR train from Okayama Station, one hour by rental car or shared taxi from Okayama Momotaro Airport, and approximately two hours by car from Osaka city. For more information about tourism in Tsuyama City, you can visit the official website.' where id = 'kB_MQhnV8ESijF_mfE48U';
update content_bodies set title = 'アイヌ文化の活用をお手伝いします～-2024ver.（一社）阿寒アイヌコンサルン', description = '（一社）阿寒アイヌコンサルンは、アイヌ文化の普及・啓発・伝承活動を阿寒湖アイヌコタンを拠点に行っています。アイヌ文化は音楽や舞踊だけでなく、独自の言葉やアイヌ文様、食文化など多岐にわたります。私たちのミッションは、皆さんがこれらを正しく利用できるようお手伝いすることです。この映像では、アイヌ文様を使用したパッケージデザインの開発を例に、プロジェクトの具体的な進め方や認証手続きについて紹介しています。ぜひお気軽にご相談ください。' where id = 'NEQfS5uy9vFr5LxTwLLzJ';
update content_bodies set title = 'Supporting the Utilization of Ainu Culture - 2024 Version (Akan Ainu Consultant)', description = 'Akan Ainu Consultant is engaged in the promotion, awareness, and transmission of Ainu culture, based in the Akan Lake Ainu Kotan. Ainu culture encompasses various aspects, including music, dance, language, Ainu patterns, and food culture. Our mission is to assist everyone in utilizing these elements correctly. This video introduces specific project methods and certification procedures, using the development of package design featuring Ainu patterns as an example. Please feel free to consult us.' where id = 'XeS4amEGGf82fdZO9CLtr';
update content_bodies set title = '岡山県津山市観光PR動画', description = '岡山県津山市は岡山県の北部に位置し、北は鳥取県と接しています。津山までは、岡山駅からJRで約１時間程度、岡山桃太郎空港からレンタカーや乗合タクシーで約１時間、大阪市内から車で約２時間でアクセス可能です。津山市の観光情報については、https://www.tsuyamakan.jp をご覧ください。' where id = 'MRLOhhgqwh-IrJbKfeNob';
update content_bodies set title = 'Tsuyama City Tourism PR Video', description = 'Tsuyama City is located in the northern part of Okayama Prefecture, bordering Tottori Prefecture to the north. It is accessible from Okayama Station by JR train in about one hour, from Okayama Momotaro Airport by rental car or shared taxi in about one hour, and from Osaka city by car in about two hours. For more information on tourism in Tsuyama City, visit https://www.tsuyamakan.jp.' where id = 'Ib_dqO4Gbtl4xerP5AO_6';
update content_bodies set title = '【公式】トーベ・ヤンソンあけぼの子どもの森公園ライトアップ', description = 'トーベ・ヤンソンあけぼの子どもの森公園では、「豊かな闇」を感じる時間をテーマにしたライトアップを行っています。土曜日、日曜日、祝日の夕暮れから21時までの限られた時間に開催され、訪れる人々はリラックスしたり、カメラを持参して幻想的な北欧童話の世界に浸ることができます。' where id = 'Y8HzAMLyWojwjSFsPgj9C';
update content_bodies set title = 'Tove Jansson Akebono Children''s Forest Park Light Up', description = 'The Tove Jansson Akebono Children''s Forest Park is hosting a light-up event based on the concept of experiencing ''rich darkness'' illuminated by lights in the forest. This event takes place on weekends and holidays from sunset until 9:00 PM. Visitors are encouraged to relax, bring their cameras, and immerse themselves in the enchanting world of Nordic fairy tales.' where id = 'pXjgahY5f7GMrMqrGoGu-';
update content_bodies set title = '映画『urar suye』本編', description = '短編映画『urar suye（ウララ スエ）』は、北海道・阿寒湖アイヌコタンを舞台に、現代のアイヌの世界観を体感できる作品です。物語は、東京で音楽活動をしているユカリが、自身の将来に悩む中、大学の同級生でダンサーのサヤに誘われて阿寒湖アイヌコタンを訪れるところから始まります。アイヌコタンは「創り作り手の街」として知られ、木彫りや刺繍、歌や踊りが日常生活に息づいています。アイヌの人々は、山や川、動物、火などの自然物や現象に「カムイ」が宿ると信じています。ユカリはアイヌコタンを巡りながら、周囲の人々がカムイの存在を感じる様子を通じて、自分自身と世界とのつながりを再認識していきます。' where id = 'oYrkM_28t1lI_BVEbBQ-f';
update content_bodies set title = 'Film ''urar suye'' Main Feature', description = 'The short film ''urar suye'' is set in the Ainu Kotan of Lake Akan in Hokkaido, allowing viewers to experience the contemporary Ainu worldview. The story follows Yukari, a musician in Tokyo who struggles with her future as an artist. Invited by her college classmate Saya, a dancer, she visits the Ainu Kotan, known as a ''town of creators.'' Here, traditional crafts like wood carving and embroidery, as well as songs and dances, are integral to daily life. The Ainu believe that natural elements and phenomena, such as mountains, rivers, animals, and fire, are inhabited by ''kamuy'' (spirits). As Yukari explores the Ainu Kotan, she reconnects with her sense of self and her connection to the world through the lived experiences of the people around her.' where id = 'bbExLXyLkqoBf5LvAEkG2';
update content_bodies set title = '北海道釧路阿寒湖アイヌ文化ガイドツアー「廣野 洋（森、木彫のガイド）」～Anytime Ainutaimu（エニタイムアイヌタイム）　アイヌとともに時間を過ごす阿寒湖旅～', description = 'このツアーでは、日本の先住民族であるアイヌの文化を体験することができます。阿寒湖のほとりで今も息づくアイヌ文化は、他の地域にはない独自の特色を持っています。阿寒湖には北海道最大規模のアイヌコタンがあり、工芸品の販売や歌、踊りなどが脈々と受け継がれています。アイヌと和人が古くから協働してきたこの地域で、文化を深く理解することができます。' where id = '0RWh86zM4Ba4Yg8Z3GfUu';
update content_bodies set title = 'Ainu Cultural Guide Tour at Lake Akan, Hokkaido - Hiroshi Hirono (Wood Carving Guide) - Anytime Ainutaimu', description = 'This tour offers an opportunity to experience the culture of the Ainu, Japan''s indigenous people, who continue to thrive by Lake Akan. The Ainu culture in this region, where Ainu and Japanese have collaborated for centuries, possesses unique characteristics not found elsewhere. Lake Akan is home to the largest Ainu village in Hokkaido, where traditional crafts, songs, and dances are continuously passed down through generations.' where id = 'UoUeWVAu4cyHU7dy20hq2';
update content_bodies set title = 'アイヌ文様有田焼', description = 'この動画では、アイヌ文様が施された有田焼について紹介しています。アイヌ文化と有田焼の融合をテーマにしており、伝統的な技術とデザインがどのように結びついているかを示しています。' where id = '_yos0dn14UF1TaWb5Gtr0';
update content_bodies set title = 'AINU meets ARITA', description = 'This video introduces AINU meets ARITA, which features Ainu patterns on Arita porcelain.' where id = '65ddqXPywASRpXPrep23i';
update content_bodies set title = 'アイヌ文化の活用をお手伝いします～（一社）阿寒アイヌコンサルン', description = '（一社）阿寒アイヌコンサルンは、アイヌ文化の普及・啓発・伝承活動を阿寒湖アイヌコタンを拠点に行っています。アイヌ文化は音楽や舞踊だけでなく、独自の言葉やアイヌ文様、食文化など多岐にわたります。私たちのミッションは、皆さんがこれらを正しく利用できるようにお手伝いすることです。この映像では、アイヌ文様を使用したパッケージデザインの開発を例に、プロジェクトの具体的な進め方や認証手続きについて紹介しています。ぜひお気軽にご相談ください。' where id = '88GLVI-sPWRYc_GPfSwS1';
update content_bodies set title = 'Supporting the Utilization of Ainu Culture - Akank Ainu Consultant', description = 'Akank Ainu Consultant is engaged in the promotion, awareness, and transmission of Ainu culture, based in the Ainu Kotan of Lake Akank. Ainu culture encompasses various aspects, including music, dance, language, patterns, and food culture. Our mission is to assist everyone in utilizing these elements correctly. This video introduces specific project methods and certification procedures, using the development of package design featuring Ainu patterns as an example. Please feel free to consult us.' where id = 'rG681Xz06iNdonWDxXfHa';
update content_bodies set title = '湖の時間（グリーンシーズン）', description = '自然と共に生きる知恵を持つ人々と共に、アイヌ民族の案内役が導くツアーです。大切なものを思い出し、忘れていた自分を取り戻す時間を提供します。次は大切な方と共に、特別な阿寒湖の旅に出かけましょう。合言葉は「Anytime, Ainutime！」です。' where id = '4m1zcerEAuQG7ReWN0_wr';
update content_bodies set title = 'Lake Time (Forest Walk Long Course & Mukkuri Making)~Anytime, Ainutime！~', description = 'This tour invites participants to connect with nature and learn the wisdom of living in harmony with it, guided by the Ainu people. It offers a chance to reflect on what is truly important in life and rediscover oneself. Join this special journey to Lake Akan with a loved one, embracing the motto, ''Anytime, Ainutime!''' where id = '9K74Qg9hqLRon-Jfg5ZOi';
update content_bodies set title = '森の時間（グリーンシーズン）', description = '自然と共に暮らし、生きる知恵を授かる人々がいます。アイヌ民族の案内役と共に、人として大切なものを思い出す時間、忘れていた自分を取り戻す時間を提供します。大切な方と一緒に、特別な阿寒湖の旅に出かけましょう。合言葉は「Anytime, Ainutime！」です。' where id = '5WlG3yghYPdl8q0Yx9K30';
update content_bodies set title = 'Forest Time (Forest Walk Short Course)~Anytime, Ainutime！~', description = 'There are people who live in harmony with nature and learn the wisdom of life. Accompanied by an Ainu guide, this experience offers a chance to remember what is truly important as a human being and to rediscover forgotten aspects of oneself. Join us for a special journey to Lake Akan with your loved ones. The catchphrase is ''Anytime, Ainutime!''' where id = 'iL1g7kkKLpkLmbxWQDkux';
update content_bodies set title = 'AINUとARITAの出会い アイヌ模様の有田焼プレート', description = 'この動画では、アイヌ模様が施された有田焼のプレートを紹介しています。アイヌの芸術性と伝統的な有田焼の技術が交差する様子を強調しています。' where id = 'YKxhvIJh96UARcD08uAOp';
update content_bodies set title = 'AINU meets ARITA Arita Porcelain Plates with Ainu Patterns', description = 'This video showcases Arita porcelain plates that feature unique Ainu patterns, highlighting the cultural intersection between Ainu artistry and traditional Arita craftsmanship.' where id = '_5tLt83L4mTD7p-BC-s31';
update content_bodies set title = 'TSURUGA アドベンチャーベース SIRI 夏の楽しみ方', description = 'この動画では、TSURUGA アドベンチャーベース SIRIでの夏の楽しみ方について紹介しています。さまざまなアクティビティや体験を通じて、訪れる人々がどのように夏を楽しむことができるかを示しています。' where id = 'j24KzdCR-8fYSeOlSxO7_';
update content_bodies set title = 'TSURUGA Adventure Base SIRI: Summer Activities', description = 'This video introduces various ways to enjoy summer at TSURUGA Adventure Base SIRI.' where id = 'L_bMKRw0b_5LOVve9WRit';
update content_bodies set title = '秩父小鹿野プロモーションビデオ（英語版 3分）', description = 'こちらは、伝統的な日本の田舎町である小鹿野町の公式プロモーションビデオです。地域の魅力や文化遺産、風景の美しさや地元の観光名所を紹介しています。' where id = 'JusfOmhQ3W3brI7LZUqfd';
update content_bodies set title = 'Chichibu Ogano Promotion Video (English Ver. 3min)', description = 'This is a promotional video for Ogano town, a traditional Japanese country town. The video showcases the unique charm and cultural heritage of the area, highlighting its scenic beauty and local attractions.' where id = 'xjt4oQPURsRWHru5C0kv7';
update content_bodies set title = '秩父小鹿野プロモーションビデオ', description = 'こちらは、伝統的な日本の田舎町である小鹿野町の公式プロモーションビデオです。地域の独自の魅力や文化遺産を紹介しています。' where id = 'Ly_jV5G1NZMGK7x5Pqmj-';
update content_bodies set title = 'Chichibu Ogano Promotion Video', description = 'This is a promotional video for Ogano town, a traditional Japanese country town. It showcases the unique charm and cultural heritage of the area.' where id = 'yac5SIAFMWp1W_-6N30Os';
update content_bodies set title = '妻沼聖天山', description = 'この動画は妻沼聖天山について紹介しています。' where id = 'JwT95_yl6Xqd7M9nIPhZr';
update content_bodies set title = 'Menuma Shodenzan Temple', description = 'This video introduces Menuma Shodenzan Temple.' where id = 'KpAUH0GSeITl_BBIebJaO';
update content_bodies set title = '長瀞船玉まつり 2018', description = '長瀞船玉まつりは、景勝地・長瀞で行われる夏の祭りです。この祭りは、船下りの船頭が水上の安全を祈願し、水神様を祀ったことに由来しています。約1,000基の灯篭が荒川に流され、提灯をつけた船が水上を行き交います。夜になると、対岸から3,500発を超える花火が打ち上げられ、美しさと迫力を同時に体験できるのがこの祭りの魅力です。' where id = '2Y43wzWez57CK2wguAwyu';
update content_bodies set title = 'Nagatoro Funadama Festival 2018 [4K]', description = 'The Nagatoro Funadama Festival is a summer festival held in the scenic area of Nagatoro. It is said to have originated from the boatmen praying for safety on the water and honoring the water deity. Approximately 1,000 lanterns are released into the Arakawa River, and boats adorned with lanterns navigate the waters. At night, over 3,500 fireworks are launched from the opposite bank, allowing visitors to experience both the beauty and the excitement of the event.' where id = 'VUWnVrUo8ry-MDvkVL4TN';
update content_bodies set title = '秩父夜祭', description = '秩父地方の師走名物である「秩父夜祭」は、京都祇園祭、飛騨高山祭と共に日本三大曳山祭の一つに数えられ、2016年には「秩父祭の屋台行事と神楽」としてユネスコ無形文化遺産に登録されました。この祭りは、秩父神社の例大祭であり、その起源は江戸時代にまでさかのぼります。毎年、12月2日、3日に行われる「秩父夜祭」は、華やかな行事が展開され、秩父の人々にとって一年の総決算ともいえる重要な祭りです。' where id = 'o1JqxVep37XDXAk9rk7TP';
update content_bodies set title = 'Chichibu Night Festival', description = 'The Chichibu Night Festival, a December tradition in the Chichibu region, is one of Japan''s three major float festivals, alongside the Gion Matsuri in Kyoto and the Takayama Matsuri. In 2016, it was registered as an Intangible Cultural Heritage by UNESCO as ''Chichibu''s Float Events and Kagura.'' The festival is held in honor of the Chichibu Shrine, the area''s main deity, and its origins date back to the Edo period. Celebrated annually on December 2nd and 3rd, the Chichibu Night Festival is a vibrant event that serves as a culmination of the year for the local community.' where id = 'pYH5EnWzseKHc5-Kz-X_A';
update content_bodies set title = '猪俣の百八燈', description = '「猪俣の百八燈（ひゃくはっとう）」は、児玉郡美里町で毎年8月15日に行われる盆祭りで、400年以上の歴史があります。この行事では、夏の夜に堂前山の尾根に築かれた108基の塚に火がともされ、幻想的な光景が広がります。主役は満6歳から満18歳までの子どもたちや若者たちで、彼らは協力しながら準備を進め、当日を迎えます。荘厳で幻想的な雰囲気を楽しめる盆行事の一つです。' where id = 'V1TzXW_001zOrAZGVnOqW';
update content_bodies set title = 'Inomata''s 108 Lanterns', description = 'Inomata''s 108 Lanterns is a Bon festival held annually on August 15 in Misato Town, Kodama District, with a history of over 400 years. This event features a mystical display where 108 mounds, built along the ridge of Doumae Mountain, are lit up during the summer night. The main participants are children and young people aged 6 to 18, who work together from preparation to the event day. It is one of the Bon events that offers a solemn and enchanting atmosphere.' where id = 'QhioCF_hE2hg67AZsbL0O';
update content_bodies set title = '長瀞船玉まつり', description = '長瀞船玉まつりは、景勝地・長瀞で行われる夏の祭りです。この祭りは、船下りの船頭が水上の安全を祈願し、水神様を祀ったことが始まりとされています。約1,000基の灯篭が荒川へ流され、提灯をつけた船が水上を行き交います。夜になると、対岸から3,500発を超える花火が打ち上げられ、美しさと迫力を同時に体験できるのがこの祭りの魅力です。' where id = 'JVbY3voKZZZ9tLQHXcFSi';
update content_bodies set title = 'Nagatoro Funadama Festival', description = 'The Nagatoro Funadama Festival is a summer festival held in the scenic area of Nagatoro. It is said to have originated when boatmen prayed for safety on the water and honored the water deity. Approximately 1,000 lanterns are floated down the Arakawa River, and boats adorned with lanterns navigate the waters. At night, over 3,500 fireworks are launched from the opposite bank, allowing visitors to experience both the beauty and the excitement of the event.' where id = 'hS5fhKgn22FAOvYduq9E9';
update content_bodies set title = '大宮夏まつり（中山道まつり）', description = '中山道まつりは、関東一円の氷川神社の総本山である武蔵一宮氷川神社の例大祭に合わせて行われる、古くから地元に根付いた祭りです。現在では市民祭り「大宮夏まつり」の一環として開催されています。おはらいを受けた御輿と山車が駅前に集結する光景は圧巻で、多くの人々が訪れます。' where id = 'AX7H3AiQWtef6Ni5S0cwx';
update content_bodies set title = 'Omiya Summer Festival (Nakasendo Festival)', description = 'The Nakasendo Festival is a traditional event that has deep roots in the local community, held in conjunction with the grand festival of the Musashi Ichinomiya Hikawa Shrine, the head shrine of Hikawa Shrine in the Kanto region. Today, it is part of the citizen festival known as the Omiya Summer Festival. The sight of the purified portable shrines and floats gathering in front of the station is truly impressive.' where id = 'fE4RiGSU7BwwNciiKJ1JX';
update content_bodies set title = 'エミー賞受賞監督が捉えた美しい伊豆', description = 'この動画は、エミー賞を受賞した監督によって捉えられた美しい伊豆を紹介しています。伊豆の風光明媚な風景や独特の特徴が映し出されており、視聴者にその自然の魅力や文化的な重要性を垣間見せています。' where id = 'y5QUej3BtQHbjGSnSHGEG';
update content_bodies set title = 'Beautiful Izu Captured by an Emmy Award-Winning Director', description = 'This video showcases the stunning beauty of Izu, a region in Japan, as captured by an Emmy Award-winning director. The visuals highlight the picturesque landscapes and unique features of Izu, offering viewers a glimpse into its natural charm and cultural significance.' where id = 'BZG73385814u_rq-V3h4D';
update content_bodies set title = '備前市吉永町八塔寺プロモーション動画', description = 'この動画は備前市吉永町八塔寺について紹介しています。八塔寺の魅力や特徴を視覚的に伝え、地域の観光資源としての価値を高めることを目的としています。地域の文化や自然環境を感じられる内容となっており、訪れる人々に八塔寺の魅力を伝えることを意図しています。' where id = 'E9degfVE4ReDfsb7oluyG';
update content_bodies set title = 'Promotion Video of Hattouji, Yoshinaga Town, Bizen City', description = 'This video introduces Hattouji in Yoshinaga Town, Bizen City.' where id = 'WcjvTpiMQl_OdsEhSMpne';
update content_bodies set title = '備前観光動画（日本語）/produce by ABC Style', description = 'この動画は備前観光について紹介しています。備前は日本の歴史的な地域であり、観光名所や文化的な魅力が豊富です。動画では、備前の美しい風景や観光スポット、地元の特産品などが紹介されており、訪れる価値のある場所としての魅力が伝えられています。' where id = 'EbHq5FuDDGOy_ETvrNmAA';
update content_bodies set title = 'Bizen Tourism Video (Japanese) / produced by ABC Style', description = 'This video introduces Bizen tourism.' where id = 'zeH8XwoQsYKJVTMXL9lxY';
update content_bodies set title = '食とライフスタイルにこだわる方の備前焼講座　-入門編-', description = 'この動画では、食とライフスタイルにこだわる方々のための備前焼講座について紹介しています。備前焼は日本の伝統的な陶器であり、その魅力や技術を学ぶことができます。入門編として、初心者でも理解しやすい内容が提供されており、食文化と結びついた陶芸の楽しさを体験することができます。' where id = 'LH50YxB2hfCJzMWTHwkP8';
update content_bodies set title = 'Bizen Ware Course for Food and Lifestyle Enthusiasts - Introductory Edition', description = 'This video introduces a Bizen ware course designed for those who are particular about food and lifestyle.' where id = 'hJi0r6mza-HZhQh_BioDf';
update content_bodies set title = '日本のルーツ', description = 'この動画では、日本の歴史的および文化的なルーツについて紹介しています。日本の起源と発展を探る内容です。' where id = 'CW8quq8-JOSeieYNiePib';
update content_bodies set title = 'Roots of Japan', description = 'This video provides an introduction to the historical and cultural roots of Japan, exploring the origins and development of the nation.' where id = 'fRgDuEQRS0zSjyxyDZMHa';
update content_bodies set title = '埼玉県の棚田', description = '横瀬町にある「寺坂棚田」は、西武秩父線の横瀬駅から徒歩約20分の距離に位置しています。美しい風景が楽しめる「寺坂棚田」へ、ぜひ訪れてみてください。' where id = 'gzfzCoUylxPxtYLlLGC6A';
update content_bodies set title = 'Terraced Rice Fields in Saitama Prefecture', description = 'The ''Terazaka Tanada'' in Yokose Town is about a 20-minute walk from Yokose Station on the Seibu Chichibu Line. It offers beautiful scenery, making it a must-visit destination.' where id = 'dq88C8FqPHCR4_31VRp-1';
update content_bodies set title = '獅子舞披露　～上梨青年会　2015 05 30 日本民家園～', description = '世界文化遺産登録20周年記念事業「世界遺産五箇山がやってくる」で、上梨青年会による獅子舞が披露された。2015年5月30日から31日に開催され、道中の太鼓の音色と共に会場に入場し、獅子と共に舞い踊る演目が行われた。演目にはマイコミ、ゲンバヤシ、シチゴサンが含まれている。上梨の獅子舞は毎年4月下旬に白山社を中心に行われ、氷見市大久保の大工が伝えたとされ、五箇山地域で最も古く、規模も最大の獅子舞である。' where id = '3z0iz8XFmaAXBDK4UB_Q4';
update content_bodies set title = 'Lion Dance Performance by Kaminarishi Youth Association - Trip to Nanto City, Toyama Prefecture', description = 'The lion dance performed by the Kaminarishi Youth Association was showcased during the 20th anniversary event of the World Heritage registration, titled ''The World Heritage Gokayama Comes to You'' held from May 30 to 31, 2015. The performance began with the sound of drums as they entered the venue, featuring the lion and the performers dancing together. The repertoire included ''Maikomi,'' ''Genbayashi,'' and ''Shichigosan.'' The Kaminarishi lion dance is traditionally held in late April at Hakusan Shrine and is said to have been passed down by carpenters from Okubo in Himi City. It is the oldest and largest lion dance tradition in the Gokayama region.' where id = 'Xm6swOa6oDRRYIStHh8P2';
update content_bodies set title = '五箇山民謡の演舞～出演：平高校郷土芸能部～', description = '2015年6月6日に開催された「世界文化遺産登録20周年記念事業『五箇山民謡祭』」で、富山県立南砺平高校郷土芸能部が五箇山民謡の演舞を披露しました。平高校郷土芸能部は、第38回全国高等学校総合文化祭（いばらき総文2014）の郷土芸能部門で文部科学大臣賞を受賞するなど、その実力が評価されています。' where id = 'v8AfMIdulUMWcbulqSLrZ';
update content_bodies set title = 'Performance of Gokayama Folk Songs by Taira High School Folklore Club', description = 'On June 6, 2015, the Taira High School Folklore Club performed Gokayama folk songs at the ''20th Anniversary of World Cultural Heritage Registration Gokayama Folk Song Festival.'' The club is recognized for its excellence, having won the Minister of Education, Culture, Sports, Science and Technology Award at the 38th National High School Comprehensive Cultural Festival (Ibaraki Soubun 2014) in the traditional performing arts category.' where id = 'IwOVo1fWkvlTs5TNARz2b';
update content_bodies set title = '獅子舞披露　～ダイジェスト版　2015.05.30 日本民家園～', description = '2015年5月30日に上梨青年会による獅子舞の演舞が披露されました。この演舞は、2015年5月30日から31日にかけて開催された「世界文化遺産登録20周年記念事業『世界遺産五箇山がやってくる』」のアトラクションの一つです。' where id = 'E_ERcfOy-Fr8dRomKSBzC';
update content_bodies set title = 'Lion Dance Performance - Digest Version, May 30, 2015, Japan Open-Air Folk Museum', description = 'On May 30, 2015, the Kaminarishi Youth Association performed a lion dance. This performance was part of the attractions for the ''20th Anniversary of World Heritage Registration: The World Heritage Gokayama Comes to You'' event, held from May 30 to 31, 2015.' where id = '9ei_nbdu-1VbjQKtfNdNq';
update content_bodies set title = '民宿　中の屋（みんしゅく　なかのや）【利賀村】', description = '民宿　中の屋は、富山県南砺市利賀村坂上551に位置しています。郵便番号は939-2516で、電話番号は0763-68-2104です。詳細は公式ウェブサイト（https://travel.rakuten.co.jp/HOTEL/51646/51646.html）をご覧ください。' where id = 'Fg8_ewcBC2n4IKhzZtux3';
update content_bodies set title = 'Minpaku Nakano-ya (Inn Nakano-ya) [Toga Village]', description = 'Minpaku Nakano-ya is located at 551 Sakaue, Toga Village, Nanto City, Toyama Prefecture, 939-2516, Japan. For inquiries, you can reach them at TEL: 0763-68-2104. More information can be found on their website: https://travel.rakuten.co.jp/HOTEL/51646/51646.html' where id = '-f6tcprefCeYdOARC_aQW';
update content_bodies set title = '南砺の風景：夕焼け（閑乗寺公園）', description = '見頃は4月下旬から5月中旬で、水田の風景が楽しめる閑乗寺公園は、富山県南砺市井波外二入会に位置し、標高300メートルの高台から砺波平野を一望できる絶景スポットです。かつてファミリースキー場だったこの公園は、高低差を活かしたアクティビティが楽しめ、開放感があります。キャンプ場やバーベキュー棟、合掌造りの研修棟、イベント用のログハウス、子供向けの遊具などが整備されており、家族連れにも最適です。自然を学び、リラックスできるアットホームな雰囲気の公園で、幹線道路からも近く、瑞泉寺や井波、庄川などの観光スポットも豊富です。' where id = '6tXAXxTkZlpwaq3Bm7vmI';
update content_bodies set title = 'Sunset at Kanjoji Park, Nanto City', description = 'Best viewing period: Late April to mid-May, featuring rice field scenery. Kanjoji Park, located at 1 Inami Sotonai, Nanto City, Toyama Prefecture, is a scenic spot at an elevation of 300 meters, offering a panoramic view of the Tonami Plain and harmonious nature with deep mountains. Once a family ski resort, the park utilizes its elevation for various activities, providing a sense of openness. Facilities include a campsite, barbecue area, a traditional gassho-style training center, a log house for events, and playgrounds for children, making it a family-friendly destination. Visitors can relax and learn about nature in this welcoming park, which is conveniently located near main roads and attractions like Zuiseiji Temple, Inami, and Shogawa.' where id = 'SrASHN1NcGmgpRWfW0VVD';
update content_bodies set title = '【南砺の風景】サイクリング①（散居村）', description = '撮影は6月中旬に南砺市井波から井口の散居村で行われました。散居村は富山県の砺波平野に位置し、庄川と小矢部川によって形成された扇状地に広がっています。約220平方キロメートルの面積に、屋敷林に囲まれた7,000戸以上の農家が点在しています。散居村は、各農家が周囲の土地を開拓し米作りを行ってきたことに由来し、農作業の効率を高めています。また、屋敷林（カイニョ）は、冬の冷たい風や夏の日差しから家を守り、日常生活に必要な燃料や建材を提供してきました。このように、散居村の人々は自給自足に近い生活を送り、自然との共生を図ってきた知恵の結晶と言えます。' where id = 'O7wi9WJH4QLQ61jyENfkr';
update content_bodies set title = 'Cycling in Nanto: Scenic Views (Sankyo Village)', description = 'The photos were taken in mid-June in Nanto City, specifically in the Sankyo Village area. Sankyo Village is located in the Takaoka region of Toyama Prefecture, characterized by the Takaoka Plain formed by the Shogawa and Oyabe rivers. This area spans approximately 220 square kilometers and is home to over 7,000 farmhouses surrounded by estate forests. The development of Sankyo Village is rooted in the practice of each farmhouse cultivating the surrounding land for rice farming, which allowed for efficient management of water and crops. A distinctive feature of this village is the estate forests, known as ''Kainyo,'' which protect homes from harsh winter winds and summer heat. The forests also provided essential resources for daily life, such as firewood and building materials. The lifestyle of the villagers was largely self-sufficient, relying on their land and forests for sustenance and materials, reflecting a harmonious relationship with nature.' where id = 'NM4sM0Jwq842qgWTnY_b-';
update content_bodies set title = '南砺の風景：散居村のサイクリング', description = '撮影は6月中旬に南砺市の福野、井波、井口の散居村で行われました。散居村は、富山県の砺波平野に広がる約220平方キロメートルの地域で、7,000戸以上の農家が屋敷林に囲まれて点在しています。この集落形態は、農家が自宅周辺の土地を開拓し、米作りを行うことから生まれました。屋敷林（カイニョ）は、冬の冷たい風や夏の日差しから家を守り、日常生活に必要な燃料や建材を提供しました。住民は自給自足に近い生活を送り、自然と共生する知恵を受け継いできました。' where id = 'efN7EuxjBbpwbZVNY9elO';
update content_bodies set title = 'Cycling in Nanto: Scenic Views of the Scatter Village', description = 'The photos were taken in mid-June in the scatter villages of Fukuno, Inami, and Iguchi in Nanto City, located in the Tōnami Plain of Toyama Prefecture. The scatter village, characterized by over 7,000 farmhouses surrounded by estate forests, spans approximately 220 square kilometers. This unique settlement pattern originated from farmers cultivating rice on land around their homes, allowing for efficient management of water and crops. The estate forests, known as ''Kainyo,'' provided protection from harsh winter winds and summer sun, while also supplying essential fuel and materials for daily life. The residents of these villages practiced a self-sufficient lifestyle, growing rice and vegetables and sourcing necessary resources from their surrounding forests. The scatter village represents the wisdom of past generations who harmonized their lives with nature.' where id = '2B0PSsMKLZaicTGThWJJB';
update content_bodies set title = '観光列車べるもんた　～住民によるお出迎え＆お見送り～', description = '観光列車「べるもんた」は、正式名称「ベル・モンターニュ・エ・メール」で、2015年10月10日から運行を開始しました。北陸新幹線と城端線を結ぶこの列車は、山と海の美しい景色を楽しめる「走るギャラリー」としてデザインされています。毎週土曜日に城端線を2往復し、車内では富山湾鮨を楽しむことができる珍しい体験が提供されます。地元のボランティアガイドによる温かみのある観光案内も好評で、方言を交えたおしゃべりが旅を盛り上げます。終着駅の城端駅では「南砺さとやマルシェ」が開催され、地元のお菓子やお土産品が紹介・販売されています。' where id = '1jYenKMrkt5C1yxThYoUT';
update content_bodies set title = 'Tourist Train ''Belmont'' - Welcoming and Farewell by Locals', description = 'The ''Belmont'' tourist train, officially known as ''Belle Montagne et Mer'', began operations on October 10, 2015, as part of the Hokuriku Destination Campaign. It connects the Hokuriku Shinkansen and the Jōhana Line, showcasing beautiful views of mountains and the sea through its design, which is likened to a moving gallery. The train runs twice every Saturday on the Jōhana Line, offering a unique experience of enjoying freshly made sushi from Toyama Bay onboard. Local volunteer guides provide warm and engaging commentary in the local dialect, enhancing the journey. At the final stop, Jōhana Station, the ''Nanto Satoya Marche'' is held, featuring local sweets and souvenirs for sale.' where id = 'u3oUPX3NWm013ntbisRvO';
update content_bodies set title = '観光列車べるもんた　５周年', description = '観光列車「べるもんた」は、正式名称「ベル・モンターニュ・エ・メール」として2020年10月10日に運行開始から5周年を迎えました。この日は城端駅でお祝いが行われ、式年太鼓による和太鼓演奏が披露されました。式年太鼓は1970年に発足し、地域の支援を受けながら活動を続けています。べるもんたは、北陸デスティネーションキャンペーンに合わせて運行を開始し、山と海の美しい景色を楽しめる観光列車です。毎週土曜日に運行され、富山湾鮨を楽しめる珍しい体験や、地元ボランティアによる観光案内が好評です。終着駅の城端駅では「南砺さとやマルシェ」が開催され、地元のお菓子やお土産が紹介されています。' where id = 'ajnozoYXX59V5N5l08y11';
update content_bodies set title = 'Tourist Train ''Belmont'' Celebrates 5th Anniversary', description = 'The tourist train ''Belmont'', officially named ''Bel Montagne et Mer'', celebrated its 5th anniversary on October 10, 2020. The event at Jōhana Station featured a traditional Japanese drum performance by the Shikinen Taiko group. Established in 1970, Shikinen Taiko has been supported by the local community and continues to hold annual events, including drum training for local students. The Belmont train, launched in conjunction with the Hokuriku Destination Campaign, operates on the Jōhana and Himi lines, showcasing beautiful views of mountains and the sea. It runs twice on Saturdays, offering unique experiences such as freshly made Toyama Bay sushi and guided tours by local volunteers. At the final stop, Jōhana Station, the ''Nanto Satoya Marche'' is held, featuring local sweets and souvenirs.' where id = 'qr_jSjdIa_09I5jFujlMB';
update content_bodies set title = '函館市の観光 ~秋と冬~', description = 'この動画では、函館市の秋と冬の魅力を紹介しています。' where id = 'KJzWmTi-nRQdJknxFnTox';
update content_bodies set title = 'Sightseeing in Hakodate City ~Autumn and winter~', description = 'This video introduces the autumn and winter seasons in Hakodate City.' where id = '5iKH5iG5YObHlwX0I-2IE';
update content_bodies set title = '薪の音（まきのおと）【城端】', description = '薪の音は、富山県南砺市の里山に位置するオーベルジュです。住所は、富山県南砺市野口140番地、郵便番号は939-1844です。電話番号は0763-62-3255で、詳細は公式ウェブサイト（https://makinooto.co.jp/）をご覧ください。' where id = '5ilqWKyRrwCDcT_R-goqv';
update content_bodies set title = 'Makinooto', description = 'Makinooto is an auberge located in the Satoyama area of Nanto City, Toyama Prefecture, Japan. The address is 140 Noguchi, Nanto City, Toyama 939-1844. For inquiries, you can contact them at 0763-62-3255. More information can be found on their website: https://makinooto.co.jp/' where id = 'BJUlkMCB3Fi52f6lKRnau';
update content_bodies set title = '城端曳山祭 ～狭い路地の通過～', description = '越中の小京都・城端の春を彩る城端神明宮の祭礼である城端曳山祭。獅子舞と剣鉾が悪霊を鎮め、傘鉾が神霊を迎えます。その後、情緒あふれる庵唄と伝統の城端塗の曳山が続きます。この記事では、狭い路地を通過する曳山の様子に焦点を当て、各町の曳山に施された仕掛けについて紹介します。狭い路地を通るための工夫をぜひ楽しんでください。' where id = 'M-wL8E3sySmYSTW8m64LW';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture - Juhon Hikiyama Festival: Passing Through Narrow Alleys', description = 'The Juhon Hikiyama Festival, held at Juhon Shinmeigu Shrine, celebrates spring in Juhon, a small Kyoto in Etchu. The festival begins with a lion dance and sword poles that pacify evil spirits, followed by umbrella poles welcoming divine spirits. The procession continues with the charming sounds of traditional ''An Uta'' from the ''An Yatai'' and the beautifully crafted Hikiyama, showcasing the traditional Juhon lacquer. This article focuses on the Hikiyama passing through narrow alleys, where each town''s Hikiyama is equipped with special mechanisms to navigate these tight spaces. Enjoy discovering the unique features of these mechanisms!' where id = 'CjAifTrVrAJx9KMSHsads';
update content_bodies set title = 'ビジネスホテルAsahi壱番館', description = 'ビジネスホテルAsahi壱番館は、富山県南砺市松原本町1236に位置しています。郵便番号は939-1518です。お問い合わせは0763-22-7070までどうぞ。詳細は公式ウェブサイト（https://travel.rakuten.co.jp/HOTEL/43919/43919.html）をご覧ください。' where id = 'KJyMygEqBkpSEC7gejm_R';
update content_bodies set title = 'Business Hotel Asahi Ichibankan', description = 'Business Hotel Asahi Ichibankan is located at 1236 Matsubara Honmachi, Nanto City, Toyama Prefecture, 939-1518, Japan. For inquiries, you can contact them at 0763-22-7070. More information can be found on their website: https://travel.rakuten.co.jp/HOTEL/43919/43919.html.' where id = 'B5aBSTi3r2sLCAl0qeTD1';
update content_bodies set title = '城端曳山祭 　～提灯山（夜の曳山巡行）～', description = '越中の小京都・城端で行われる城端神明宮の祭礼は、春の訪れを祝う重要なイベントです。祭りは獅子舞と剣鉾が悪霊を鎮め、続いて傘鉾が神霊を迎えるところから始まります。その後、情緒豊かな庵唄を奏でる庵屋台や、伝統的な城端塗の美しい曳山が続きます。夕方になると、曳山は提灯山に変わり、昼間とは異なる趣を楽しむことができます。また、神様を迎えるための６箇所の山宿が見られる宵祭りも見逃せません。' where id = 'pvRnWRjjNQn3DGeOkKDyt';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture - Juhon Hikiyama Festival: Lantern Mountain (Night Procession)', description = 'The Juhon Hikiyama Festival, held at Juhon Shinmeigu Shrine in Juhon, a small Kyoto in Etchu, celebrates the arrival of spring. The festival begins with a lion dance and a sword pole that pacify evil spirits, followed by umbrella poles welcoming divine spirits. The procession continues with the charming ''An Uta'' from the traditional ''An Yatai'' and the beautifully crafted Hikiyama, showcasing the traditional Juhon lacquer. As evening falls, the Hikiyama transforms into a lantern mountain, offering a different ambiance from the daytime festivities. Additionally, the night festival features six mountain lodges where visitors can witness the welcoming of the gods.' where id = 'O48RcCpST-nvv6tUxDzOX';
update content_bodies set title = '城端曳山祭　～まちなか巡行～', description = '城端曳山祭では、精緻な彫りと塗りが施された6台の山車が町中を練り歩き、御神像を乗せています。それぞれの山車を先導するのは、京都祇園の一力茶屋を模した精巧な「庵屋台」で、笛や三味線の音色に合わせて、江戸端唄の流れをくむ城端独特の「庵唄」が唄われます。' where id = 'ztstjAUBejFm0RTQhCh5q';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'The Juhana Hikiyama Festival features six intricately carved and painted floats parading through the town, each carrying a sacred statue. Leading these floats are elaborately designed ''An-yatai'' inspired by Kyoto''s Ichiriki Chaya. During the procession, the unique ''An-uta'' of Juhana, which is rooted in Edo-style folk songs, is performed accompanied by the sounds of flutes and shamisen.' where id = 'yJBLUo_ppWF_kxoX8YpZU';
update content_bodies set title = '城端曳山祭　～夜のまちなか巡行～', description = 'この動画では、城端曳山祭の夜のまちなか巡行について紹介しています。祭りの雰囲気や参加者の様子が映し出され、地域の文化や伝統を感じることができます。' where id = 'BZy40LemVPd7-n9Hq6NG6';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'This video introduces the nighttime procession of the Juhon Hikiyama Festival.' where id = '4H9lEtb07g8suEyy4ozEs';
update content_bodies set title = '井波別院瑞泉寺で写仏と写経　～日本一大きな太子堂と聖徳太子信仰を訪ねて～　富山県南砺市／南砺市観光協会', description = '井波別院瑞泉寺は、井波彫刻の発祥地であり、写仏と写経の体験を通じて心身のリフレッシュを図ることができます。特に虎の掛け軸が飾られた「虎の間」での体験は、自己と向き合う貴重な時間を提供します。主な体験内容には、本堂や太子堂の拝観、聖徳太子の二歳像の写仏、聖徳太子を讃える和讃の写経があります。予約はオンラインで可能で、詳細は南砺市観光協会のウェブサイトで確認できます。' where id = 'STvdaILDBsqwDpQeF4SKo';
update content_bodies set title = 'Experience Shabutsu and Shakyo at Inami Betsuin Zuiseiji - Visiting Japan''s Largest Taishido and the Faith in Prince Shotoku - Nanto City, Toyama Prefecture / Nanto City Tourism Association', description = 'Inami Betsuin Zuiseiji, known as the birthplace of Inami woodcarving, offers a unique opportunity for spiritual rejuvenation through the experiences of Shabutsu (Buddha copying) and Shakyo (sutra copying). Visitors can engage in these practices in a special room adorned with tiger scrolls, allowing for a reflective and refreshing experience. The main activities include visiting the main hall and Taishido, copying the statue of Prince Shotoku, and transcribing hymns praising him. Reservations can be made online, and further details about the experiences and facilities are available through the Nanto City Tourism Association.' where id = '0jHzkunUWVKAAL0ocCJe_';
update content_bodies set title = '木のぐい吞みづくり体験　～日本一の木彫刻のまち、井波で職人体験～', description = '井波での木彫刻体験プランでは、現役の彫刻師の指導のもと、木のぐい吞みを手作りします。彫刻の道具を使い、心地よい音を楽しみながら、木と向き合う時間を過ごせます。体験後は、地元の若駒酒造で地酒の試飲を楽しみ、出来立てのぐい吞みでその香りや味わいを体感できます。初心者でも気軽に参加できるこのプランで、職人の技を体験してみてはいかがでしょうか。' where id = 'N8TvRtswhmRw5GrN47gFz';
update content_bodies set title = 'Experience Making Wooden Sake Cups - Craftsmanship Experience in Inami, Japan''s Top Wood Carving Town', description = 'Join a unique wood carving experience in Inami, renowned as one of Japan''s leading wood carving towns. Under the guidance of skilled local artisans, participants will use traditional carving tools to create their own original wooden sake cups. The soothing sounds of chiseling and the ambiance of the historic town will provide a memorable experience. After crafting, enjoy a sake tasting at Wakakoma Brewery, where you can appreciate the distinct flavors and aromas of sake served in your handmade cup. This program is suitable for beginners, offering a delightful glimpse into the world of craftsmanship.' where id = '4au15XvvgQ1gXb15HMo5d';
update content_bodies set title = '菓子木型で和菓子づくり体験　～越中の小京都・城端で職人体験～', description = '富山県南砺市城端にある老舗菓子処田村萬盛堂で、貴重な菓子木型を用いた和菓子作り体験ができます。この体験では、茶道の一部作法を学びながら、抹茶の点て方やふくさの扱い方を体験します。田村萬盛堂は寛政年間から続く店舗で、約300点の精緻な菓子木型を展示する木型館も併設されています。訪れる人々は、店主による城端菓子の話を楽しみながら、加賀前田藩主が奨励した茶の湯文化に触れることができます。体験メニューには、練り切りや鯛型最中の餡子詰めなどがあり、内容はコースによって異なります。' where id = 'u8KDgEamxHFgF_5VVf_uB';
update content_bodies set title = 'Experience Making Japanese Sweets with Wooden Molds in Jōhana, Toyama', description = 'In Jōhana, a small Kyoto in Nanto City, Toyama Prefecture, you can participate in a unique experience of making traditional Japanese sweets using valuable wooden molds at the long-established Tamura Manseido. The experience includes learning about the art of tea ceremony, with a focus on the preparation of matcha and the handling of fukusa. Tamura Manseido has been in operation since the Kansei era and features a museum displaying around 300 exquisite wooden molds, which are akin to art pieces. Visitors can enjoy stories about Jōhana sweets from the shop owner while immersing themselves in the rich cultural heritage of the region, which was encouraged by the Kaga Maeda clan. Various experience options are available, including making nerikiri, filling tai-shaped monaka with red bean paste, and more.' where id = 'BZ4iE1T5-gP9NYuvxFO5X';
update content_bodies set title = '【公式】『なん旅』福光バットものがたりPV', description = '南砺市福光は、全国のバット生産の約4割を占める一大生産地です。福光地域のバット産業は大正時代から始まり、現在も多くのプロ野球選手が使用する木製バットが地元の工場で生産されています。南砺市観光協会が主催するツアー『なん旅』では、バット工場の見学や職人の手ほどきによるバット削り体験ができます。移動には便利な地元タクシーが用意されています。南砺を感じる旅に出かけましょう。' where id = 'Sui_K6abQGthvgD8KsLJd';
update content_bodies set title = 'Official PV of ''Nanto Travel'' - The Story of Fukumi Bats', description = 'Fukumi in Nanto City is a major production area, accounting for about 40% of bat production in Japan. The bat industry in Fukumi began in the Taisho era, and wooden bats used by many professional baseball players are still produced in local factories. The ''Nanto Travel'' tour, organized by the Nanto City Tourism Association, offers a factory tour where participants can experience bat carving under the guidance of skilled craftsmen. Convenient local taxis are provided for transportation. Come and enjoy a deeper experience of Nanto.' where id = '7OqizPau2GP1i35nYA4XM';
update content_bodies set title = '【公式】『なん旅』五箇山和紙を彩る～世界遺産で手仕事体験～PV', description = '五箇山合掌造り集落は世界文化遺産に登録されており、高品質で強靭な「五箇山和紙」は今も重要な産業として受け継がれています。「なん旅」では、合掌造りの家屋の中で、和紙を使った紙塑人形に絵付けをし、自分だけの猫の置物を作る体験ができます。このプログラムを通じて、南砺の文化を深く感じることができます。ただし、現在は冬期のため休止中で、2022年春に再開予定です。' where id = 'bns9WJ2RedE4nwGESFbqQ';
update content_bodies set title = 'Experience Traditional Crafting in Gokayama - A World Heritage Site', description = 'Gokayama, a UNESCO World Heritage site, is known for its traditional gassho-zukuri farmhouses and the high-quality, durable Gokayama washi paper. The ''Nantabi'' program offers a unique opportunity to paint and create your own cat figurine using paper-mache dolls made from washi paper inside a gassho-zukuri house. This experience allows visitors to immerse themselves in the culture of Nanto. Note that this program is currently suspended for winter and is expected to resume in spring 2022.' where id = 'IneM1Lz0fn8FiiQVw2bia';
update content_bodies set title = '福野の曳山～新町編～', description = '福野には、上町・七津屋の船鉾型曳山と、横町、浦町・辰巳町、新町の花傘山型曳山の計4基が存在します。各曳山は独自の意匠を持ち、上町の「神功皇后の西征航海」や浦町の「素戔嗚尊の大蛇退治」などが代表的です。曳山の起源は不明ですが、文政年間（1818～1830）には各町で作られ、天保年間（1830～1844）には全ての曳山が揃って曳き廻されたと考えられています。経済不況の際、人々は神を奉り、町の繁栄を祈ったと推測されます。福野夜高祭は毎年5月1日から2日に開催され、曳山のメインイベントは5月3日に行われます。' where id = 'HVoVX3pU4t6VysszFl-FM';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'Fukuno City features four types of traditional floats: the Funahako-type from Kamimachi and Nanatsuya, and the Hanakasa-type from Yokomachi, Uramachi, Tatsumimachi, and Shinmachi. Each float showcases unique designs, such as ''Empress Jingu''s Western Expedition'' from Kamimachi and ''Susa-no-o''s Great Serpent Defeat'' from Uramachi. The origins of these floats date back to the early 19th century, with records indicating their existence by the Bunsei era (1818-1830). The floats were likely created as a means to pray for prosperity and ward off disasters during economic downturns. The Fukuno Yotaka Matsuri, a paper lantern parade festival, is held annually on May 1-2, while the main float event takes place on May 3 in the city center.' where id = '_s5H7nrhNchBaKt9mkicC';
update content_bodies set title = '福野の曳山～浦町・辰巳町編～', description = '福野には、上町・七津屋の船鉾型曳山、横町、浦町・辰巳町、新町の花傘山型曳山の計4基が存在します。各曳山は、上町の「神功皇后の西征航海」、横町の「猩々の汲み酒」、浦町・辰巳町の「素戔嗚尊の大蛇退治」、新町の「橋弁慶牛若丸」といった独自の意匠を持っています。曳山の起源は不明ですが、文政年間には各町で曳山が作られ、天保年間には4町の曳山が揃って曳き廻されたと考えられています。これは、享保期の経済不況に対する打開策として、町内の繁栄を祈るためのものであったと推測されます。福野夜高祭は毎年5月1日から2日に開催され、曳山のパレードは5月3日に行われます。' where id = '-kElHpCM20RdTMkb3fND0';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'Fukuno City features four types of traditional floats: the Funahoko-style float from Kamimachi and Nanatsuya, and the Hanakasa-style floats from Yokomachi, Urakawachi, Tatsumimachi, and Shinmachi. Each float showcases unique designs, such as ''Empress Jingu''s Western Expedition'' from Kamimachi, ''Shōjō''s Sake Fetching'' from Yokomachi, ''Susanoo''s Serpent Defeat'' from Urakawachi and Tatsumimachi, and ''Benkei and Ushiwakamaru on the Bridge'' from Shinmachi. The origins of the float parades are unclear, but historical documents suggest that floats were created in the early 19th century, with all four towns participating by the 1830s. The floats were likely a response to economic hardships during the Edo period, as communities prayed for prosperity and disaster prevention. The Fukuno Yotaka Matsuri, a paper lantern parade festival, is held annually from May 1 to 2, while the float parade takes place on May 3.' where id = 'hW1ZuwtqrDKGU5phIIc2Z';
update content_bodies set title = '福野の曳山～上町・七津屋編～', description = '福野には、上町・七津屋（船鉾型曳山）、横町、浦町・辰巳町、新町（以上３基花傘山型曳山）の計４基の曳山が存在します。各曳山の意匠は、上町・七津屋が「神功皇后の西征航海」、横町が「猩々の汲み酒」、浦町・辰巳町が「素戔嗚尊の大蛇退治」、新町が「橋弁慶牛若丸」をテーマにしています。曳山の曳き廻しの開始時期は不明ですが、文政４年（1821）以降の古文書や弘化４年の修繕記録から、文政年間（1818～1830）には各町で曳山が作られ、天保年間（1830～1844）には全ての町の曳山が揃って曳き廻されたと考えられます。享保期（1716～1736）の経済不況時には、神を奉り、町内の繁栄を祈る風習があったと推測され、安永期（1772～1781）には曳山祭りが流行しました。' where id = 'ZQ46wdimcH6GiMk4nvV79';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'In Fukuno, there are four types of float (hikiyama) used in festivals: Kamimachi-Nanatsuya (funahoko type), Yokomachi, Uramachi-Tatsumimachi, and Shinmachi (the last three are hanagasa type). The designs of the floats depict various themes: Kamimachi-Nanatsuya features ''Empress Jingu''s Western Expedition,'' Yokomachi shows ''Shōjō''s Sake Fetching,'' Uramachi-Tatsumimachi illustrates ''Susanoo''s Defeat of the Great Serpent,'' and Shinmachi represents ''Benkei and Ushiwakamaru on the Bridge.'' The exact start date of the float parades is unclear, but historical documents from the Bunsei era (1818-1830) suggest that floats were created in each town, and by the Tenpo era (1830-1844), all four towns participated in the parades. During the Kyōhō period (1716-1736), economic downturns led people to worship deities for prosperity and disaster prevention, and by the An''ei period (1772-1781), float festivals became popular across various regions.' where id = 'eN5gwOeadGow57iEuNXS8';
update content_bodies set title = '福野の曳山～庵唄編～', description = '福野には、上町・七津屋（船鉾型曳山）、横町、浦町・辰巳町、新町（以上３基花傘山型曳山）の計４基の曳山が存在します。各曳山の意匠は、上町・七津屋が「神功皇后の西征航海」、横町が「猩々の汲み酒」、浦町・辰巳町が「素戔嗚尊の大蛇退治」、新町が「橋弁慶牛若丸」となっています。曳山の開始時期は不明ですが、文政４年（1821）以降の古文書や弘化４年の修繕記録から、文政年間には各町で曳山が作られ、天保年間には４町の曳山が揃って曳き廻されたと考えられます。享保期の経済不況時には、神を奉り町内繁栄を祈る動きがあり、安永期には曳山祭りが流行しました。' where id = 'qc-h2kvqETYjh-8Lug6WU';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'In Fukuno, there are four types of float (hikiyama): the Kamimachi and Nanatsuya (funahoko type), Yokomachi, and Urakawachi and Tsumimachi, and Shinmachi (the latter three are hanagasa type). The designs of the floats include ''Empress Jingu''s Western Expedition'' from Kamimachi and Nanatsuya, ''Shōjō''s Sake Fetching'' from Yokomachi, ''Susanoo''s Defeat of the Great Serpent'' from Urakawachi and Tsumimachi, and ''Benkei and Ushiwakamaru on the Bridge'' from Shinmachi. The exact start date of the float parades in Fukuno is unknown, but historical documents from the Bunsei era (1818-1830) suggest that floats were created in each town, and by the Tenpo era (1830-1844), all four towns had their floats ready for parades. During the Kyōhō period (1716-1736), economic downturns led people to worship deities for prosperity and disaster prevention, and by the An''ei period (1772-1781), float festivals became popular across various regions.' where id = 'SGtQ7Ud6GUkTfLvKZehgP';
update content_bodies set title = '福野夜高祭り　～前夜祭（2015/04/30）編～', description = '福野夜高祭りの前夜祭では、夜高行燈の練り回しが行われ、夜高太鼓の音と若衆の掛け声が響き渡ります。4月30日にはJR福野駅前で前夜祭が開催され、文久の大行灯の練り回しが行われます。特に注目すべきは、南砺（福野）を代表するイベント「スキヤキ・ミーツ・ザ・ワールド」との夜高行燈のコラボレーションです。夜高行燈と巨大人形隊の対決が見どころで、夜の南砺を盛り上げます。' where id = 'DQLOCAMJFSyPNgu7U1a-U';
update content_bodies set title = 'Fukuno Yotaka Festival - Pre-Festival (April 30, 2015)', description = 'The pre-festival of the Fukuno Yotaka Festival features the lively procession of Yotaka lanterns, accompanied by the powerful sounds of Yotaka drums and the spirited shouts of the young men. On April 30, a pre-festival event takes place in front of JR Fukuno Station, showcasing the procession of the Bunki large lanterns. This event highlights the collaboration between the representative event of Nanto (Fukuno), ''Sukiyaki Meets the World,'' and the Yotaka lanterns. A particular highlight is the grand confrontation between the Yotaka lanterns and the giant puppet troupe, which adds excitement to the night in Nanto.' where id = 'DwUbqrCJnU0Cp4jjeP86K';
update content_bodies set title = '福野夜高祭り　～引き合い（通称：ケンカ）2015 05 02～', description = '福野夜高祭りの宵祭りでは、夜高行燈の練り回しが行われ、夜高太鼓と若衆の勇ましい掛け声が響き渡ります。最大の見どころは、５月２日の23時頃から始まる呼び物の引合い（ケンカ）です。威勢のいい拍子木とともに、若衆が相手方の行燈を壊し合います。その激しい引合いは、見る者を釘付けにする迫力があります。' where id = 'BxDtyd-Hdqszt3ax57bsq';
update content_bodies set title = 'Fukuno Yotaka Festival - Kenka (Fight) 2015 05 02', description = 'The Fukuno Yotaka Festival features a lively evening celebration where participants parade with Yotaka lanterns, accompanied by the powerful sounds of Yotaka drums and the spirited shouts of the young men. The highlight of the festival occurs around 11 PM on May 2nd, known as the Kenka, where young men fiercely compete to break each other''s lanterns. This intense competition captivates the audience with its thrilling energy.' where id = 'N3qGt5w77dJju0K8Oonfl';
update content_bodies set title = 'なんチャリツアー　～ふくみつ千本桜を愉しむ～　富山県南砺市／南砺市観光協会', description = '2021年4月10日に開催されたなんチャリツアーでは、ふくみつ千本桜の桜並木を自転車で巡る体験が提供されました。桜の見頃は過ぎていましたが、参加者は桜の木の下や商店街の裏路地、田園風景を楽しみながらサイクリングをしました。ツアーでは、地元の豆腐屋や珍しい種麹屋などに立ち寄り、地元の美味しい食べ物を堪能しました。行程には、小矢部川沿いのふくみつ千本桜、懐かしい昭和の新町通り、伝統的な家屋様式が見られる田園風景が含まれていました。地元の特産品として、豆腐や甘酒、かば焼き、季節のジェラートなどが紹介されました。南砺を自転車で探索したい方には、電動アシスト付き自転車のレンタルサービス「なんチャリ」がおすすめです。' where id = 'f_9YyTuhSni0TQGc5ZlHE';
update content_bodies set title = 'Nanchari Tour - Enjoying the Fukumitsu Senbonzakura - Nanto City, Toyama Prefecture / Nanto City Tourism Association', description = 'The Nanchari Tour, held on April 10, 2021, offered a cycling experience through the Fukumitsu Senbonzakura cherry blossom avenue. Although the cherry blossoms had already passed their peak bloom, participants enjoyed cycling under the cherry trees, through back alleys of shopping streets, and across picturesque rural landscapes. The tour included stops at local shops, such as a traditional tofu shop and a unique seed koji maker. The itinerary featured the Fukumitsu Senbonzakura along the Oyabe River, the nostalgic Showa-era New Town Street, and scenic rural views showcasing traditional architectural styles. The tour highlighted local delicacies, including delicious tofu, sweet sake, kabayaki, and seasonal gelato flavors. For those interested in exploring Nanto by bike, the Nanchari rental service offers electric bicycles for a leisurely experience of the area''s beauty and culture.' where id = 'csVSGMD86fMBOyzrxS0_v';
update content_bodies set title = '【公式】南砺サイクリング『なんチャリ』プロモーション動画 （Short ver.）', description = '南砺市、富山県の美しい風景を自転車で楽しむことができるプロモーション動画です。世界遺産の五箇山合掌造り集落や、清流庄川の美しい峡谷、深緑の桂湖、夕日に染まる散居村などが紹介されています。四季折々に変わる南砺の魅力を自転車で体験してみませんか？詳しくは公式旅行サイトやなんチャリのページをご覧ください。' where id = '8UoOxCpBoVEf4Hjp3U-6a';
update content_bodies set title = 'Official Nanto Cycling ''Nanchari'' Promotional Video (Short ver.)', description = 'Explore the beautiful landscapes of Nanto City, Toyama Prefecture, through cycling. The video showcases the World Heritage site of Gokayama with its traditional gassho-zukuri houses, the stunning gorge of Shogawa River, the lush greenery of Lake Katsura, and the sunset over the scattered villages. Experience the changing seasons and the unique charm of Nanto by bike. For more information, visit the official travel site and the Nanchari cycling page.' where id = 'j-8CJxcIntoi9arvIQP8V';
update content_bodies set title = '【公式】南砺サイクリング『なんチャリ』プロモーション動画 （Full ver.）', description = '南砺市、富山県の美しい風景を自転車で楽しむことができるプロモーション動画です。世界遺産の五箇山合掌造り集落や、清流庄川の美しい峡谷、深緑の桂湖、夕日に染まる散居村などが紹介されています。四季折々の表情を持つ南砺の魅力を自転車で体験してみませんか。詳細は「旅々なんと」や「なんチャリ」のページをご覧ください。' where id = 'TdK6Mg3kYKIbQVkv0DYlA';
update content_bodies set title = 'Official Nanto Cycling ''Nanchari'' Promotion Video (Full ver.)', description = 'Explore the beautiful landscapes of Nanto City, Toyama Prefecture, through cycling. The video showcases the World Heritage site of Gokayama with its traditional gassho-zukuri farmhouses, the stunning gorge of Shogawa River, the lush greenery of Lake Katsura, and the picturesque sunset over the scattered villages. Experience the changing seasons and the unique charm of Nanto by bike. For more information, visit the travel site ''Tabi Tabi Nanto'' and the ''Nanchari'' cycling page.' where id = '-pWrM4ptBkdS58jXXZrmm';
update content_bodies set title = '【公式】『なん旅』E-bikeで走る！世界遺産五箇山でサイクリング [25kmライド]', description = '世界遺産五箇山をEバイクで走るガイド付きサイクリングツアーです。Eバイクのアシスト機能により、上り坂も楽に走行できます。参加者には自転車のマナーや乗り方の基本レクチャーがあり、安全に楽しむことができます。心地よい風を感じながら、ガイドブックには載っていない美しい景色や合掌造り集落の暮らしに触れることができる特別なサイクリング体験をお楽しみください。走行距離は約25kmです。南砺をもっと感じる旅に出かけましょう！' where id = '952h798VEQP6p7MRGMiRS';
update content_bodies set title = 'Cycling with E-bike in World Heritage Gokayama [25km Ride]', description = 'Join a guided cycling tour through the World Heritage site of Gokayama using E-bikes. The E-bike''s assist feature makes it easy to tackle uphill rides. Participants will receive basic instructions on cycling etiquette and riding techniques, ensuring a safe experience. Enjoy the refreshing breeze while discovering beautiful landscapes not found in guidebooks and experiencing the unique lifestyle of the gassho-zukuri villages. The total distance for this ride is approximately 25 km. Embark on a journey to feel more of Nanto!' where id = 'leV0Jb7lo38JCgZVbQWtI';
update content_bodies set title = '【2023年版】南砺だから　まるごと酒旅　朝も昼も夜も…２泊３日', description = '2泊3日を通じて、南砺の酒にひたる旅を体験できます。「南砺だから　まるごと酒旅」では、朝、昼、夜、さらには夕暮れ時にも南砺の酒を楽しむことができます。このユニークな旅行体験では、南砺の豊かな酒のバリエーションと地元の料理を堪能できます。伝統的な料理から現代的なペアリングまで、各スポットで記憶に残る試飲体験が待っています。南砺の7つの酒を発見し、この地域を特徴づける地元の味を楽しんでください。' where id = 'bSwDEsJM5lnvOlstv1Sqa';
update content_bodies set title = '2023 Edition: Nanto''s Complete Sake Journey - Morning, Noon, and Night... 2 Nights and 3 Days', description = 'Experience a 2-night, 3-day journey fully immersed in sake. The ''Nanto''s Complete Sake Journey'' offers you the opportunity to enjoy Nanto''s sake at every moment—morning, noon, and night, including the twilight hours. This unique travel experience showcases the rich variety of sake available in Nanto, along with local culinary delights. From traditional dishes to modern pairings, each stop promises a memorable tasting experience. Discover the seven types of sake from Nanto and indulge in the local flavors that define this region.' where id = 'TfGMNlq-ctKVSqkR2NIPd';
update content_bodies set title = 'まるごと酒旅をゆく3', description = 'この動画は、シリーズ「まるごと酒旅をゆく」の第3弾を紹介しています。' where id = 'LotWcauJhQwD8rM8h8DL4';
update content_bodies set title = 'Exploring the Whole Sake Journey 3', description = 'This video introduces the third installment of the series ''Exploring the Whole Sake Journey''.' where id = 'Onv_NFfNn1xYE5OfjtCqw';
update content_bodies set title = 'まるごと酒旅をゆく4', description = 'この動画は、シリーズ「まるごと酒旅をゆく」の第4弾を紹介しています。' where id = '2MoCQkr7VsP9FZnruWJRL';
update content_bodies set title = 'Exploring the Whole Sake Journey 4', description = 'This video introduces the fourth installment of the series ''Exploring the Whole Sake Journey''.' where id = 't92IFfraS2nGJfY3n5oH1';
update content_bodies set title = 'まるごと酒旅をゆく2', description = 'この動画は、まるごと酒旅をゆく2について紹介しています。' where id = 'fi9SU8npdLFvfbSOHS47r';
update content_bodies set title = 'Marugoto Sake Journey 2', description = 'This video introduces Marugoto Sake Journey 2.' where id = 'vyeiIQ-e9HdO4SLCFvep9';
update content_bodies set title = 'まるごと酒旅をゆく1', description = 'この動画は、まるごと酒旅をゆく1について紹介しています。日本の酒文化やその魅力を探求する内容で、視聴者にとって新たな発見があることでしょう。酒の種類や製造過程、地域の特色など、さまざまな視点から日本酒の世界を楽しむことができます。' where id = 'GReTfOetTWv7OYWwzJ0Rq';
update content_bodies set title = 'Exploring the Whole Sake Journey 1', description = 'This video introduces the first part of the whole sake journey.' where id = 'Vu3S2E7sL0DLRiM8YArp8';
update content_bodies set title = '【初夏】南砺だから　まるごと酒旅　朝も昼も夜も…２泊３日', description = '南砺での2泊3日の旅では、酒にひたる体験が待っています。「南砺だから　まるごと酒旅」では、朝、昼、夜、さらには夕暮れ時にも、南砺の酒を存分に楽しむことができます。6つの異なる酒を提供する地元の飲食店で、朝の黒ビールを「おかべ」で、昼の酒おでんを「春乃色食堂」で、夜のマリアージュを「ランソレイエ」で楽しむことができます。2日目は貸切タクシーでの移動があり、スムーズに各地を巡れます。「中の屋」では手製のどぶろくを味わい、「川合田温泉」では古酒とジビエを堪能できます。この旅は、南砺の豊かな酒文化を祝うものです。' where id = 'eBpkHUeXRPVbu2YwKCuA4';
update content_bodies set title = 'Early Summer: A Complete Sake Journey in Nanto - Day and Night... 2 Nights and 3 Days', description = 'Experience a 2-night, 3-day journey dedicated entirely to sake in Nanto. The ''Complete Sake Journey in Nanto'' offers you the opportunity to enjoy local sake at every moment—morning, noon, and night, including the twilight hours. This immersive experience showcases six different types of sake, with various tasting opportunities at local establishments. From morning black beer at ''Okabe'' to lunchtime oden at ''Harunoiro Shokudo'', and evening pairings at ''Ransoleil'', each venue provides a unique sake experience. The itinerary includes a private taxi for day two, allowing for seamless travel between locations. Enjoy handcrafted sake at ''Nakanoya'' and indulge in aged sake and game meat at ''Kawaida Onsen''. This journey is a celebration of Nanto''s rich sake culture.' where id = '-rnFvbEfEbPtL4EZS0Cjz';
update content_bodies set title = '南砺だから　まるごと酒旅　朝も昼も夜も…２泊３日', description = '南砺での2泊3日、酒にひたる旅を体験しませんか。「南砺だから　まるごと酒旅」では、朝、昼、夜、さらには夕暮れ時にも南砺の酒を楽しむことができます。この旅では、6つの異なる酒を体験します。朝は「おかべ」で黒ビール、昼は「春乃色食堂」でおでんと共に昼酒、そして「ランソレイエ」でのマリアージュ、さらに「清水や」でのどじょう串、最後に「nomi」での貸切ハッピーアワーを楽しめます。2日目は貸切タクシーで「かずら」へ行き、フルボトルと果実を味わい、「中の屋」で手製のどぶろく、そして「川合田温泉」で古酒とジビエを堪能します。6つの蔵の息遣いを感じる特別な旅です。' where id = 'HTbZbutm--GnWrv7TgHMC';
update content_bodies set title = 'Nanto''s Complete Sake Journey: Two Nights and Three Days of Sake', description = 'Experience a two-night, three-day journey dedicated entirely to sake in Nanto. The ''Complete Sake Journey'' offers you the opportunity to enjoy Nanto''s sake at every moment—morning, noon, and night, including the twilight hours. This immersive experience allows you to explore six different types of sake, starting with black beer in the morning at ''Okabe,'' followed by lunchtime sake with oden at ''Harunoiro Shokudo.'' Enjoy a pairing at ''Ransoleil,'' savor delicious loach skewers at ''Shimizuya,'' and have a private happy hour at ''Nomi.'' On the second day, travel in a private taxi to ''Kazura'' for full bottles and fruits, then to ''Nakanoya'' for handmade doburoku, and finally to ''Kawaidain Onsen'' for aged sake and game meat. Discover the essence of six breweries throughout this unique journey.' where id = 'P_Pgg8m9hihl848mqMNOk';
update content_bodies set title = '【福井県高浜町】高浜町をめぐる週末', description = 'カメラを持って福井県高浜町を訪れた女子のひとり旅を紹介します。この旅は「人と関わり、自然と触れ合い、美味しいものを食べて思い出を記録する」ことをテーマにしたリトリートで、癒しに満ちた高浜町を巡ります。訪れる場所には、和田路地、若狭和田ビーチ、海沿いの遊歩道、城山公園、音海大断崖、UMIKARA、日引の棚田、青葉山登山、青葉山ハーバルビレッジなどがあります。出演者には素人カメラ女子、青葉山登山ガイド、地元農家の人々、和田地区の子供たち、音海大断崖の漁船クルーズを行う啓福丸が含まれています。高浜町の協力を得て、Funa film＆Photo worksが制作しました。' where id = '-7o1mVmh-4oi5bHI_qypt';
update content_bodies set title = 'Weekend in Takahama Town, Fukui Prefecture', description = 'This is a solo trip to Takahama Town in Fukui Prefecture, captured through the lens of a camera. The journey is a retreat filled with various forms of healing, focusing on connecting with people, engaging with nature, and enjoying delicious food while documenting memories. The trip includes visits to several locations such as Wada Alley, Wakasa Wada Beach, a seaside promenade, Shiroyama Park, the Oumi Grand Cliff, UMIKARA, Hibiki Rice Terraces, Aobayama Mountain, and Aobayama Herbal Village. Special thanks to the amateur camera girl, Aobayama mountain guide, local farmers, children from Wada area, and the Keifukumaru fishing boat cruise at Oumi Grand Cliff. The project is supported by Takahama Town and produced by Funa Film & Photo Works.' where id = 'ClaMHMEzHjy8ntokygtaf';
update content_bodies set title = 'ZENとの再接続', description = '若狭高浜は海辺の自然の楽園であり、秋と冬の季節における魅力と美しさを紹介するプロモーション動画が制作されています。豊かな自然と文化に恵まれた高浜は、自分自身と再接続し、探索するのに最適な場所です。' where id = '4jgW2OmyVbAoyAcVeClwC';
update content_bodies set title = 'Reconnect with your ZEN', description = 'Wakasa Takahama is a natural haven by the sea, highlighted in a promotional video that showcases its charm and beauty during the autumn and winter seasons. With its abundant nature and rich culture, Takahama offers a perfect opportunity for exploration and self-reconnection.' where id = 'AYpRLfIESr5Tqouiz1K8N';
update content_bodies set title = '函館市の春と夏の観光', description = 'この動画では、函館市における春と夏の観光スポットやアクティビティについて紹介しています。美しい自然や文化的な魅力が詰まった函館の魅力を感じることができる内容です。' where id = 'Ukr2ShmGieUO1t49BjmVD';
update content_bodies set title = 'Sightseeing in Hakodate City ~Spring and Summer~', description = 'This video introduces sightseeing in Hakodate City during the spring and summer seasons.' where id = 'n3yFgP8cAd7-xpfaX2hKF';
update content_bodies set title = '【福井県高浜町】白浜海水浴場・鳥居浜海水浴場', description = '白浜海水浴場と鳥居浜海水浴場は、美しい青い海が魅力の海水浴場です。お子様連れのファミリーにぴったりの広さの砂浜があり、その背後には松原が広がっています。波が穏やかで、磯遊びができる岩場もあり、小さなお子様を持つ家族に特に人気があります。' where id = 'RyiYVVQx3KV9SF-nYQ4Wz';
update content_bodies set title = 'Shirahama Beach/Toriihama Beach in Takahama, Fukui Prefecture', description = 'Shirahama Beach and Toriihama Beach are beautiful seaside spots known for their blue waters. They feature spacious sandy beaches that are perfect for families with children, and behind the beaches, there are pine groves. The waves are gentle, making it a popular destination for families with small children, who can also enjoy exploring the rocky areas for tide pooling.' where id = 'vc2plFS1lshoy4rjtjqnW';
update content_bodies set title = '【福井県高浜町】青葉山登山', description = '青葉山はその美しい山容から「若狭富士」とも呼ばれ、高浜町のシンボルです。東峰（693m）と西峰（692m）の2つの峰があり、初心者から上級者まで楽しめる多様な登山道があります。各ポイントからの絶景や、約500種類の有用植物が自生しており、希少な植物にも出会えることができます。この動画は英語でナレーションされており、青葉山の魅力を存分に感じられます。' where id = 'wKlR81U4bxeE83vWMCSgp';
update content_bodies set title = 'Aoba Mountain Climbing in Takahama, Fukui Prefecture', description = 'Mt. Aoba, also known as ''Wakasa Fuji'' due to its beautiful shape, is a symbol of Takahama town. It features two peaks, the East Peak (693m) and the West Peak (692m), offering a variety of trails that cater to both beginners and advanced hikers. The mountain is renowned for its stunning viewpoints and is home to around 500 species of useful plants, including rare flora. The video, narrated in English, captures the charm of Mt. Aoba.' where id = 'cXFcrnBQ7DZoMhrFqBYln';
update content_bodies set title = '【福井県高浜町】音海大断崖 漁船クルーズ', description = '福井県の名勝に指定されている音海大断崖は、高さ260mの絶壁で、迫力のあるクルーズでその美しさを間近で楽しむことができます。このクルーズの魅力の一つは、漁船での巡りです。大自然の中での特別な体験を提供し、訪れる人々に感動を与えます。' where id = 'qi9gRM21P-IwOCsJuee9P';
update content_bodies set title = 'Oumi Great Cliff Fishing Boat Cruise in Takahama, Fukui Prefecture', description = 'Experience the breathtaking views of the Oumi Great Cliff, a designated scenic spot in Fukui Prefecture, standing at 260 meters high. This thrilling cruise allows you to get up close to the towering cliffs, offering a unique perspective of this natural wonder. One of the highlights of the cruise is the opportunity to explore the area aboard a fishing boat, adding to the charm of the experience.' where id = 'PfI4UmvYrsk5lwwdpCY_e';
update content_bodies set title = '福井県高浜町のSUPマリンアクティビティ', description = '高浜町の名勝「明鏡洞」や奇岩の風景を楽しみながらSUPを体験してみませんか？波の少ない場所から始めるコースなので、初心者でも安心して参加できます。認定資格を持つインストラクターによるレクチャーを受けながら、透明度の高い高浜の海の上をゆったりと散歩することができます。' where id = 'xwP8MfOD0p3SdIUWsmtnu';
update content_bodies set title = 'SUP Marine Activities in Takahama Town, Fukui Prefecture', description = 'How about enjoying SUP while taking in the scenic views of the famous ''Meikyo Cave'' and unique rock formations in Takahama Town? The course starts in a location with minimal waves, making it safe for beginners! You can take a leisurely stroll on the clear waters of Takahama with guidance from certified instructors.' where id = 'Nz8zh5_H3czZCfXEDPr4i';
update content_bodies set title = '東京からの日帰り旅行（神奈川／箱根）', description = '神奈川県の公式観光ウェブサイトでは、旅行計画を効果的に立てることができます。旅行プランを整理し、個別の旅程を作成し、神奈川や箱根地域の最適な観光コースを見つけることができます。' where id = 'eoG0i4qF8dwUxd5UL-76G';
update content_bodies set title = 'Day Trip from Tokyo (KANAGAWA／HAKONE)', description = 'The official Kanagawa Tourism website helps you plan your trip effectively. You can organize your travel plans, create a personalized itinerary, and discover the best sightseeing courses in the Kanagawa and Hakone areas.' where id = 'KeV4zPVVlZiZS10IQxEJg';
update content_bodies set title = '東京からの日帰り旅行（神奈川／横浜）', description = '神奈川県の公式観光ウェブサイトでは、旅行計画を効果的に立てることができます。旅行のプランを整理し、オリジナルの旅程を作成し、神奈川や横浜エリアのおすすめ観光コースを見つけることができます。' where id = 'McTLwnC6UFoCU9QzHZjBZ';
update content_bodies set title = 'Day Trip from Tokyo (KANAGAWA/YOKOHAMA)', description = 'The official Kanagawa Tourism website helps you plan your trip effectively. You can organize your travel plans, create a personalized itinerary, and discover the best sightseeing courses in the Kanagawa and Yokohama areas.' where id = 'XmVwotwmHvt2djq6bh582';
update content_bodies set title = '東京日帰り旅行 – 神奈川旅行情報 -', description = '神奈川県の公式観光ウェブサイトでは、旅行計画を立てるためのリソースを提供しています。旅行プランを整理し、行程を作成し、神奈川のおすすめ観光コースを見つけることができます。' where id = 'Za30JV6XbgWkoOKBoVAgB';
update content_bodies set title = 'Tokyo Day Trip –Kanagawa Travel Info-', description = 'The official Kanagawa Tourism website provides resources to help you plan your trip. You can organize your travel plans, create an itinerary, and discover the best sightseeing courses in Kanagawa.' where id = 'mwjP7Gcm1TXLJs4Iej7_s';
update content_bodies set title = '福井県・高浜町で最高のサーフィン体験！', description = '青く広がる海と美しい砂浜が広がる高浜町は、サーファーの隠れた楽園です。初心者から上級者まで楽しめる絶景スポットで、波に乗る爽快感を味わうことができます。次の週末は高浜でサーフィンに挑戦してみませんか？コメントやチャンネル登録もお忘れなく！波の音に癒される映像と共に、自然の中で自由を感じましょう。' where id = '7DMvYbY0VIPaqgS-z-jK7';
update content_bodies set title = 'The Best Surfing Experience in Takahama, Fukui Prefecture!', description = 'Takahama, with its expansive blue sea and beautiful sandy beaches, is a hidden paradise for surfers! It''s a breathtaking spot where both beginners and advanced surfers can enjoy the exhilarating feeling of riding the waves. Why not challenge yourself to surf in Takahama next weekend? Don''t forget to comment and subscribe to the channel! 🎥 Experience the soothing sounds of the waves and feel the freedom in nature!' where id = '1KldCVdrZaAEiCWFqrA_2';
update content_bodies set title = '小田原漆器の作り方', description = '神奈川県の熟練した伝統工芸士たちが、小田原漆器の作品について語る動画です。視聴者は、これらの工芸品の魅力を映像を通じて感じることができます。' where id = 'MeckUaT67qZ2OHM5apfQB';
update content_bodies set title = 'How to craft Odawara Lacquerware', description = 'This video features several skilled traditional craftsmen from Kanagawa who discuss their works in Odawara lacquerware. Viewers can appreciate the unique charms of these crafts through the visual presentation.' where id = 'oxpcPfUibUIM_ePPsB0nL';
update content_bodies set title = '神奈川県の伝統工芸【小田原漆器】', description = '小田原漆器は、ゼルコバの木の美しい木目を引き立てるために、生漆を何度も塗り重ねて作られる伝統的な工芸品です。この技法により、素材の特性が際立ち、各作品が独自の魅力を持つようになります。小田原漆器の魅力は、その精巧な製作過程や美的な魅力を紹介するさまざまな動画を通じて感じることができます。' where id = 'x8meIT4xgtdOSkfxKMf5K';
update content_bodies set title = 'Japanese traditional crafts in Kanagawa【ODAWARA LACQUERWARE】', description = 'Odawara lacquerware is a traditional craft that involves repeatedly applying raw lacquer to enhance the natural grain of zelkova wood, resulting in a beautiful finish. The craftsmanship showcases the unique characteristics of the material, making each piece distinct. The charm of Odawara lacquerware can be appreciated through various videos that highlight its intricate production process and aesthetic appeal.' where id = 'Iy8MaxlMuCzT_ln8SGu0B';
update content_bodies set title = '神奈川県の伝統工芸品【箱根寄木細工】', description = '箱根寄木細工は、さまざまな種類の木材の自然な色合いを組み合わせて作られる、精巧な模様が特徴の伝統工芸品です。この工芸品は、木工技術の美しさと熟練度を示し、地域の豊かな文化遺産を反映しています。動画を通じて、箱根寄木細工の独特の魅力とその芸術的価値を感じることができます。' where id = 'Y45UdboBQIEZ-KUd1XUhh';
update content_bodies set title = 'Japanese traditional crafts in Kanagawa【HAKONE YOSEGI ZAIKU】', description = 'Hakone Yosegi Zaiku is a traditional craft from Kanagawa, known for its intricate patterns created by combining the natural colors of various types of wood. This craft showcases the beauty and skill involved in woodworking, reflecting the rich cultural heritage of the region. The video provides an opportunity to appreciate the unique charm of Hakone Yosegi Zaiku and its artistic value.' where id = 'bICn5_B6e6Xg5h-kGbxeH';
update content_bodies set title = '川崎大師平間寺_神奈川での10の楽しみ', description = '東京の南に位置する神奈川県は、多様性とアクセスの良さで知られています。さまざまな魅力的な旅行が楽しめるため、訪れる人々にとって魅力的な目的地となっています。' where id = 'ApqIJGG6BHCXk81Fqx2Yt';
update content_bodies set title = 'Kawasaki Daishi Heikenji Temple_10 things to do in Kanagawa', description = 'Located south of Tokyo, Kanagawa is a prefecture known for its diversity and accessibility. It offers a variety of delightful trips, making it an attractive destination for visitors.' where id = 'M9qDVTiBTCmeSmjXUSVHx';
update content_bodies set title = '工場夜景ジャングルクルーズ_神奈川での10の楽しみ', description = '東京の南に位置する神奈川は、多様でアクセスしやすい都道府県として知られています。さまざまな魅力的な旅行を楽しむことができる、訪れるのに最適な場所です。' where id = 'JpeZrL7kXrrrtvAwq8V83';
update content_bodies set title = 'Factory Night View Jungle Cruise_10 things to do in Kanagawa', description = 'Located south of Tokyo, Kanagawa offers a variety of enjoyable experiences. It is known for being one of Japan''s most diverse and accessible prefectures, making it an ideal destination for travelers.' where id = 'y25DSMyxBkIMVis2MEmCG';
update content_bodies set title = 'KANAGAWA LU-LU-LUN♪ - 湘南エリアで恋に落ちる', description = '「KANAGAWA LU-LU-LUN♪」は、神奈川の魅力的な旅行体験を紹介し、思わず口ずさみたくなるような楽しさを提供します。湘南エリアは、若者文化と鎌倉時代の歴史が共存する場所であり、人気の映画やドラマ、アニメの舞台となった美しいスポットが数多くあります。ロマンチックなデートスポットも豊富で、訪れる人々は湘南の魅力に恋をすることでしょう。主な観光地には、江ノ電、由比ヶ浜、湘南平塚七夕祭り、寺ヶ崎・二宮海岸、小町通り、鶴岡八幡宮、江の島水族館、江の島などがあります。' where id = 'ttQaugI3AX_-FNGKTE6Oh';
update content_bodies set title = 'KANAGAWA LU-LU-LUN♪ - Fall in love in Shonan area', description = 'KANAGAWA LU-LU-LUN♪ highlights the best travel experiences in Kanagawa, designed to evoke joy and nostalgia. The Shonan area uniquely blends youth culture with the historical essence of the Kamakura period. It features numerous scenic spots that have served as backdrops for popular movies, dramas, and anime, making it an ideal romantic getaway. Key attractions include Enoden, Yuigahama, the Shonan Hiratsuka Tanabata Festival, Terugasaki/Ninomiya Coast, Komachi-dori Street, Tsurugaoka Hachimangu, Enoshima Aquarium, and Enoshima itself. Visitors are sure to fall in love with the charm of Shonan.' where id = 'OtdMwQHSbvT87w_YW8LCi';
update content_bodies set title = '大山（東海大学）', description = '東海大学の学生たちは、神奈川県が推進する「新たな観光拠点」の候補地である「大山」の主な魅力を紹介する動画を制作しました。' where id = 'rEhpBdF79ewOo1gS1ySTL';
update content_bodies set title = 'Oyama (Tokai University)', description = 'Students from Tokai University created a video showcasing the main attractions of Oyama, which is being considered as a candidate site for the ''New Bases for Tourism'' initiative promoted by the Kanagawa Prefectural Government.' where id = 'veOU5QmYKiJ0MAg1drUOu';
