update content_bodies set title = '日本三景天橋立　幻想的な空撮動画', description = '天の浮橋神話が残る天橋立を幻想的に撮影した空撮動画です。この動画では、天と地をつなぐ梯子「天橋立」が美しく表現されています。' where id = '-SyMC2ApjslpdSnxTNNZT';
update content_bodies set title = 'Aerial Video of Amanohashidate, One of Japan''s Three Scenic Views', description = 'Amanohashidate, steeped in the myth of the heavenly floating bridge, is captured in a fantastical aerial video. This video showcases the bridge, which was believed to connect heaven and earth.' where id = 'OvbHUzZhNpCt0c9dIItZz';
update content_bodies set title = '生きてるおきなわ 今こそ聖地巡礼編', description = '沖縄は美しい海やおいしい食べ物、温かい島国としてすぐにイメージされるが、それは誤解かもしれない。沖縄には教科書やネットには載っていない独自の文化が溢れている。しかし、その文化に触れるためにはタイミングが必要で、沖縄は365日生きている。生きている沖縄に出会えるのは年に一度だけであり、沖縄は常に変わり続けているが、次の年には変わらないことを願っている。生きている沖縄を知るためには、今日しかない。' where id = 'O3qdTntb-uS_7lm8wBjhU';
update content_bodies set title = 'Be Okinawa 2024: Pilgrimage to Sacred Places', description = 'Okinawa is often associated with beautiful seas, delicious food, and a warm island atmosphere, but this perception can be misleading. The true essence of Okinawa is filled with unique cultures that are not found in textbooks or online. Experiencing this culture requires the right timing, as Okinawa is alive every day of the year. The only opportunity to encounter this vibrant Okinawa is once a year, as it continues to evolve. Each year, Okinawa transforms, yet there is a hope that it will return unchanged the following year. To truly understand the living Okinawa, today is the only chance.' where id = 'EAb96yuMHJMO6JJoeMatf';
update content_bodies set title = '生きてるおきなわ 生きがいに触れる旅編 Short｜Be Okinawa 2024', description = '沖縄は美しい海やおいしい食べ物、あたたかい島国として知られていますが、そのイメージは誤解を招くことがあります。沖縄には教科書やネットには載っていない独自の文化が溢れていますが、それに触れるためにはタイミングが必要です。沖縄は365日生きており、その瞬間にしか出会えない沖縄は年に一度の機会です。沖縄は常に変わり続けており、次の年には変わらないことを願っています。生きている沖縄を知るためには、今日しかないのです。' where id = 'xoDPDtx0_ZctX8voOuyfk';
update content_bodies set title = 'Be Okinawa 2024: A Journey to Experience the Living Essence of Okinawa', description = 'Okinawa is often associated with beautiful seas, delicious food, and a warm island atmosphere, but this perception can be misleading. The true essence of Okinawa is filled with unique cultures that are not found in textbooks or online. Experiencing this culture requires the right timing, as Okinawa is alive every day of the year. The only opportunity to encounter this vibrant Okinawa is once a year, as it continues to evolve. Each year, Okinawa changes, yet there is a hope that it will return unchanged in some aspects. To truly understand the living Okinawa, today is the only day to do so.' where id = 'XZ_nlch0Cyba6Te_aVtpx';
