update content_bodies set title = '函館市觀光 ~美食~', description = 'この動画では、函館市の観光に焦点を当て、美味しい食べ物を紹介しています。函館の美食文化や特産品を通じて、観光客に魅力的なグルメ体験を提供する内容です。' where id = 'wrSs2Bh4oeZZQY509Wdrk';
