update content_bodies set title = '函馆市観光 ~四季~', description = 'この動画は函馆市の四季について紹介しています。函馆市の美しい風景や季節ごとの魅力を映し出し、訪れる人々にその魅力を伝えています。春の桜、夏の緑、秋の紅葉、冬の雪景色など、四季折々の自然の美しさを楽しむことができる函馆市の観光スポットを紹介しています。' where id = 'RQA77hSUigQpje9HGQTkO';
