update content_bodies set title = '函館市観光 ~美食~', description = 'この動画では、函館市の観光スポットや美味しい食べ物について紹介しています。函館は新鮮な海産物や地元の特産品が豊富で、観光とともに美食を楽しむことができます。観光名所と共に、地元のグルメを堪能することができる内容となっています。' where id = 'K_KGIDWS2Z2aXKgGMYvoV';
