update content_bodies set title = '活火山「恵山」PR動画（ショートバージョン）', description = '函館市の東側に位置する活火山「恵山」は、白い噴気を上げる荒々しい山肌と眼下に広がる青い海、さらに季節ごとに変わる美しい景色を楽しむことができます。恵山に関する詳しい情報は、こちらのリンクをご覧ください。' where id = 'bZUfmhAS4jppaxRXSLv6i';
update content_bodies set title = 'Active Volcano ''Esan'' PR Video (Short Version)', description = 'Esan, an active volcano, towers over the eastern side of Hakodate City. Visitors can enjoy the rugged mountain face emitting white fumaroles, the expansive blue sea below, and breathtaking seasonal views.' where id = 'vdNOTLD5wwb0Fn3qzdcVf';
