update content_bodies set title = '函館夜景飛行', description = '輝きの街「函館」。夢見るようなひとときを、あなたに。' where id = '9tt22-cZSOPeP9AWLIbH8';
update content_bodies set title = 'Night flight－Hakodate, Japan', description = 'Hakodate, a city of brilliance, offers you a dreamy experience.' where id = 'yXG0Ds0UrehgQ5CI4gHEj';
update content_bodies set title = 'はじまる、恋。函館', description = '函館に行く方は必見です！港や坂道、教会、夜景など、函館のロマンチックな街並みはカップルに最適です。このガイドでは、函館の人気スポットを紹介し、旅気分を盛り上げること間違いなしです。大切な人と函館を楽しむためのオススメの旅メニューも掲載しています。観光情報やイベント情報については、各リンクをチェックしてください。' where id = 'RQWyotwrE2oJ67F1Uhoqy';
update content_bodies set title = 'A New Beginning of Love in Hakodate', description = 'If you''re planning a trip to Hakodate, this is a must-read! The romantic streets of Hakodate, with its ports, slopes, churches, and night views, are perfect for couples. This guide introduces popular spots in Hakodate that will surely enhance your travel experience. Discover recommended travel itineraries to enjoy Hakodate with your loved one. For more tourist information, visit the Hakodate tourism site, and for event details, check the event page.' where id = 'CuKN43USFlFNjg4guROxF';
update content_bodies set title = '函館市観光ＰＲ映像【30秒】', description = 'この30秒のPRムービーは、春の五稜郭や観光名所、縄文文化など、函館の魅力を凝縮して紹介しています。' where id = '69f0GM5LlA9vgDLdQHSSN';
update content_bodies set title = 'Hakodate City Tourism PR Video [30 seconds]', description = 'This 30-second promotional movie encapsulates the charm of Hakodate, featuring the spring scenery of Goryokaku, tourist attractions, and Jomon culture.' where id = 'NLsB-zF9naNv1dxolwJne';
update content_bodies set title = '新緑の西川町', description = '西川町は山形県のほぼ中央に位置し、名峰月山のふもとに広がる町です。豊かな大自然に囲まれた新緑の美しさを感じる映像をご覧ください。' where id = 'hpsroC5Cbrxwj9OoteX5N';
update content_bodies set title = 'New Greenery in Nishikawa Town', description = 'Nishikawa Town is located almost in the center of Yamagata Prefecture, spreading at the foot of the famous Mt. Gassan. Enjoy the visuals that capture the beauty of the lush greenery surrounded by rich nature.' where id = '340Sp_HM2Eq31UU1LLOV0';
update content_bodies set title = '【サウナ月山】西川町の本気サウナで極上の"ととのい"体験はいかが？', description = '山形県西川町のサウナー町長が本気で作ったサウナを紹介します。リニューアルオープンした水沢温泉館のサウナは、北欧フィンランドの伝統的なスタイルを基にしており、山形県内でも珍しいセルフロウリュを設置しています。月山の雪解け水風呂でクールダウンした後は、大自然の中で外気浴を楽しむことで、最高の"ととのい"体験が得られます。また、『カリーショップくじら』がプロデュースした美味しいサ飯も楽しめます。西川町・水沢温泉館で極上のサウナ体験をしてみませんか？' where id = 'KEkiBzyEKhnOEGzg2_PdI';
update content_bodies set title = 'Experience Ultimate Relaxation at Gassan Sauna in Nishikawa Town', description = 'Introducing a sauna created with passion by the sauna-loving mayor of Nishikawa Town in Yamagata Prefecture! The newly renovated Mizusawa Onsenkan features a sauna based on traditional Finnish designs, including a rare self-rolling feature in Yamagata. After cooling down in the snowmelt water bath from Mount Gassan, enjoy the ultimate relaxation experience with outdoor air baths in nature. Additionally, you can savor delicious meals from ''Curry Shop Kujira'' to complement your sauna experience. Come and enjoy an exceptional sauna experience at Mizusawa Onsenkan in Nishikawa Town!' where id = 'Oyg3WwMF6mFrv0WnN0RVx';
update content_bodies set title = 'トナミ - 興奮が満ちる場所', description = 'トナミ市は設立からわずか20年の新しい都市です。美しい景観、文化、便利さを兼ね備えた魅力的な街であり、トナミの魅力を伝える動画を共有しています。この動画を通じて、トナミ市の素晴らしさを感じていただければと思います。トナミの良さを実感してもらうことが目的です。' where id = 'yteIiFYawprNP_9qYkc9b';
update content_bodies set title = 'Tonami - Where excitement is in full bloom', description = 'Tonami is a vibrant city that has been established for just 20 years. The city boasts beautiful views, rich culture, and convenient amenities. A video showcasing the city''s attractions is available, inviting viewers to experience the charm of Tonami. The aim is to evoke a sense of appreciation for the city, encouraging people to feel how wonderful Tonami is.' where id = '7kG3sh3KzHbrt-FueE4Tg';
update content_bodies set title = '全国のファンを魅了する御料理ふじ居さんへ行ってみたら富山が素晴らしすぎて圧倒されたVlog', description = '3月下旬に富山県を訪れ、事前に予約した飲食店で食事を楽しみました。訪れた場所は『鮨し人』、『つりや東岩瀬』、『KOBO Brewery』、『ピアット スズキ チンクエ』、『大塚屋』、『ベーカリーみや』、そして『御料理ふじ居』です。また、富山県美術館や富岩運河環水公園などの文化的なスポットも訪れました。各地で富山の食文化や美しさを体験し、地域の魅力に圧倒されました。' where id = 'OGFZl8R9Zp33osG_wkKt3';
update content_bodies set title = 'A Vlog Experience at Oryouri Fujii, Captivating Fans Nationwide with the Wonders of Toyama', description = 'In late March, I visited Toyama Prefecture, where I had pre-reserved meals at various restaurants. The places I visited include ''Sushi Shijin'', ''Tsurya Higashi-Iwase'', ''KOBO Brewery'', ''Piato Suzuki Cinque'', ''Otsukaya'', ''Bakery Miya'', and ''Oryouri Fujii''. I also explored cultural sites like the Toyama Prefectural Museum of Art and the Toyama Bay Canal Kansui Park. Each location offered a unique taste of Toyama''s culinary and cultural richness, leaving me overwhelmed by the beauty and charm of the region.' where id = 'OCdd59itCtzj8EtQ6URza';
update content_bodies set title = '3DキャラクターがHiphopを踊りながら群馬の観光名所をご案内します！', description = '群馬の旅は、こんな楽しい場所があったのかと再認識させられるものでした。訪れた場所は『元祖 田丸屋』、『五徳山 水澤観世音』、『伊香保グリーン牧場』、『旅邸 諧暢楼』、『榛名神社』、『少林山 達磨寺』、『原嶋屋総本家』、『白井屋ホテル』、そして『龢（nagi)』です。それぞれの場所が持つ独自の魅力が、群馬の素晴らしさを引き立てています。' where id = 'uhB_zoke0As8zh0qoyRLM';
update content_bodies set title = '3D Characters Guide You Through Gunma''s Tourist Attractions While Dancing Hiphop!', description = 'This trip to Gunma was a delightful rediscovery of its fun attractions. The places visited include ''Ganso Tamaruya'', ''Gotoku Mountain Mizusawa Kannon'', ''Ikaho Green Farm'', ''Tabitei Kaichoro'', ''Haruna Shrine'', ''Shorinzan Daruma Temple'', ''Harajimaya Sohonke'', ''Shiraiya Hotel'', and ''Nagi''. Each location offers unique experiences, showcasing the charm of Gunma.' where id = 'B2F4ynkh5-eHho0Q28GwK';
update content_bodies set title = 'こんなに楽しくて美味しい県だったとは！と驚いた岡山グルメ満喫の旅', description = '岡山の素晴らしさと美味しさに正直驚きました。この旅では、地域の美食を堪能できる厳選された場所を訪れました。倉敷の『パーラー果物小町』、『ホテルグランヴィア岡山』、かやくめしの『弁慶』、『すし屋の日の出』、『かつ丼野村』、『玉野けいりん』、『HOTEL 10』、焼き鳥の『炭ハバキ』、『児島ジーンズストリート』、たこ漁師の専門店『Nanafuku』、『吉備津神社』、『吉備路もてなしの館』、岡山駅近くの『お好み焼き もり』などが特に印象に残りました。' where id = 'mI-1yBnpISJVGs4upH5mZ';
update content_bodies set title = 'A Surprising Journey Through the Delicious Cuisine of Okayama', description = 'I was honestly surprised by how wonderful and delicious Okayama is. This trip featured a selection of places that truly showcased the region''s culinary delights. Highlights included ''Parlor Fruit Komachi'' in Kurashiki, ''Hotel Granvia Okayama'', ''Benkei'' known for its kayaku-meshi, ''Sushi-ya Hinode'', ''Katsudon Nomura'', ''Tamano Keirin'', ''Hotel 10'', ''Sumihabaki'' for yakitori, ''Kojima Jeans Street'', ''Nanafuku'', a specialty shop for octopus fishing, ''Kibitsu Shrine'', ''Kibiji Hospitality Center'', and ''Okonomiyaki Mori'' near Okayama Station.' where id = 'H63biNQCs5-YkJwcEJN6v';
update content_bodies set title = '歌舞伎ダンスのガイド（谷口宏和出演）', description = '歌舞伎は、約400年前に流行した「歌舞伎踊り」と呼ばれるダンスから始まったと言われています。外国楽器による音楽や複雑な物語などの新しい要素が加わることで、歌舞伎は他のエンターテインメントスタイルや文化要素を取り入れた総合的な演劇形式へと成長しました。都市に住む庶民に人気があり、優れた劇作家や俳優たちが新たな創作や洗練をもたらしました。現代日本では、歌舞伎ダンスは歌舞伎から独立し、多くのプロの歌舞伎ダンスパフォーマーが活躍するようになりました。これにより、伝統芸能への関心が高まり、長い時間をかけて達成された技術と限界まで洗練された表現が、伝統芸術の本質を示しています。' where id = '8CMGTbbW_yT1YwYWpt8Kp';
update content_bodies set title = 'Guide to KABUKI Dance featuring Hirokazu Taniguchi', description = 'Kabuki originated as a dance known as kabuki-odori, which was popular around 400 years ago. Over time, it evolved into a comprehensive theatrical form by incorporating music from foreign instruments, intricate narratives, and various cultural elements. Kabuki became a favorite among urban commoners, supported by talented playwrights and actors who contributed to its development. In modern Japan, Kabuki Dance has become a distinct art form, with many professional performers establishing successful careers. This resurgence has captivated audiences and revitalized interest in traditional arts, showcasing a mastery and refinement that epitomizes the essence of Japanese cultural heritage.' where id = 'h7R8U13TvwSujmQCg3KsK';
update content_bodies set title = 'シェラトン鹿児島と妙見石原荘に泊まる２泊3日で鹿児島名物美味尽くしの旅！', description = '今回の旅行記では、訪れた場所を順に紹介しています。『紫光』で寿司を楽しみ、『天文館むじゃき本店』でかき氷を味わい、シェラトン鹿児島に宿泊しました。その他には、『お酒肆』の居酒屋や『鹿児島ラーメン豚とろ 天文館本店』、『ぢゃんぼ餅 平田屋』、『スターバックス 鹿児島仙巌園店』を訪れました。さらに、妙見石原荘に宿泊し、霧島神宮や丸尾滝、蒲生八幡神社境内の大クスを見学しました。著者は鹿児島を何度も訪れていますが、今回は高齢の両親を連れての旅で観光は控えめです。この行程は高齢者でも楽しめる内容になっており、同様の旅行を計画している方々に参考にしていただければ幸いです。' where id = 'yMvFLI8KJ_NBtkFgAjTIj';
update content_bodies set title = 'A 2-Night, 3-Day Culinary Journey in Kagoshima Staying at Sheraton Kagoshima and Myoken Ishihara-so!', description = 'This travelogue details the places visited in order. Highlights include ''Shiko'' for sushi, ''Tenmonkan Mujaki Honten'' for kakigori (shaved ice), and the Sheraton Kagoshima hotel. Other notable stops are ''Osake Shi'' izakaya, ''Kagoshima Ramen Butatoro Tenmonkan Honten'', ''Jambo Mochi Hirataya'', and ''Starbucks Kagoshima Senganen''. The journey continues to Myoken Ishihara-so, with visits to Kirishima Shrine, Maruo Falls, and the giant camphor tree at Kamou Hachiman Shrine. Although the author has visited Kagoshima numerous times, this trip was tailored for their elderly parents, resulting in fewer sightseeing activities. This itinerary is designed to be accessible for those traveling with older companions, providing a helpful reference for similar travelers.' where id = 'vmp7EauPINDeJEbbgwSJ3';
update content_bodies set title = '美味しさに惚れ込み再訪！新潟食材にこだわる大将の握りは格別！', description = '新潟県新発田市にある『鮨 登喜和』は、2年前のYoutube新潟編でも紹介されました。美味しさに惚れ込み、再訪しました。新潟店もオープンしましたが、週末は本店のみ営業のため、こちらに伺いました。つまみも美味しいですが、大将の握りは格別です。私の貧弱なボキャブラリーでは説明しきれませんが、食べればその美味しさが分かるはずです。大将と女将さんも素敵で、その人柄にも惚れ込んでいます。新潟旅行の際は、事前に予約をして極上の鮨を体験してみてください。' where id = 'JBwoboF8YXOLzwhMBAFJr';
update content_bodies set title = 'Deliciousness That Makes You Return! The Chef''s Sushi with a Focus on Niigata Ingredients is Exceptional!', description = 'This sushi restaurant, ''Sushi Tokiwa'', located in Niigata''s Shibata city, was featured in a YouTube segment two years ago. After falling in love with the flavors, I returned for another visit. Although I wanted to check out the new Niigata location, it only operates on weekends, so I went to the main store. The appetizers are delicious, but the chef''s sushi is truly exceptional. My limited vocabulary can''t do it justice, but you''ll understand once you taste it. The chef and his wife are also wonderful people, and I admire their warmth. If you''re traveling to Niigata, be sure to make a reservation and experience this exquisite sushi.' where id = 'pI0tLQJb4PlGvqIhCOrqL';
update content_bodies set title = '季節の風景⑥（城山公園　ボタンザクラ）', description = 'もてぎあいあいチャンネルで放送されている季節の風景の一環として、今回は茂木町市街地に位置する城山公園のボタンサクラを紹介します。城山公園は、桜や彼岸花などが楽しめる茂木町の花の名所の一つです。頂上までの道は狭いため、運転には十分な注意が必要です。花が咲いていない時期でも、茂木町の市街地を一望できる景観が楽しめます。' where id = 'ePgYbV7jqeMusMx6nPn0I';
update content_bodies set title = 'Seasonal Scenery ⑥ (Jyouyama Park - Botan Cherry Blossoms)', description = 'This is a seasonal scenery broadcasted on the Motegi Ai Ai Channel. This time, we present the Botan Cherry Blossoms at Jyouyama Park, located in the city of Motegi. Jyouyama Park is one of the famous flower spots in Motegi Town, known for its cherry blossoms and Higanbana (red spider lilies). Please be cautious while driving as the road to the top is narrow. Even during the off-season for flowers, you can enjoy a panoramic view of the city of Motegi.' where id = '1wll0n0n9-iEf_Lez4iu8';
update content_bodies set title = '福井県随一の名店！日本料理『御料理 一燈』の''’AI恐竜動画添え’’', description = '皆さまこんにちは。北陸新幹線の開通により、東京から福井までの所要時間が3時間になり、便利になりました。今回の旅の目的の一つは、北陸の味を楽しむことです。名店『御料理 一燈』に行ってきました。結論から言うと、とても美味しかったです！素晴らしい体験でしたし、日本酒のラインアップも素晴らしかったです。ウキウキするほどおすすめのお店です！' where id = 'OPxMZmKNPWBVE-ub9DlJf';
update content_bodies set title = 'Fukui''s Premier Restaurant! Japanese Cuisine ''Goryori Itto'' with AI Dinosaur Video', description = 'Hello everyone. With the opening of the Hokuriku Shinkansen, it now takes just three hours to travel from Tokyo to Fukui, making it more convenient. One of the goals of this trip was to enjoy the flavors of the Hokuriku region at the renowned restaurant ''Goryori Itto.'' In short, it was incredibly delicious! The experience was wonderful, and the selection of sake was impressive. This restaurant comes highly recommended!' where id = 'ZMmewzeyW2f8E_COssz3M';
update content_bodies set title = '皮膚に効く硫黄泉！秋田の湯源郷『日景温泉』', description = '皆さまこんにちは。秋の気配を感じるようになり、秋田県の良い温泉に行きました。源泉掛け流しを謳う宿は多いですが、こちらは「皮膚に効く薬湯」として知られる秘湯です。秋田の山中にあり、熊が心配ですが、内湯もあるので安心です。追加料金で利用できる岩盤浴は素晴らしく、ガンに効く玉川温泉を超えるラドン量で、体の芯から温まります。貸切風呂は予約が争奪戦なので、15時のチェックインに合わせて到着し、すぐに予約することをお勧めします。ラウンジでは飲み物やアイスクリームが飲み放題で、快適に過ごせました。' where id = 'k-BN1S-BD9XAJLUxUc-0V';
update content_bodies set title = 'Sulfur Springs Beneficial for Skin! Akita''s Hot Spring Resort ''Hikage Onsen''', description = 'Hello everyone. I finally felt the arrival of autumn, so I decided to visit a great hot spring in Akita Prefecture. While many accommodations boast of flowing spring water, this hidden gem is known as a ''medicinal bath effective for the skin.'' Located in the mountains of Akita, I was a bit worried about bears in this season. Normally, I would feel lucky to have the outdoor bath to myself, but now I find it hard to relax without anyone around! However, there''s an indoor bath for reassurance. Additionally, there is a wonderful stone sauna available for an extra fee, with radon levels surpassing the famous Tamagawa Onsen, allowing for a deep warmth. Reservations for private baths can be made twice, but they are highly competitive, so I recommend arriving right at the 3 PM check-in to secure a spot. The lounge offers unlimited drinks and ice cream, making for a very comfortable stay.' where id = 'WmJL-U5qjvum7IiTzAmzH';
update content_bodies set title = 'いつかの日常が蘇る場所　茂木町', description = '茂木町は懐かしい「あの頃」の雰囲気をそのまま残している場所です。日常から離れ、昭和の情緒を感じるために訪れてみませんか。ここでは急ぐ必要がなく、心地よく温かい空気を味わうことができます。便利さはないかもしれませんが、心が満たされる体験が待っています。栃木県の茂木町で、そんな時代を思い出しに来てください。また、2024年の地域プロモーションアワードで木川剛志賞を受賞したこともお知らせします。' where id = 'L8Xgp3NLPSUqUVymreCFz';
update content_bodies set title = 'A Place Where Everyday Life Resurfaces: Motegi Town', description = 'Motegi Town preserves the nostalgic atmosphere of the past. It invites you to step away from your usual routine and experience the charm of the Showa era. Life here doesn''t rush, allowing you to savor a comforting and warm environment, even if it''s not convenient. Come to Tochigi Prefecture''s Motegi Town to reminisce about those times. The town has received recognition, winning the Kagawa Tsuyoshi Award at the 2024 Regional Promotion Awards for its efforts in promoting local culture and heritage.' where id = '_Pk3rbm_jNzOLLNv0Zxa2';
update content_bodies set title = '夢に終わった鉄路～未成線　長倉線～', description = '未成線である長倉線は、完成しなかった鉄道を象徴しています。この鉄道は、別の世界戦を巡る旅を表現しており、栃木県茂木町に位置しています。幻の長倉線は、実現しなかった夢の象徴として、地域の歴史に刻まれています。' where id = 'YvXMe0ZwUARE44ybD6Mvg';
update content_bodies set title = 'The Dream of the Railway: The Unfinished Nagakura Line', description = 'The Nagakura Line, an unfinished railway, represents a journey through an alternate world of war. Located in Motegi Town, Tochigi Prefecture, this phantom railway remains a symbol of what could have been.' where id = 'rzFYewhFcyfytjS2QB3ON';
update content_bodies set title = '茂木町で、過ごす今日（秋ver.）', description = '茂木町の秋を紹介する素敵な動画が完成しました。秋だからこそ出会えるもてぎのステキがいっぱいです！' where id = 'J19y-mU5Y0HD1Uo0hOMAO';
update content_bodies set title = 'A Day in Motegi Town (Autumn Version)', description = 'A wonderful video showcasing autumn in Motegi Town has been completed. The season brings many delightful experiences unique to Motegi!' where id = 'qfIpgh4mX7WQMr6SD5aIu';
update content_bodies set title = '茂木町季節の風景⑤　逆川沿いの夜桜', description = '道の駅もてぎ東側に位置する水車小屋付近から弾正大橋付近までの河川沿いには、百数十本のシダレザクラとソメイヨシノが植えられています。これらの桜はライトアップされ、薄ピンクに輝く幻想的な風景を楽しむことができます。ライトアップは4月11日までの期間限定で行われています。桜並木の美しい光景をぜひお楽しみください。' where id = '3mFcx0lLJXcaJIn2gC4MO';
update content_bodies set title = 'Night Cherry Blossoms Along Sakukawa', description = 'This description highlights the illuminated cherry blossoms along the riverbank from the watermill near the Motegi East roadside station to the area around the Banjō Bridge. The display features over a hundred weeping cherry trees and Somei Yoshino cherry trees, creating a magical scene with their soft pink glow. The light-up event is available for a limited time until April 11. Enjoy the enchanting view of the cherry blossom avenue illuminated by lights!' where id = 'OiZuJbi829AWAb9-IOEzF';
update content_bodies set title = '茂木町の季節の風景③　紅梅（烏生田地区）', description = '茂木町の烏生田地区に咲く紅梅の様子について述べています。' where id = 'zpgBY0WCOA_ZOkbZm8okU';
update content_bodies set title = 'Seasonal Scenery of Motegi Town: Red Plum Blossoms (Kushida Area)', description = 'This text describes the appearance of red plum blossoms blooming in the Kushida area of Motegi Town.' where id = '_J1ksWHZc78rszLnEtmIg';
update content_bodies set title = '茂木町の季節の風景①・ロウバイ（城山公園）', description = '城山公園のロウバイが見ごろを迎えています。甘いかおりが漂い、訪れる人々を楽しませています。ただし、周辺の道路が狭いため、車でお越しの際は十分に注意が必要です。' where id = '2fasJjGfA1inZ3-ikR4Id';
update content_bodies set title = 'Seasonal Scenery of Motegi Town: Wintersweet (Shiroyama Park)', description = 'The wintersweet at Shiroyama Park is currently in full bloom, filling the air with a sweet fragrance. Please be cautious when driving to the area, as the surrounding roads are narrow.' where id = 'mIKB4a2lOljhYVfrAoEtQ';
update content_bodies set title = '茂木町の風景　夏（7‐9月）', description = '茂木町の夏の風景は、ブルーベリーやノカンゾウ、道の駅もてぎなど多彩な要素で構成されています。特に馬門の滝やふるさと茂木夏まつりの花火が見どころです。上空からの茂木町の美しい景観が楽しめ、サルスベリやイチジク、リコリスの花も彩りを添えています。また、三坂公民館の花壇も地域の魅力を高めており、チャリティ鮎釣り大会は地域の交流を促進するイベントとなっています。' where id = 'l_26ZhZ3lr5H1fRG415h-';
update content_bodies set title = 'Scenery of Motegi Town in Summer (July-September)', description = 'The summer scenery of Motegi Town features various elements such as blueberries, daylilies, and the Motegi roadside station. Notable attractions include the Makado Falls and the hometown Motegi Summer Festival fireworks. Aerial views of Motegi Town showcase its beauty, complemented by the presence of crape myrtle, figs, and lycoris flowers. Additionally, the Misaka Community Center garden adds to the local charm, while the charity ayu fishing tournament highlights community engagement.' where id = 'dg27swSaH6zOpMeKNo_DN';
update content_bodies set title = '茂木町の景色　春', description = '茂木町の春の景色についての説明です。この町は、春の訪れとともに色とりどりの花々が咲き誇り、爽やかな雰囲気が漂う美しい風景で知られています。訪れる人々は、この時期特有の自然の美しさと絵のような景色を楽しむことができます。' where id = 'MYpE2UTYHLGdhMBM53sMu';
update content_bodies set title = 'Scenery of Mogi Town in Spring', description = 'This description highlights the beautiful scenery of Mogi Town during the spring season. The town is known for its vibrant landscapes, blooming flowers, and the refreshing atmosphere that comes with the arrival of spring. Visitors can enjoy the picturesque views and the natural beauty that characterizes this time of year.' where id = 'admTREYsEZDZlD--TNutt';
update content_bodies set title = '茂木町の風景10～12月', description = '茂木町の風景をお楽しみください。' where id = '8mo3XhA2KpejRYeuf5T7R';
update content_bodies set title = 'Scenery of Motegi Town from October to December', description = 'Enjoy the scenery of Motegi Town.' where id = 'WX20qg6HOsBuV3MV0blR0';
update content_bodies set title = '初桜酒造', description = 'この動画は初桜酒造について紹介しています。' where id = 'nStgpcEa5vPUIin5d-yiS';
update content_bodies set title = 'Hatsuzakura Sake Brewery', description = 'This video introduces Hatsuzakura Sake Brewery.' where id = 'mywnVAHJ1JvfsvlWQTG66';
update content_bodies set title = 'アイアイ今治公式ブランドムービー（3分38秒ver）', description = 'この動画は、アイアイ今治の公式ブランドムービーを紹介しています。' where id = '6AG1UYm3MalfhWJykpVkf';
update content_bodies set title = 'Ai Ai Imabari Official Brand Movie (3 minutes 38 seconds version)', description = 'This video introduces the official brand movie of Ai Ai Imabari.' where id = 'rgj2R70c0LFYJ9aQVIXsg';
update content_bodies set title = '楽山園　春の景色（群馬県甘楽町）', description = '楽山園の「春」の景色を空から4K映像で撮影しました。この庭園は季節ごとに様々な景色を楽しむことができ、ミュージシャンのMVやドラマ、映画のロケ地としても利用されています。楽山園は江戸時代初期に織田氏によって造られた小幡藩邸の庭園で、池泉回遊式の借景庭園です。名前は「知者ハ水ヲ楽シミ、仁者ハ山ヲ楽シム」という論語の故事に由来しています。庭園は西や南の山々を借景とし、広がりのある空間構成が特徴で、庭園美の極みと言えます。また、複数の茶屋が設けられており、織田氏と茶事との深い関連も伺え、歴史的・文化的価値が高い庭園です。' where id = 'CLUSCJGFB6yeXwUVZO_-M';
update content_bodies set title = 'Rakusanyen Spring Scenery (Kanra Town, Gunma Prefecture)', description = 'The spring scenery of Rakusanyen, a garden that offers various views throughout the seasons, has been captured in 4K video from the sky. This location is also used for music videos, dramas, and film shoots. Rakusanyen was created in the early Edo period by the Oda clan as a garden for the Obata domain, featuring a pond-style landscape garden. Its name is derived from a saying in the Analects, meaning ''The wise enjoy water, and the benevolent enjoy mountains.'' The garden showcases a beautiful spatial composition that incorporates the surrounding mountains to the west and south, representing the pinnacle of garden aesthetics. With multiple tea houses, the connection between the Oda clan and tea ceremonies is evident, highlighting the garden''s historical and cultural significance.' where id = 'nZWZvpYXimkWnhFquWLWj';
update content_bodies set title = '【2023夏】高知観光 / 日本最後の清流四万十川で高知を大満喫！', description = '高知県の美しい四万十川は、日本最後の清流として知られています。この旅行ガイドでは、四万十エリアのさまざまな観光スポットやアクティビティを紹介しています。道の駅とおわではジップラインを楽しめ、豚丼が美味しいとおわ食堂や、shimantoおちゃくりcaféもおすすめです。また、四万十カヌーとキャンプの里かわらっこでのカヌー体験や、道の駅よって西土佐のストローベイルSANKANYA、鮎市場も訪れる価値があります。高瀬沈下橋や佐田沈下橋などの名所も紹介されており、さらに四万十市観光協会のHPでカヌー体験ができる施設の情報も確認できます。' where id = 'I3MBelKExl74yjrAlSAtL';
update content_bodies set title = 'Summer 2023: Enjoying Kochi with Japan''s Last Clear Stream, the Shimanto River!', description = 'Discover the breathtaking Shimanto River in Kochi Prefecture, known as Japan''s last clear stream. This travel guide highlights various attractions and activities in the Shimanto area, including the Toowa Road Station with its zipline, Toowa Shokudo for delicious pork rice bowls, and Shimanto Ochakuri Café. Visitors can also enjoy canoeing and camping at Kawarako, explore the Straw Bale SANKANYA, and visit the Ayu Market at the Yotte Nishi Tosa Road Station. The guide features notable locations such as the Takase and Sada sinking bridges, and provides information on additional canoeing facilities in the area. For more details, check the Shimanto City Tourism Association''s website.' where id = 'Wbf3ZaM2BFoUch-trBUSA';
update content_bodies set title = '【Drone空撮映像】甘楽町紅葉山を空から撮影しました！', description = 'この映像は、甘楽町の紅葉山の美しさを空から捉えたもので、特に秋の紅葉シーズンに焦点を当てています。撮影はシーズンの後半に行われ、夕日に照らされた山々の美しい景色が映し出されています。使用したドローンはDJI Phantom 4 Pro V2.0で、編集にはDJI GO4が使用されています。撮影場所は群馬県甘楽町の紅葉山公園で、住所は甘楽郡甘楽町大字善慶寺418-2です。このプロジェクトは、空から町の新たな魅力を発見することを目的としています。チャンネル登録もお忘れなく！' where id = 'ViM0Xw89Pqyhequyukl12';
update content_bodies set title = 'Drone Aerial Footage: Capturing the Autumn Foliage of Kanra Town!', description = 'This video showcases the beauty of Kanra Town from the sky, highlighting the stunning autumn foliage of Momijiyama. The filming was done during the later part of the season, capturing the picturesque mountains bathed in the evening sun. The drone used for this project is the DJI Phantom 4 Pro V2.0, and the editing was done using DJI GO4. The filming location is Kanra Town Momijiyama Park, located at 418-2 Zenkeiji, Kanra Town, Gunma Prefecture. The project aims to reveal new attractions of the town from an aerial perspective. Don''t forget to subscribe to the channel for more videos!' where id = 'yQbQoq3cq2OG98ewPGG1b';
update content_bodies set title = '【Drone空撮映像】稲含山山開き・こいのぼりの里', description = '甘楽町の魅力を空から発見することをコンセプトにした映像が公開されました。5月3日に標高1370mの稲含山が山開きとなり、山頂の様子や稲含神社での太々神楽奉納、那須地区でのこいのぼりの様子が収められています。こいのぼりは4月中旬からゴールデンウィークまで展示されます。撮影にはDJI Phantom 4 Pro V2.0とMavic 2 Proが使用され、Adobe Premiere Pro 2019で編集されています。ビューポイントには稲含山・稲含神社や、那須庵近くの雄川の谷沿いのこいのぼりが含まれています。チャンネル登録もお願いします！' where id = 'tcVCJ0Qcvk2DKsGesrHNq';
update content_bodies set title = 'Drone Aerial Footage: Inagumi Mountain Opening and Koinobori Village', description = 'This video captures the beauty of Kanra Town from above, showcasing the opening of Inagumi Mountain, the highest peak in the area at 1,370 meters, which took place on May 3rd. The footage includes views from the summit, the ritual performance of the Daidai Kagura at Inagumi Shrine, and the colorful koinobori (carp streamers) displayed in the region of Nasu from mid-April to the Golden Week. The filming was done using DJI Phantom 4 Pro V2.0 and Mavic 2 Pro drones, and edited with Adobe Premiere Pro 2019. Viewpoints include Inagumi Mountain and Shrine, as well as the koinobori along the valley of Ougawa near Nasu-an, a soba restaurant in Kanra Town. Don''t forget to subscribe to the channel!' where id = 'pbQrzVTNTljldN3Rc9veq';
update content_bodies set title = '城と名古屋飯を眺めながらのランニングコース', description = '名古屋ウィメンズマラソンは、毎年3月に愛知県で開催される世界最大級の女性マラソンの一つです。この記事では、海外から参加するランナーや愛知県を訪れる人々におすすめのランニングコースや観光スポットを紹介します。レポーターは、愛知県で人気のラジオDJであり、マラソン参加経験のある高木リサさんです。今回は、愛知県の有名な城を眺めながら走れるジョギングコースと観光スポットを紹介します。情報は2023年3月現在のものです。' where id = 'ddL-WPI20b-eqR6OcZgG4';
update content_bodies set title = 'Running trails with a view of a castle and a Japanese food called Nagoyameshi', description = 'The Nagoya Women’s Marathon, one of the largest women’s marathons globally, takes place every March in Aichi Prefecture, Japan. This article introduces recommended running trails and tourist attractions for both participants from abroad and visitors to Aichi. The reporter, Lisa Takagi, a popular radio DJ in Aichi and a marathon participant, highlights a jogging trail that offers views of a famous castle in Aichi and nearby tourist spots. The information is current as of March 2023.' where id = 'm15tMynaeOViw6vE0WR6a';
update content_bodies set title = '【京都 上賀茂神社】新嘗祭　11月23日', description = '京都の上賀茂神社は、最も古い社の一つであり、境内全域が世界遺産に登録されています。平安時代から変わらぬ佇まいを保っています。新嘗祭は11月23日に行われ、宮中では天皇が新穀を天神地祇にお供えし、感謝と祈りを捧げます。全国の神社でも新穀や秋の実りが供えられ、収穫への感謝と皇室の繁栄、国家の安泰が祈られます。現在は勤労感謝の日として祝日ですが、元々は収穫祭である新嘗祭の日です。当神社では11月23日午前10時より新嘗祭が斎行されます。' where id = 'J794I25zqf7doSZ2sU_tu';
update content_bodies set title = 'Shinji Matsuri at Kamigamo Shrine, Kyoto on November 23', description = 'Kamigamo Shrine, one of the oldest shrines in Kyoto, is a UNESCO World Heritage site that has preserved its appearance since the Heian period. On November 23, the Shinji Matsuri is held, where the Emperor offers newly harvested rice to the deities in gratitude and prayer. Across the country, various shrines also present new grains and autumn harvests, expressing gratitude for the harvest and praying for the prosperity of the imperial family and national peace. Although it is now a national holiday known as Labor Thanksgiving Day, it originally served as a harvest festival. The ceremony at Kamigamo Shrine will take place at 10 AM on November 23.' where id = '4vcHp7AE1_Jr32DTTffFG';
update content_bodies set title = 'サイクリングロード', description = '和歌山県伊都郡かつらぎ町に位置するサイクリングロードは、紀の川沿いにあり、豊かな自然を満喫しながら自転車で悠々と走ることができます。' where id = '167edq_v-fdeOFyn7p2T3';
update content_bodies set title = 'Cycling Road', description = 'Located in Katsuragi Town, Iwaki District, Wakayama Prefecture, the Cycling Road along the Kinokawa River offers a chance to enjoy the rich natural surroundings while cycling leisurely.' where id = 'dbRtOMqvrV4NNNTbgQJv-';
update content_bodies set title = '丹生酒殿神社', description = '丹生酒殿神社は、丹生都比賣大神を祀る神社であり、紀の国三谷に降臨されたことから氏神として崇められています。明治6年4月1日に村社に列し、昭和10年6月18日に上天野村の官幣大社丹生都比賣神社の攝社として合併され、戦後に独立しました。丹生都比賣大神は天照大御神の妹で、古代に農耕や織物、料理を教え、特に紀の川の水で酒を醸したことからこの名が付けられました。また、高野御子大神や誉田別大神も祀られており、特に誉田別大神は無病息災や子宝、受験の神として広く信仰されています。' where id = 'YzZr5uCK9iXO_pfHNBcoD';
update content_bodies set title = 'Niu Sakenomi Shrine', description = 'Niu Sakenomi Shrine is dedicated to the deity Niu Tsubaki no Okami, who is revered as the village deity since her descent in Kinokuni Mitani. It was designated as a village shrine on April 1, 1873, and later merged with the Kamibe Yamano Shrine on June 18, 1935, becoming an independent shrine after World War II. Niu Tsubaki no Okami, the younger sister of Amaterasu, is known for teaching agriculture, weaving, and cooking to the people during ancient times. The shrine''s name is derived from her brewing of sake using the waters of the Kii River. The shrine also honors Takayama no Mikoto, believed to be the origin of the name of Mount Koya, and Honda no Wakatoshi, who was enshrined here after being relocated from Kagawa Prefecture. The shrine is widely worshipped for various blessings, including health and fertility.' where id = 'Y0hsTKnkr6Uek-JKC7y4L';
update content_bodies set title = 'ゆめしまサイクル2019 ダイジェスト（90秒）', description = '上島町観光協会が主催する「ゆめしまサイクル2019」のファミリーコースのダイジェスト映像です。この映像では、イベントの様子や参加者の楽しむ姿が収められています。' where id = 'CK5LqJZWJs3VGyp6EJCao';
update content_bodies set title = 'Yumesima Cycle 2019 Digest (90 seconds)', description = 'This is a digest video of the family course from the ''Yumesima Cycle 2019'' event organized by the Ushimachi Tourism Association.' where id = 'wQ8GS7JOcZSpV2ULgyv0s';
update content_bodies set title = '感情 -上島エコツーリズム-', description = '上島町観光協会が主催する「かみじまエコツーリズム」のPRイメージ動画です。かみじまエコツーリズムでは、シーカヤックやSUP、ファミリーキャンプ、電動キックボード、ハイキング、ポタリングなど、さまざまなアウトドアアクティビティを中心にプログラムを提供しています。上島町の美しい自然や、島に流れる時間・空気感、素朴でありのままの魅力をぜひ体感してみてください。' where id = 'hg8zWo_3omyUI18i4pueZ';
update content_bodies set title = 'Feelings -Kamijima EcoTourism-', description = 'This is a promotional image video for ''Kamijima EcoTourism'' organized by the Kamijima Town Tourism Association. Kamijima EcoTourism offers a variety of outdoor activities centered around sea kayaking, stand-up paddleboarding (SUP), family camping, electric kickboarding, hiking, and cycling. Visitors can experience the beautiful nature of Kamijima Town, the unique atmosphere and flow of time on the island, and its simple, authentic charm.' where id = 'EjWVQTQZ3UwWc1iJgag2q';
update content_bodies set title = '【2024高知】海の近くの須崎市で街歩きを楽しもう', description = '海の近くに位置する須崎市の街並みを楽しむことができます。参道が海に面した鳴無神社や、海の近くで味わえる高知グルメ、フォトジェニックなスポットなど、見所がたくさんあります。LOGOS PARK SEASIDE KOCHI SUSAKIや富士ヶ浜、旧三浦邸にあるすさきまちかどギャラリーなど、訪れるべき場所が豊富です。また、海が見える安和駅からの景色も見逃せません。自然と地元文化を楽しむ旅行者にとって、須崎市は理想的な目的地です。' where id = 'r9w-5fXF3QKVaDMt9ZGLW';
update content_bodies set title = 'Explore the Streets of Susaki City Near the Sea in 2024', description = 'Discover the charming streets of Susaki City, located near the sea, where you can enjoy various attractions. Visit the Narukami Shrine, known for its scenic approach facing the ocean, and indulge in local Kochi cuisine at picturesque spots. The area offers a range of experiences, including the LOGOS PARK SEASIDE KOCHI SUSAKI, Fujigahama beach, and the Susaki Machikado Gallery in the former Miura residence. Don''t miss the scenic views from Anwa Station, a station with a view of the sea. This guide highlights the best places to visit in Susaki City, making it a perfect destination for travelers seeking to connect with nature and local culture.' where id = 'hAM_allwLxxSnE48IazmX';
update content_bodies set title = '【高知満喫】2024年の冬旅激推しスポット - 中土佐町・佐川町', description = '冬の旅行を考えている方に、高知県中土佐町と佐川町を強くおすすめします。漁師が船の上で楽しむ地元の料理や、巨大なナウマンゾウなど、魅力的な体験が待っています。また、高知の近代的な建物も見どころです。動画では、久礼大正町市場やとみぃの台所、西村甘泉堂、佐川ナウマンカルスト、旧浜口家住宅、旧青山文庫、ロ481号客車展示施設うえまち駅などのスポットを紹介しています。旅行の計画に役立つGoogleマップのリンクも提供されています。' where id = 'j_aa2MQ01ITwrzI3BE6jI';
update content_bodies set title = 'Recommended Winter Travel Spots in Kochi - Nakatsu Town and Sagawa Town', description = 'If you''re considering a winter trip, I highly recommend Nakatsu Town and Sagawa Town in Kochi Prefecture. Experience unique local cuisine enjoyed by fishermen on their boats and discover the fascinating Naumann elephant! Explore modern architecture in Kochi and enjoy the deep, exciting aspects of the region. The video includes highlights such as Kure Taisho Market, Tomii''s Kitchen, Nishimura Kansen-do, Sagawa Naumann Karst, the former Hamaguchi Residence, the former Aoyama Library, and the Uemachi Station showcasing the RO481 train. A Google Map link is provided for easy navigation.' where id = 'F8Ai8lX_tiGVVCRcoMBPY';
update content_bodies set title = '夢、つながる！ゆめしまエール', description = '愛媛県越智郡上島町を訪れる際には、「夢、つながる！ゆめしまエール」キャンペーンを利用してください。対象の施設を利用すると、弓削のりがプレゼントされます。泊まって、食べて、遊びながら、お得に上島町を満喫できます。詳しくは、こちらをご覧ください→ https://yumeshimayell.net/' where id = 'aSwSRl4xeJ17Y2upn__-G';
update content_bodies set title = 'Dreams Connect! Yumeshima Yell CM', description = 'If you''re traveling to Kamijima Town in Ehime Prefecture, take advantage of the campaign ''Dreams Connect! Yumeshima Yell.'' By using designated facilities, you can receive a gift of Yuge nori (seaweed). Enjoy your stay in Kamijima Town by staying, eating, and playing at a great value. For more details, visit: https://yumeshimayell.net/' where id = 'bSAZcnD_nlexWJb2RaUal';
update content_bodies set title = '【高知旅行2023冬】本山町・土佐町でアクティブなおでかけに【また行きたい！】', description = '高知県の本山町・土佐町で冬の魅力を楽しむ旅を提案します。自然に囲まれたコテージで、土佐あかうしやはちきん地鶏を使ったBBQを味わい、アクティブにサイクリングを楽しむことができます。また、碧い水に囲まれた秘境を探検することも可能です。日常を忘れ、癒しのひとときを過ごすことができるこの旅では、モンベルアウトドアヴィレッジ本山や下津野沈下橋、レストランハーベステラス本山店、汗見川升渕、三樽権現の滝、さめうらレイクタウンなどの見どころがあります。急斜面があるため、動きやすい服装での訪問をお勧めします。' where id = '2f-BnsE6hlUaDwWrghzJ4';
update content_bodies set title = 'Kochi Travel Winter 2023: Active Outings in Motoyama and Tosa Towns', description = 'Experience the winter charm of Kochi Prefecture in Motoyama and Tosa towns! Enjoy BBQ featuring local delicacies like Tosa Akaushi beef and Hachikin chicken, surrounded by nature in cozy cottages. Engage in active cycling adventures and explore hidden gems with stunning blue waters. This trip offers a perfect escape from daily life, providing moments of relaxation and rejuvenation. Key highlights include Montbell Outdoor Village Motoyama, Shimotsuno Sinkabashi Bridge, Harvest Terrace Restaurant, Asamigawa Masubuchi, Mitataru Gongen Falls, and Lake Station Sameura Lake Town. Don''t forget to wear comfortable clothing for the steep terrains!' where id = 'HBalAY60P4Sw3eGYwigqg';
update content_bodies set title = '【高知旅】海を身近に感じる2023【柏島・土佐清水】', description = '高知県西部の土佐清水市と大月町柏島を巡る旅を紹介します。黒潮がもたらす豊かで青い海と絶品グルメを楽しむことができます。主な観光スポットには、竜宮神社、白山洞門、絶景レストランのアズリッシモ、足摺海洋館SATOUMI、大月エコロジーキャンプ場、柏島などがあります。これらのスポットを通じて、自然の美しさと地域の美味しい料理を堪能できる内容となっています。' where id = 'V5SWzx-PXz3vxHdt-Jsey';
update content_bodies set title = 'Kochi Trip: Experience the Sea Up Close 2023 - Kashiwajima & Tosashimizu', description = 'This travel guide explores the western part of Kochi Prefecture, focusing on Tosashimizu City and Kashiwajima in Otsuki Town. It highlights the rich and blue sea brought by the Kuroshio Current, along with exquisite gourmet experiences. Key attractions include the Ryugu Shrine, the Hakusan Cave, the Azzurrissimo restaurant, the SATOUMI Marine Museum, the Otsuki Ecology Campground, and the beautiful Kashiwajima Island. The guide provides a comprehensive overview of these spots, making it an ideal resource for anyone looking to enjoy the natural beauty and culinary delights of this region.' where id = 'bRnU6OmgUi2w6G8c_cye4';
update content_bodies set title = '高知県の海 －SEASCAPES－', description = '高知県の「海」を集めた作品です。高知の海の新しい表情を感じてもらえる内容になっています。撮影は「仁淀ブルー」で知られる高橋宣之さんが担当し、編集はsecondの細木拓也さんが行っています。' where id = '2P-DfEvSihKz5zkNZ4ybN';
update content_bodies set title = 'The Sea of Kochi - SEASCAPES -', description = 'This collection showcases the sea of Kochi Prefecture. It aims to present a new perspective of Kochi''s coastal beauty. The photographs are taken by Nobuyuki Takahashi, known for capturing the ''Niyodo Blue,'' and the editing is done by Takuya Hosoaki from Second.' where id = 'LQqUBF7PnRzgR-_ahgDEM';
update content_bodies set title = '女神湖でSUPやろうよ! 斎藤リョーツさんも遊びに来てくれたよ!', description = '信州たてしなの白樺高原は標高1,530mに位置し、真夏でも湿度が低くカラッとしているため、夏のアクティビティに最適なリゾート地です。特に女神湖は穏やかでちょうど良いサイズで、SUPにぴったりです。ここで練習して上達しましょう！親子やペットと一緒に楽しむこともでき、湖からの蓼科山の眺めは最高です。持ち込みも可能で、湖面使用料と保険代は2時間で1,300円です。レンタルもあり、1艇のレンタルとライフジャケット、保険が含まれています。ガイドツアーも人気で、2時間4,000円で参加できます。' where id = '-3Et1yrKaW9dEGnxBGC46';
update content_bodies set title = 'Let''s SUP at Lake Megami! Saito Ryotsu joined us!', description = 'Shinshu Tateshina''s Shirakaba Highlands, at an elevation of 1,530 meters, offers a dry and comfortable environment even in the summer, making it an ideal resort for summer activities. Lake Megami, with its calm waters and perfect size, is great for Stand-Up Paddleboarding (SUP). It''s a wonderful place to practice and improve your skills! Families and pets can join in the fun, and the view of Mount Tateshina from the lake is spectacular! You can bring your own equipment (lake usage fee and insurance cost is 1,300 yen for 2 hours) or rent equipment (1 boat rental, life jacket rental, and insurance included). Guided tours are also popular, priced at 4,000 yen per person for 2 hours.' where id = 'B13aBO44sQ_0P5V1EN7eP';
update content_bodies set title = '雪と雲海の白×蓼科ブルー', description = '白樺高原の蓼科第二牧場は、秋の雲海スポットとして知られていますが、冬でも条件が合えば雲海を見ることができます。雪原の白と雲海の白、そして晴天率の高い蓼科ブルーの青とのコントラストは非常に美しいです。2020〜21シーズンからは、牛乳専科のもうもうさんも冬季営業を開始します。スキーに行く前に、周辺に宿泊する際は、ぜひ蓼科第二牧場を訪れてみてください。' where id = 'HQMf3SpCog7VRGIbyC1fJ';
update content_bodies set title = 'Snow and Sea of Clouds White × Tateshina Blue', description = 'Tateshina Second Ranch in the Shirakaba Highlands is known as an autumn sea of clouds spot, but it can also be seen in winter under the right conditions! The contrast between the white of the snow, the white of the sea of clouds, and the blue of Tateshina, which has a high rate of clear skies, is stunning! Starting from the 2020-21 season, the milk specialty shop ''Moumou-san'' will also begin winter operations. If you''re staying in the area before heading to ski, be sure to check out Tateshina Second Ranch.' where id = 'g8Rnomyi8ZNzd3oiByqFe';
update content_bodies set title = '朝イチ×紅葉 ミラーレイク@女神湖', description = '白樺高原の紅葉の見頃は毎年10月中旬から11月初旬です。早朝、太陽が昇る前から8時頃までの時間帯は、湖面に紅葉や蓼科山が映る「ミラーレイクタイム」を楽しむことができます。湖面の霧も幻想的で、黄金のカラマツ、白樺湖の黄色い葉と白い樹のコントラストが美しいです。差し色の紅葉が加わり、絶妙な共演を楽しむことができます。' where id = 'BXv1QWOrP7XINqk8UeeL_';
update content_bodies set title = 'Morning and Autumn Foliage at Mirror Lake, Megami Lake', description = 'The best time to view the autumn foliage in the Shirakaba Highlands is from mid-October to early November. Early in the morning, before the sun rises until around 8 AM, visitors can enjoy the ''Mirror Lake Time'' where the lake reflects the autumn colors and Mount Tateshina. The mist on the lake adds a mystical touch. The contrast of golden larch trees, the yellow leaves of Lake Shirakaba, and the white trunks creates a stunning visual experience, enhanced by the vibrant colors of the autumn leaves.' where id = 'pN2BZO9h9x2lIF2NcdwHD';
update content_bodies set title = '蓼科第二牧場は雲海スポット!', description = '毎年9月下旬から11月下旬にかけて、白樺高原の蓼科第二牧場では雲海が見られることが多いです。前日の夜が晴れて放射冷却現象が起こると、雲海が発生する大きなチャンスがあります。見頃は7:30から8:30の間で、佐久平が雲に覆われ、雲を突き抜けて頭を出す浅間山の絶景を楽しむことができます。最高の雲海を体験するために、白樺高原に宿泊することをお勧めします。' where id = 'GIB2fovwGP9_BwZo7NzfG';
update content_bodies set title = 'Tateshina Second Ranch: A Sea of Clouds Spot!', description = 'From late September to late November each year, Tateshina Second Ranch in the Shirakaba Highlands often offers stunning views of a sea of clouds. If the night before is clear, the phenomenon of radiative cooling creates a great opportunity for cloud formation! The best time to see this is between 7:30 and 8:30 AM. You can witness the breathtaking sight of the Saku Plain completely covered by clouds, with Mount Asama peeking through. To experience the best sea of clouds, consider staying in the Shirakaba Highlands!' where id = 'fwNqufcQt9eIV_3OVooDo';
update content_bodies set title = '信州たてしな白樺高原 CM', description = '信州立科町に位置する白樺高原は、広大な自然に囲まれた高原リゾートです。ここには、山野草や野鳥の宝庫である「御泉水自然園」や、湖を見下ろす絶景が楽しめる「女神のそらテラス1830」、白樺湖の「黄金アカシアの森」、そして女神湖があります。真夏の平均気温は22℃で、密にならない屋外アクティビティも充実しています。標高1800mの別天地で、ぜひ遊びに来てください。' where id = 'jUznjewt-XojAqZnZIaWJ';
update content_bodies set title = 'Shinshu Tateshina Shirakaba Kogen CM', description = 'Shirakaba Kogen in Tateshina Town, Nagano, is a highland resort surrounded by vast nature, featuring a treasure trove of wildflowers and birds at the ''Mizusawa Natural Garden.'' Visitors can enjoy breathtaking views from the ''Megami no Sora Terrace 1830'' overlooking a lake, explore the ''Golden Acacia Forest'' by Shirakaba Lake, and relax at Megami Lake. With an average temperature of 22°C in midsummer, the area offers a variety of outdoor activities without crowding. Come and experience this paradise at an altitude of 1800 meters.' where id = 'QWnu5WGA_tefml4RxlYrE';
update content_bodies set title = '4Kで白樺高原の紅葉撮ってみた!', description = '長野県には多くの紅葉スポットがありますが、白樺高原も素晴らしい場所です。カラマツの紅葉は見事で、白樺の黄色と白のコントラストはとても美しいです。今回は、ペンションる・ぐらんの看板犬おはぎちゃんと一緒に女神湖畔を散歩しました。白樺高原の紅葉の見頃は、10月中下旬から11月初旬です。' where id = 'QyCIGgzTM-hZYX9KX2KYl';
update content_bodies set title = 'Capturing Autumn Foliage at Shirakaba Kogen in 4K!', description = 'Nagano Prefecture is known for its many autumn foliage spots, and Shirakaba Kogen is no exception! The larch trees display stunning colors, and the contrast of yellow and white birch trees is simply beautiful. I took a walk along the shores of Lake Megami at Shirakaba Kogen with Ohagi, the beloved dog of Pension Le Grand. The best time to see the autumn leaves at Shirakaba Kogen is from late October to early November.' where id = '7kC2qczTyudpQj-1ik5Pb';
update content_bodies set title = 'e-bikeで目指そう! 白樺高原　#e-Bike #YADEA', description = 'YADEA Nikkiのe-bikeに乗り、立科町の「道の駅女神の里たてしな」から白樺高原の「女神湖」までサイクリングしました。ご褒美として女神湖のりんごソフトを楽しみにしていました。延々と続く登坂に挑戦し、e-bikeのおかげで後ろから押されているような感覚を味わいました。2019年夏には、このe-bikeにGPSナビを付けて、(一社)信州たてしな観光協会でレンタルを開始する予定です。' where id = 'Utgmb17OPGQhy3lMYH3v9';
update content_bodies set title = 'Aim for Shirakaba Highlands with e-bike! #e-Bike #YADEA', description = 'Riding the YADEA Nikki e-bike, I cycled from the ''Michi no Eki Megami no Sato Tateshina'' in Tateshina Town to ''Megami Lake'' in Shirakaba Highlands. I looked forward to enjoying an apple soft serve at Megami Lake as a reward! I took on the endless uphill challenge, and the e-bike made it feel like I was being pushed from behind! In the summer of 2019, we will start renting this e-bike equipped with GPS navigation through the Tateshina Tourism Association.' where id = 'WCh7xI2K-hTIPrsER0fS_';
update content_bodies set title = '360度動画平櫛田中の庭園　５分間日向ぼっこ[VR体験]', description = 'この動画は、東京都小平市にある平櫛彫刻美術館の庭園で日向ぼっこを擬似体験する内容です。春になると梅の花が美しく咲き、訪れる人々を楽しませます。動画はスマートフォンのYouTubeアプリから視聴することをお勧めします。美術館の所在地は東京都小平市学園西町1-7-5で、西武多摩湖線の一橋学園駅から徒歩10分の距離にあります。' where id = 'fQgDYRZGPNDsdHlKwZzAK';
update content_bodies set title = '360° Video of Hirakushi Denchu Garden - 5 Minutes of Sunbathing [VR Experience] Kodaira Tokyo Japan', description = 'This video offers a virtual experience of sunbathing in the garden of the Hirakushi Denchu Sculpture Museum located in Kodaira, Tokyo. The garden is particularly beautiful in spring when the plum blossoms bloom. For the best experience, please watch the video using the YouTube app on your smartphone.' where id = 'oP0XJllhHTEUBznfehD9n';
update content_bodies set title = '東京都小平市/狭山・境緑道の桜を楽しむサイクリング（小平駅〜花小金井駅〜馬の背） [VR対応]', description = '小平グリーンロードは、小平市を一周する水と緑の散歩道で、狭山・境緑道、玉川上水、野火止用水を合わせて21kmの緑道です。春になると、狭山・境緑道は桜のトンネルとなり、小平駅から花小金井駅の間は特に桜を楽しみながら散歩やサイクリングができる名所となります。ぜひ小平にお越しください！この動画は360度VR対応で、スマートフォンのYouTubeアプリでの視聴をお勧めします。' where id = 'NcgTtkgjWZk-xLD4oG4ge';
update content_bodies set title = 'Cycling to Enjoy Cherry Blossoms on the Sayama-Sakai Greenway in Kodaira City, Tokyo [VR Compatible]', description = 'The Kodaira Green Road is a scenic walking path that encircles Kodaira City, featuring a total of 21 km of greenery, including the Sayama-Sakai Greenway, Tamagawa Josui, and Nobidome Yosui. In spring, the Sayama-Sakai Greenway transforms into a tunnel of cherry blossoms, making it a prime spot for walking and cycling between Kodaira Station and Hanakoganei Station. We invite you to visit Kodaira! This video is a 360-degree VR compatible experience, best viewed on the YouTube app on your smartphone.' where id = 'GitOlSuuAXQaB4M4QhPNq';
update content_bodies set title = '【絶景茨城】神磯の鳥居-茨城県大洗町磯前神社', description = '神が降り立った地・神磯に立つ鳥居は、海岸沿いの高台に位置する大洗磯前神社の一つです。この神社は856年に創建され、家内安全や海上交通の守り神として古くから信仰されています。朝日に照らされた鳥居と、太平洋の荒波が岩礁に当たり白く砕ける瞬間は、まさに神々しい光景です。' where id = 'WEQlLN_0cNB9XgP8CXUVG';
update content_bodies set title = 'Spectacular Ibaraki: Torii Gate at Kamiso - Isozaki Shrine in Oarai Town, Ibaraki Prefecture', description = 'The Torii gate at Kamiso, where gods are said to descend, is one of the gates of Isozaki Shrine, located on a high point along the coastline. Established in 856, Isozaki Shrine is a historic shrine that has long been revered as a guardian of family safety and maritime traffic. The moment when the Torii gate is illuminated by the morning sun, and the rough waves of the Pacific crash against the rocky shore, creating a white spray, is truly a divine sight.' where id = 'acgi7XZqOqnPWrmEwpRlE';
update content_bodies set title = '【絶景茨城】鹿島神宮', description = '鹿島神宮は、日本建国・武道の神様である武甕槌大神を御祭神とし、神武天皇元年に創建された由緒ある神社です。現在の社殿は徳川二代将軍の秀忠によって奉納され、奥宮は徳川家康、楼門は水戸初代藩主徳川頼房によって奉納されており、いずれも重要文化財に指定されています。奥参道を進むと、奥宮や鹿園、要石、御手洗池なども見ることができます。' where id = 'LDRR2jofjyExpYGdAtqgJ';
update content_bodies set title = 'Kashima Shrine | VISIT IBARAKI, JAPAN', description = 'Kashima Shrine is a historic shrine founded in the first year of Emperor Jimmu, dedicated to the deity Takemikazuchi no Kami, the god of Japan''s founding and martial arts. The current main hall was donated by Tokugawa Ieyasu''s son, Tokugawa Hidetada, while the inner shrine was contributed by Tokugawa Ieyasu himself, and the gate was donated by Tokugawa Yorifusa, the first lord of Mito. All these structures are designated important cultural properties. As you proceed along the inner approach, you can also see the inner shrine, deer park, sacred stone, and purification pond.' where id = 'bfW_OLuz02nJD7-MvMKgm';
update content_bodies set title = '御岩神社【絶景茨城】', description = '御岩神社は常陸国最古の霊山とされる御岩山の麓に位置しています。鳥居から少し歩くと、日立市で最も大きいとされる御神木「三本杉」が現れます。また、御岩山は縄文時代から信仰の地であり、188の神々が宿るとされています。今も多くの人々が訪れる場所です。' where id = 'zfZlgKcgei66YDvHoulT_';
update content_bodies set title = 'Oiwa Shrine: A Scenic Spot in Ibaraki', description = 'Oiwa Shrine is located at the foot of Oiwa Mountain, known as the oldest sacred mountain in Hitachi Province. A short walk from the torii gate leads to the ''Sanbon-sugi,'' the largest sacred tree in Hitachi City. Oiwa Mountain has been a place of worship since the Jomon period, believed to house 188 deities, and continues to attract many visitors.' where id = '6TG-cIc_PfkC5OuYHT0eN';
update content_bodies set title = '絶景茨城：鹿島臨海工業地帯', description = '茨城県の東南端に位置する鹿島臨海工業地帯は、巨大な工場群が立ち並ぶ壮大な景観を誇ります。2016年2月に撮影されたこの地域の風景は、様々な角度から捉えられており、昼と夜で異なる表情を見せる絶景を楽しむことができます。工業地帯の美しさを体感できるスポットです。' where id = 'r65HnMAl2cQjnGOFgYYZ_';
update content_bodies set title = 'Kashima Coastal Industrial Zone: A Scenic View in Ibaraki', description = 'The Kashima Coastal Industrial Zone, located in the southeastern part of Ibaraki Prefecture, features a stunning landscape filled with massive factories. Captured from various angles, the scenery showcases the industrial beauty of the area. Visitors can enjoy the breathtaking views that change from day to night, highlighting the unique charm of this industrial region.' where id = 'D5zNnrjCiTZ97ZzrhfgeZ';
update content_bodies set title = '【絶景茨城】水郷桜イルミネーション｜VISIT IBARAKI, JAPAN', description = '茨城県土浦市の霞ヶ浦総合公園で行われる「水郷桜イルミネーション」は、茨城県内の代表的なイルミネーションの一つです。冬の透き通った空気の中で、土浦ならではの光のアートを楽しむことができます。' where id = 'VIer4SMNrHFK5yOociI5i';
update content_bodies set title = 'Stunning Ibaraki: Suigo Sakura Illumination | VISIT IBARAKI, JAPAN', description = 'The Suigo Sakura Illumination is one of the prominent illuminations in Ibaraki Prefecture, held at Kasumigaura Comprehensive Park in Tsuchiura City. Enjoy the light art unique to Tsuchiura, shining brightly in the clear winter air.' where id = '3dq4UVoLChR2fH-vdBtKa';
update content_bodies set title = '【絶景茨城】里美の星空', description = '茨城県常陸太田市の里美地区は高原に位置し、空気が澄んでいるため、天気が良く月の無い夜には満天の星空を楽しむことができます。ここでは、天体観測施設を備えた宿泊施設「プラトーさとみ」にて、星の絶景を撮影しました。' where id = 'A91S671dGK9YnGfLiVLIh';
update content_bodies set title = 'Stunning Night Sky in Satomi, Ibaraki | VISIT IBARAKI, JAPAN', description = 'Located in the Satomi area of Hitachiota City, Ibaraki Prefecture, this region is situated on a high plateau, allowing for clear air and excellent visibility of the night sky. On moonless nights, visitors can witness a breathtaking view of countless stars. The stunning celestial scenery was captured at the accommodation facility ''Plateau Satomi,'' which is equipped with astronomical observation facilities.' where id = 'V8OW62SLej3-ZAvPM9uCH';
update content_bodies set title = '【絶景茨城】雨引観音［4K］茨城県桜川市', description = '2015年6月30日に撮影された雨引観音は、安産、子育て、子授け、厄除け、金運などの霊験あらたかな観音様として知られています。荘厳な建築物や歴史的文化財、美しい孔雀が境内を自由に歩き回り、アジサイが彩るこの場所は、観光スポットとしても多くの人々に親しまれています。' where id = 'FoWUTvq0LFCDdzHGH7-uG';
update content_bodies set title = 'Spectacular Ibaraki: Amabiki Kannon [4K] - Sakura City, Ibaraki Prefecture', description = 'Filmed on June 30, 2015, Amabiki Kannon is renowned for its miraculous powers related to safe childbirth, child-rearing, fertility, warding off evil, and financial luck. The site features majestic architecture, historical cultural assets, beautiful peacocks roaming freely, and hydrangeas that adorn the grounds, making it a beloved tourist destination.' where id = 'ti6GKkJ-4gsV-iOcSKmKC';
update content_bodies set title = '【絶景茨城】偕楽園 梅', description = '偕楽園は金沢の兼六園、岡山の後楽園と並ぶ日本三名園の一つで、毎年2月から3月に「水戸の梅まつり」が開催されます。園内には約100品種、3000本の梅があり、春の訪れを告げるように美しく咲き誇ります。様々な品種が揃っているため、「早咲き」「中咲き」「遅咲き」と長期間にわたって観梅を楽しむことができるのも魅力です。' where id = 'h6zLJusfLnOJ0K2uqh0Ji';
update content_bodies set title = 'Kairakuen: A Scenic Spot in Ibaraki - Plum Blossoms', description = 'Kairakuen is one of Japan''s three famous gardens, alongside Kenrokuen in Kanazawa and Korakuen in Okayama. Every year, from February to March, the ''Mito Plum Festival'' is held here. The garden features approximately 100 varieties of plum trees, with around 3,000 trees in total, blooming beautifully to herald the arrival of spring. The variety of plum species allows visitors to enjoy viewing the blossoms over an extended period, with early, mid, and late-blooming types available.' where id = 'S9q-i9TQhRu5pPqyURFXy';
update content_bodies set title = '【2025年最新版】空撮で魅せるネモフィラ＆チューリップ｜茨城・国営ひたち海浜公園【絶景茨城】', description = '国営ひたち海浜公園のネモフィラは、国内外で注目される圧巻の景色を誇ります。この公園の美しいネモフィラの様子を空撮でお届けし、その魅力を余すところなく伝えます。また、同じ時期に楽しめる27万本のチューリップの幻想的な風景も合わせてお楽しみいただけます。ネモフィラの見頃は4月中旬から5月上旬、チューリップは4月中旬から下旬です。' where id = 'oDvjQ7HfyClJ-dN3fdG8K';
update content_bodies set title = '2025 Latest: Aerial Views of Nemophila and Tulips at Hitachi Seaside Park, Ibaraki', description = 'Hitachi Seaside Park, renowned for its breathtaking scenery, showcases the stunning nemophila flowers that attract attention both domestically and internationally. This summary includes aerial footage of the flowers, allowing viewers to appreciate their beauty from above. Additionally, visitors can enjoy the enchanting sight of 270,000 tulips that bloom around the same time. The nemophila is in full bloom from mid-April to early May, while the tulips can be enjoyed from mid to late April.' where id = 'XpgOen73P8vxIIdcN22Bd';
update content_bodies set title = '【日本三名園】偕楽園 茨城県水戸市', description = '偕楽園は水戸藩第九代藩主・徳川斉昭公によって創設された日本三名園の一つです。ニューヨーク市のセントラルパークに次いで、世界で2番目に広い都市公園として知られています。早春には約100品種、3,000本の梅の花が咲き誇り、梅の名所としても有名です。表門から一の木戸を抜けると、孟宗竹や大杉森、クマザサが茂る静かな「陰の世界」が広がり、その先には好文亭があり、見晴らしの良い「陽の世界」が待っています。「陰」から「陽」へと正しい順路で歩くことで、偕楽園の本来の姿を知ることができます。' where id = 'DDCJpquErZghWTnIK4kxx';
update content_bodies set title = 'Kairakuen: One of Japan''s Three Great Gardens in Mito City, Ibaraki Prefecture', description = 'Kairakuen, established by the ninth lord of the Mito Domain, Tokugawa Nariaki, is one of Japan''s three great gardens. It ranks as the second largest urban park in the world, following New York City''s Central Park. In early spring, around 3,000 plum trees of approximately 100 varieties bloom, making it a renowned plum blossom spot. Upon entering through the main gate and passing through the first gate, visitors encounter a serene ''shadow world'' filled with bamboo, ancient cedar trees, and bear grass. Continuing on leads to the ''sunny world'' where the Kobuntei pavilion offers a beautiful view. Walking the correct path from ''shadow'' to ''sun'' allows visitors to fully appreciate the essence of Kairakuen.' where id = 'p3bptJO7Kjr_lqTD2IVO8';
update content_bodies set title = '【絶景茨城】竜神峡・竜神大吊橋', description = '竜神大吊橋は茨城百景の一つで、竜神峡に架かる鉄橋です。橋の長さは375m、ダム湖面からの高さは100mです。橋の上からは四季折々の美しい景色を楽しむことができます。竜神峡は茨城県の奥久慈県立自然公園に位置し、竜神川が谷を侵食して形成されました。' where id = 'wulB7BzlDnk2tu9BPGn7N';
update content_bodies set title = 'Ryujin Gorge and Ryujin Big Suspension Bridge - A Scenic View in Ibaraki', description = 'The Ryujin Big Suspension Bridge is a notable iron bridge spanning the Ryujin Gorge, recognized as one of the top scenic spots in Ibaraki. The bridge measures 375 meters in length and stands 100 meters above the surface of the dam lake. From the bridge, visitors can enjoy breathtaking views that change with the seasons. Ryujin Gorge is located within the Okukuji Prefectural Natural Park in Ibaraki Prefecture, formed by the erosion of the valley by the Ryujin River.' where id = 'j_Af4ZXoYuKQfPPmBaZwi';
update content_bodies set title = '絶景茨城｜思わず息を呑む美しさ（絶景茨城ダイジェスト）', description = '茨城県は春夏秋冬、四季折々の美しさを見せています。その魅力の一部を1分間の動画に収めました。「絶景茨城 -VISIT IBARAKI, JAPAN-」は、4Kやドローンを用いた空撮などの新技術を駆使し、より美しい茨城の魅力を描く番組です。その美しさは映画を観ているかのようで、茨城県民だけでなく他県の方々も茨城の魅力を存分に感じることができます。' where id = 'Jnp4IijT9po2mW_76gNY2';
update content_bodies set title = 'Breathtaking Ibaraki | Stunning Beauty (Ibaraki Scenic Digest)', description = 'Ibaraki Prefecture showcases its beauty through the four seasons, each offering unique expressions. This is captured in a one-minute video. ''Breathtaking Ibaraki - VISIT IBARAKI, JAPAN -'' utilizes new technologies such as 4K and drone aerial photography to depict the allure of Ibaraki in a visually stunning way. The beauty is reminiscent of watching a movie, allowing not only residents of Ibaraki but also visitors from other prefectures to fully appreciate the charm of the region.' where id = 'lXWm-rkmviRNcoQ-Ym_W6';
update content_bodies set title = '【絶景茨城】アクアワールド 茨城県大洗水族館', description = 'アクアワールド茨城は、茨城の海を再現した水族館です。水量1,300トンを誇る「出会いの海の大水槽」では、80種類20,000匹の魚たちと出会うことができます。水族館のシンボルであるサメは、日本一の飼育種類数を誇ります。また、国内最大のマンボウ専用水槽では、のんびりと泳ぐマンボウたちにも出会えます。' where id = 'Awl0Z4Wm2oKYaK1DJBxRo';
update content_bodies set title = 'Aqua World Ibaraki: A Stunning Aquarium in Oarai, Ibaraki Prefecture', description = 'Aqua World Ibaraki recreates the sea of Ibaraki, featuring the ''Encounter Sea Large Tank'' with a water volume of 1,300 tons, home to 80 species and 20,000 fish. The aquarium is renowned for having the largest variety of sharks in Japan. Visitors can also see sunfish swimming leisurely in the country''s largest dedicated sunfish tank.' where id = '3gyxWFMfvwFNHC236P4dS';
update content_bodies set title = '【絶景茨城】ネモフィラ 国営ひたち海浜公園', description = '広大なみはらしの丘では、約530万本のネモフィラが海からの風に揺れています。例年の見ごろは4月中旬から5月上旬で、一面に広がる青の絶景を楽しむことができます。' where id = '3zucw-Zzm9wFJT54kNv6w';
update content_bodies set title = 'Spectacular Ibaraki: Nemophila at Hitachi Seaside Park', description = 'At the vast Miharashi Hill, approximately 5.3 million nemophila flowers sway in the breeze from the sea. The best viewing period is from mid-April to early May, offering visitors a breathtaking view of a sea of blue flowers.' where id = 'VsUE9HIbfoSmkxJiN469J';